{"command":"create","path":"/workspace/backend/internal/app/httpx.go","file_text":"package app

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"time"
)

type apiError struct {
	Status  int
	Code    string
	Message string
}

func (e *apiError) Error() string { return e.Code + ": " + e.Message }

func errf(status int, code string, format string, args ...any) *apiError {
	return &apiError{Status: status, Code: code, Message: fmt.Sprintf(format, args...)}
}

var (
	errUnauthorized  = errf(http.StatusUnauthorized, "unauthorized", "authentication required")
	errForbidden     = errf(http.StatusForbidden, "forbidden", "not permitted for the selected role")
	errNotFound      = errf(http.StatusNotFound, "not_found", "resource not found")
	errRoleNotSet    = errf(http.StatusConflict, "role_not_selected", "an active role must be selected")
	errInternal      = errf(http.StatusInternalServerError, "internal_error", "internal error")
	errInvalidJSON   = errf(http.StatusBadRequest, "invalid_json", "request body is not valid JSON")
	errIdemRequired  = errf(http.StatusBadRequest, "idempotency_required", "idempotencyKey is required")
	errIdemConflict  = errf(http.StatusConflict, "idempotency_conflict", "idempotencyKey reused with a different payload")
	errConcurrent    = errf(http.StatusConflict, "concurrent_conflict", "conflicting concurrent modification")
	errMethod        = errf(http.StatusMethodNotAllowed, "method_not_allowed", "method not allowed")
	errInvalidTime   = errf(http.StatusBadRequest, "invalid_time", "timestamp is not a valid RFC3339 time")
	errStalePlanVers = errf(http.StatusConflict, "stale_plan", "expectedPlanVersion does not match the current plan version")
)

func writeJSON(w http.ResponseWriter, status int, body any) {
	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Cache-Control", "no-store")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(body)
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

func writeErr(w http.ResponseWriter, err error) {
	var ae *apiError
	if !errors.As(err, &ae) {
		ae = errInternal
	}
	msg := ae.Message
	if msg == "" {
		msg = ae.Code
	}
	writeJSON(w, ae.Status, map[string]any{"error": msg, "code": ae.Code})
}

func decodeBody(r *http.Request, dst any) error {
	raw, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
	if err != nil {
		return errInvalidJSON
	}
	if len(raw) == 0 {
		raw = []byte("{}")
	}
	dec := json.NewDecoder(bytesReader(raw))
	if err := dec.Decode(dst); err != nil {
		return errInvalidJSON
	}
	return nil
}

// decodeBodyRaw decodes into dst and also returns the canonical hash of the payload.
func decodeBodyRaw(r *http.Request, dst any) (string, error) {
	raw, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
	if err != nil {
		return "", errInvalidJSON
	}
	if len(raw) == 0 {
		raw = []byte("{}")
	}
	if err := json.Unmarshal(raw, dst); err != nil {
		return "", errInvalidJSON
	}
	var canon any
	if err := json.Unmarshal(raw, &canon); err != nil {
		return "", errInvalidJSON
	}
	stable, _ := json.Marshal(canon)
	sum := sha256.Sum256(stable)
	return hex.EncodeToString(sum[:]), nil
}

func parseTime(value string) (time.Time, error) {
	if value == "" {
		return time.Time{}, errInvalidTime
	}
	t, err := time.Parse(time.RFC3339, value)
	if err != nil {
		t2, err2 := time.Parse(time.RFC3339Nano, value)
		if err2 != nil {
			return time.Time{}, errInvalidTime
		}
		t = t2
	}
	return t.UTC(), nil
}

func parseTimeCode(value string, code string) (time.Time, error) {
	t, err := parseTime(value)
	if err != nil {
		return time.Time{}, errf(http.StatusBadRequest, code, "invalid timestamp %q", value)
	}
	return t, nil
}
