{"command":"create","path":"/workspace/backend/internal/app/server.go","file_text":"package app

import (
	"context"
	"embed"
	"log"
	"net/http"
	"os"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

//go:embed schema.sql
var schemaFS embed.FS

// Config holds runtime configuration for the server.
type Config struct {
	Addr          string
	DatabaseURL   string
	MapAssetsDir  string
	FrontendDir   string
	AdminUsername string
	AdminPassword string
	StaleAfter    time.Duration
	OfferTimeout  time.Duration
}

// Server is the application server.
type Server struct {
	cfg    Config
	pool   *pgxpool.Pool
	mux    *http.ServeMux
	hub    *eventHub
	nowFn  func() time.Time
	planMu sync.Mutex

	svcMu        sync.RWMutex
	svcPublished *serviceabilitySnapshot
}

// LoadConfig builds a Config from the environment.
func LoadConfig() Config {
	addr := os.Getenv("APP_ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	db := os.Getenv("DATABASE_URL")
	if db == "" {
		db = "postgresql://arena:arena@127.0.0.1:5432/arena?sslmode=disable"
	}
	maps := os.Getenv("MAP_ASSETS_DIR")
	if maps == "" {
		maps = "/opt/arena/map-assets"
	}
	front := os.Getenv("FRONTEND_DIR")
	if front == "" {
		front = "frontend/dist"
	}
	return Config{
		Addr:          addr,
		DatabaseURL:   db,
		MapAssetsDir:  maps,
		FrontendDir:   front,
		AdminUsername: os.Getenv("ADMIN_USERNAME"),
		AdminPassword: os.Getenv("ADMIN_PASSWORD"),
		StaleAfter:    5 * time.Minute,
		OfferTimeout:  2 * time.Minute,
	}
}

// New connects to the datastore and prepares the HTTP server.
func New(ctx context.Context, cfg Config) (*Server, error) {
	poolCfg, err := pgxpool.ParseConfig(cfg.DatabaseURL)
	if err != nil {
		return nil, err
	}
	poolCfg.MaxConns = 16
	pool, err := pgxpool.NewWithConfig(ctx, poolCfg)
	if err != nil {
		return nil, err
	}
	s := &Server{
		cfg:   cfg,
		pool:  pool,
		mux:   http.NewServeMux(),
		hub:   newEventHub(),
		nowFn: func() time.Time { return time.Now().UTC() },
	}
	s.routes()
	return s, nil
}

func (s *Server) now() time.Time { return s.nowFn() }

// Migrate creates the schema and seeds reference data.
func (s *Server) Migrate(ctx context.Context) error {
	sql, err := schemaFS.ReadFile("schema.sql")
	if err != nil {
		return err
	}
	if _, err := s.pool.Exec(ctx, string(sql)); err != nil {
		return err
	}
	return s.seedSampleTypes(ctx)
}

// Bootstrap ensures the schema, default sample types and initial administrator exist.
func (s *Server) Bootstrap(ctx context.Context) error {
	if err := s.Migrate(ctx); err != nil {
		return err
	}
	if err := s.ensureInitialAdmin(ctx); err != nil {
		return err
	}
	if err := s.rebuildServiceability(ctx); err != nil {
		return err
	}
	return nil
}

// Handler exposes the HTTP handler.
func (s *Server) Handler() http.Handler { return s.mux }

// Close releases resources.
func (s *Server) Close() { s.pool.Close() }

// Run serves HTTP until the context is cancelled.
func (s *Server) Run(ctx context.Context) error {
	srv := &http.Server{
		Addr:              s.cfg.Addr,
		Handler:           s.mux,
		ReadHeaderTimeout: 20 * time.Second,
	}
	go s.backgroundLoop(ctx)
	go func() {
		<-ctx.Done()
		shutCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = srv.Shutdown(shutCtx)
	}()
	log.Printf("listening on %s", s.cfg.Addr)
	if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		return err
	}
	return nil
}

func (s *Server) backgroundLoop(ctx context.Context) {
	ticker := time.NewTicker(15 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			if err := s.expireStaleOffers(ctx); err != nil {
				log.Printf("offer expiry sweep: %v", err)
			}
		}
	}
}
