{"command":"create","path":"/workspace/backend/internal/app/auth.go","file_text":"package app

import (
	"context"
	"crypto/pbkdf2"
	"crypto/rand"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// Role identifiers used throughout the application.
const (
	RoleAdministrator       = "administrator"
	RoleDispatcher          = "dispatcher"
	RoleRequester           = "requester"
	RoleCollectionPro       = "collection_professional"
	RoleDeliveryPartner     = "delivery_partner"
	RoleNodeHandler         = "node_handler"
	RoleLaboratoryTeam      = "laboratory_team"
	sessionLifetime         = 24 * time.Hour
	pbkdf2Iterations        = 64000
	pbkdf2KeyLength         = 32
	defaultWorkerCapacity   = 4
	declinePenaltyDuration  = 10 * time.Minute
	staleLocationAfter      = 5 * time.Minute
	offerResponseTimeout    = 2 * time.Minute
	qualifiedWaitBeforeFlag = 2 * time.Minute
)

var allRoles = map[string]bool{
	RoleAdministrator:   true,
	RoleDispatcher:      true,
	RoleRequester:       true,
	RoleCollectionPro:   true,
	RoleDeliveryPartner: true,
	RoleNodeHandler:     true,
	RoleLaboratoryTeam:  true,
}

// Certification records a professional certification held by a user.
type Certification struct {
	Code      string  `json:"code"`
	Active    bool    `json:"active"`
	ExpiresAt *string `json:"expiresAt,omitempty"`
}

// User is an application account.
type User struct {
	ID                 uuid.UUID
	Username           string
	PasswordHash       string
	Email              *string
	FullName           *string
	Phone              *string
	Roles              []string
	Qualifications     []string
	Certifications     []Certification
	Active             bool
	AssignedLocationID *uuid.UUID
	Available          bool
	CapacityUnits      int
	DeclineCount       int
	PenaltyUntil       *time.Time
	LastOfferedAt      *time.Time
}

// HasRole reports whether the user holds the given role.
func (u *User) HasRole(role string) bool {
	for _, r := range u.Roles {
		if r == role {
			return true
		}
	}
	return false
}

// HasQualification reports whether the user holds an active qualification code.
func (u *User) HasQualification(code string, at time.Time) bool {
	if code == "" {
		return true
	}
	for _, q := range u.Qualifications {
		if strings.EqualFold(q, code) {
			return true
		}
	}
	return u.hasActiveCertification(code, at)
}

func (u *User) hasActiveCertification(code string, at time.Time) bool {
	for _, c := range u.Certifications {
		if !strings.EqualFold(c.Code, code) || !c.Active {
			continue
		}
		if c.ExpiresAt != nil {
			if exp, err := time.Parse(time.RFC3339, *c.ExpiresAt); err == nil && exp.Before(at) {
				continue
			}
		}
		return true
	}
	return false
}

// CertificationActive reports whether any certification the user holds is currently valid.
func (u *User) CertificationActive(code string, at time.Time) bool {
	if code == "" {
		return true
	}
	if u.hasActiveCertification(code, at) {
		return true
	}
	// A plain qualification entry with no certification record counts as active.
	for _, q := range u.Qualifications {
		if strings.EqualFold(q, code) {
			for _, c := range u.Certifications {
				if strings.EqualFold(c.Code, code) {
					return false
				}
			}
			return true
		}
	}
	return false
}

func hashPassword(password string) string {
	salt := make([]byte, 16)
	_, _ = rand.Read(salt)
	key, err := pbkdf2.Key(sha256.New, password, salt, pbkdf2Iterations, pbkdf2KeyLength)
	if err != nil {
		panic(err)
	}
	return "pbkdf2$" + hex.EncodeToString(salt) + "$" + hex.EncodeToString(key)
}

func verifyPassword(hash, password string) bool {
	parts := strings.Split(hash, "$")
	if len(parts) != 3 || parts[0] != "pbkdf2" {
		return false
	}
	salt, err := hex.DecodeString(parts[1])
	if err != nil {
		return false
	}
	want, err := hex.DecodeString(parts[2])
	if err != nil {
		return false
	}
	got, err := pbkdf2.Key(sha256.New, password, salt, pbkdf2Iterations, pbkdf2KeyLength)
	if err != nil {
		return false
	}
	return subtle.ConstantTimeCompare(want, got) == 1
}

func newToken() string {
	raw := make([]byte, 32)
	_, _ = rand.Read(raw)
	return base64.RawURLEncoding.EncodeToString(raw)
}

// Session is an authenticated session with a selected role.
type Session struct {
	Token      string
	UserID     uuid.UUID
	ActiveRole string
	ExpiresAt  time.Time
}

type requestContext struct {
	Session *Session
	User    *User
	Role    string
}

func (rc *requestContext) actorID() string {
	if rc == nil || rc.User == nil {
		return ""
	}
	return rc.User.ID.String()
}

const userColumns = `id, username, password_hash, email, full_name, phone, roles, qualifications,
    certifications, active, assigned_location_id, available, capacity_units, decline_count,
    penalty_until, last_offered_at`

func scanUser(row pgx.Row) (*User, error) {
	var u User
	var certRaw []byte
	if err := row.Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone,
		&u.Roles, &u.Qualifications, &certRaw, &u.Active, &u.AssignedLocationID, &u.Available,
		&u.CapacityUnits, &u.DeclineCount, &u.PenaltyUntil, &u.LastOfferedAt); err != nil {
		return nil, err
	}
	if len(certRaw) > 0 {
		_ = json.Unmarshal(certRaw, &u.Certifications)
	}
	if u.Certifications == nil {
		u.Certifications = []Certification{}
	}
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	return &u, nil
}

func (s *Server) userByID(ctx context.Context, q querier, id uuid.UUID) (*User, error) {
	u, err := scanUser(q.QueryRow(ctx, `SELECT `+userColumns+` FROM users WHERE id = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errNotFound
	}
	if err != nil {
		return nil, err
	}
	return u, nil
}

func (s *Server) userByUsername(ctx context.Context, username string) (*User, error) {
	u, err := scanUser(s.pool.QueryRow(ctx, `SELECT `+userColumns+` FROM users WHERE lower(username) = lower($1)`, username))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errNotFound
	}
	if err != nil {
		return nil, err
	}
	return u, nil
}

func defaultRole(roles []string) string {
	priority := []string{RoleAdministrator, RoleDispatcher, RoleRequester, RoleCollectionPro,
		RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam}
	if len(roles) == 1 {
		return roles[0]
	}
	for _, p := range priority {
		for _, r := range roles {
			if r == p {
				return p
			}
		}
	}
	if len(roles) > 0 {
		return roles[0]
	}
	return ""
}

// authenticate resolves the bearer [REDACTED] on the request.
func (s *Server) authenticate(r *http.Request) (*requestContext, error) {
	token := bearerToken(r)
	if token == "" {
		return nil, errUnauthorized
	}
	return s.contextForToken(r.Context(), token)
}

func (s *Server) contextForToken(ctx context.Context, token string) (*requestContext, error) {
	var sess Session
	sess.Token = token
	err := s.pool.QueryRow(ctx,
		`SELECT user_id, active_role, expires_at FROM sessions WHERE token = $1`, token).
		Scan(&sess.UserID, &sess.ActiveRole, &sess.ExpiresAt)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errUnauthorized
	}
	if err != nil {
		return nil, err
	}
	if sess.ExpiresAt.Before(s.now()) {
		_, _ = s.pool.Exec(ctx, `DELETE FROM sessions WHERE token = $1`, token)
		return nil, errUnauthorized
	}
	u, err := s.userByID(ctx, s.pool, sess.UserID)
	if err != nil {
		return nil, errUnauthorized
	}
	if !u.Active {
		return nil, errUnauthorized
	}
	role := sess.ActiveRole
	if role != "" && !u.HasRole(role) {
		role = ""
	}
	return &requestContext{Session: &sess, User: u, Role: role}, nil
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(strings.ToLower(h), "bearer ") {
		return strings.TrimSpace(h[7:])
	}
	return ""
}

// requireRole ensures the selected role is one of the accepted roles.
func (rc *requestContext) requireRole(roles ...string) error {
	if rc.Role == "" {
		return errRoleNotSet
	}
	for _, role := range roles {
		if rc.Role == role {
			return nil
		}
	}
	return errForbidden
}

// isOperator reports whether the selected role has dispatcher-level authority.
func (rc *requestContext) isOperator() bool {
	return rc.Role == RoleDispatcher || rc.Role == RoleAdministrator
}

func (s *Server) ensureInitialAdmin(ctx context.Context) error {
	var count int
	if err := s.pool.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	username := s.cfg.AdminUsername
	password := s.cfg.AdminPassword
	if username == "" || password == "" {
		return nil
	}
	id := uuid.New()
	_, err := s.pool.Exec(ctx,
		`INSERT INTO users (id, username, password_hash, full_name, roles, qualifications,
             certifications, active, available, capacity_units)
         VALUES ($1, $2, $3, $4, $5, '{}', '[]', true, true, $6)
         ON CONFLICT (username) DO NOTHING`,
		id, username, hashPassword(password), "Initial Administrator",
		[]string{RoleAdministrator, RoleDispatcher}, defaultWorkerCapacity)
	if err != nil {
		return err
	}
	s.audit(ctx, auditRecord{ActorID: id.String(), Role: RoleAdministrator, Action: "bootstrap_admin",
		EntityType: "user", EntityID: id.String(), Success: true,
		Details: map[string]any{"username": username}})
	return nil
}
