{"command":"create","path":"/workspace/backend/internal/app/audit.go","file_text":"package app

import (
	"context"
	"encoding/json"
	"log"
	"strings"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
)

// querier abstracts the pgx pool and transaction interfaces.
type querier interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
	Query(ctx context.Context, sql string, args ...any) (pgx.Rows, error)
	QueryRow(ctx context.Context, sql string, args ...any) pgx.Row
}

type auditRecord struct {
	ActorID    string
	Role       string
	Action     string
	EntityType string
	EntityID   string
	Success    bool
	OccurredAt time.Time
	Details    map[string]any
}

// TimelineEntry is a single ordered status-history record.
type TimelineEntry struct {
	EventID    int64          `json:"eventId"`
	Action     string         `json:"action"`
	ActorID    string         `json:"actorId"`
	Role       string         `json:"role"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Success    bool           `json:"success"`
	OccurredAt string         `json:"occurredAt"`
	Details    map[string]any `json:"details"`
}

func (s *Server) auditTx(ctx context.Context, q querier, rec auditRecord) {
	if rec.OccurredAt.IsZero() {
		rec.OccurredAt = s.now()
	}
	if rec.Details == nil {
		rec.Details = map[string]any{}
	}
	detailsJSON, _ := json.Marshal(rec.Details)
	search := strings.ToLower(strings.Join([]string{rec.ActorID, rec.Role, rec.Action,
		rec.EntityType, rec.EntityID, string(detailsJSON)}, " "))
	_, err := q.Exec(ctx,
		`INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success,
             occurred_at, details, search_text)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
		rec.ActorID, rec.Role, rec.Action, rec.EntityType, rec.EntityID, rec.Success,
		rec.OccurredAt, detailsJSON, search)
	if err != nil {
		log.Printf("audit write failed (%s): %v", rec.Action, err)
	}
}

func (s *Server) audit(ctx context.Context, rec auditRecord) {
	s.auditTx(ctx, s.pool, rec)
}

// timelineFor loads the ordered audit history for one entity.
func (s *Server) timelineFor(ctx context.Context, q querier, entityType, entityID string) ([]TimelineEntry, error) {
	rows, err := q.Query(ctx,
		`SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
         FROM audit_log WHERE entity_type = $1 AND entity_id = $2
         ORDER BY occurred_at ASC, event_id ASC`, entityType, entityID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	return scanTimeline(rows)
}

// timelineForMany loads the merged ordered audit history for several entities.
func (s *Server) timelineForMany(ctx context.Context, q querier, pairs [][2]string) ([]TimelineEntry, error) {
	if len(pairs) == 0 {
		return []TimelineEntry{}, nil
	}
	types := make([]string, 0, len(pairs))
	ids := make([]string, 0, len(pairs))
	for _, p := range pairs {
		types = append(types, p[0])
		ids = append(ids, p[1])
	}
	rows, err := q.Query(ctx,
		`SELECT event_id, action, actor_id, role, entity_type, entity_id, success, occurred_at, details
         FROM audit_log a
         WHERE EXISTS (
             SELECT 1 FROM unnest($1::text[], $2::text[]) AS f(t, i)
             WHERE a.entity_type = f.t AND a.entity_id = f.i)
         ORDER BY occurred_at ASC, event_id ASC`, types, ids)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	return scanTimeline(rows)
}

func scanTimeline(rows pgx.Rows) ([]TimelineEntry, error) {
	out := []TimelineEntry{}
	for rows.Next() {
		var e TimelineEntry
		var occurred time.Time
		var details []byte
		if err := rows.Scan(&e.EventID, &e.Action, &e.ActorID, &e.Role, &e.EntityType,
			&e.EntityID, &e.Success, &occurred, &details); err != nil {
			return nil, err
		}
		e.OccurredAt = occurred.UTC().Format(time.RFC3339Nano)
		e.Details = map[string]any{}
		if len(details) > 0 {
			_ = json.Unmarshal(details, &e.Details)
		}
		out = append(out, e)
	}
	return out, rows.Err()
}

// RealtimeEvent is a durable event delivered to subscribers.
type RealtimeEvent struct {
	ID         int64          `json:"id"`
	Type       string         `json:"type"`
	EntityType string         `json:"entityType"`
	EntityID   string         `json:"entityId"`
	Payload    map[string]any `json:"payload"`
	CreatedAt  string         `json:"createdAt"`

	audience []string
	userIDs  []uuid.UUID
}

func (s *Server) publishEvent(ctx context.Context, q querier, ev RealtimeEvent) {
	if ev.Payload == nil {
		ev.Payload = map[string]any{}
	}
	if ev.audience == nil {
		ev.audience = []string{}
	}
	if ev.userIDs == nil {
		ev.userIDs = []uuid.UUID{}
	}
	payload, _ := json.Marshal(ev.Payload)
	var id int64
	var createdAt time.Time
	err := q.QueryRow(ctx,
		`INSERT INTO events (type, entity_type, entity_id, payload, audience, user_ids)
         VALUES ($1, $2, $3, $4, $5, $6) RETURNING id, created_at`,
		ev.Type, ev.EntityType, ev.EntityID, payload, ev.audience, ev.userIDs).Scan(&id, &createdAt)
	if err != nil {
		log.Printf("event publish failed (%s): %v", ev.Type, err)
		return
	}
	ev.ID = id
	ev.CreatedAt = createdAt.UTC().Format(time.RFC3339Nano)
	s.hub.broadcast(ev)
}
