{"command":"create","path":"/workspace/backend/internal/app/events.go","file_text":"package app

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
)

type subscriber struct {
	ch     chan RealtimeEvent
	userID uuid.UUID
	role   string
}

type eventHub struct {
	mu   sync.RWMutex
	subs map[*subscriber]struct{}
}

func newEventHub() *eventHub {
	return &eventHub{subs: map[*subscriber]struct{}{}}
}

func (h *eventHub) add(sub *subscriber) {
	h.mu.Lock()
	h.subs[sub] = struct{}{}
	h.mu.Unlock()
}

func (h *eventHub) remove(sub *subscriber) {
	h.mu.Lock()
	if _, ok := h.subs[sub]; ok {
		delete(h.subs, sub)
		close(sub.ch)
	}
	h.mu.Unlock()
}

func (h *eventHub) broadcast(ev RealtimeEvent) {
	h.mu.RLock()
	defer h.mu.RUnlock()
	for sub := range h.subs {
		if !eventVisibleTo(ev, sub.userID, sub.role) {
			continue
		}
		select {
		case sub.ch <- ev:
		default:
		}
	}
}

// eventVisibleTo applies role-addressed delivery: events reach the audience roles that the
// session has currently selected, plus explicitly addressed users.
func eventVisibleTo(ev RealtimeEvent, userID uuid.UUID, role string) bool {
	for _, u := range ev.userIDs {
		if u == userID {
			return true
		}
	}
	if len(ev.audience) == 0 {
		return len(ev.userIDs) == 0
	}
	for _, a := range ev.audience {
		if a == role {
			return true
		}
	}
	return false
}

const eventSubprotocol = "lab-logistics-v1"

var wsUpgrader = websocket.Upgrader{
	Subprotocols:    []string{eventSubprotocol},
	CheckOrigin:     func(r *http.Request) bool { return true },
	ReadBufferSize:  4096,
	WriteBufferSize: 4096,
}

// tokenFromSubprotocols extracts a base64url-encoded `bearer.<token>` subprotocol value.
func tokenFromSubprotocols(r *http.Request) string {
	for _, raw := range websocket.Subprotocols(r) {
		if raw == eventSubprotocol {
			continue
		}
		candidate := raw
		if decoded, err := base64.RawURLEncoding.DecodeString(strings.TrimRight(raw, "=")); err == nil {
			candidate = string(decoded)
		}
		if strings.HasPrefix(candidate, "bearer.") {
			return strings.TrimPrefix(candidate, "bearer.")
		}
	}
	return ""
}

func (s *Server) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeErr(w, errMethod)
		return
	}
	token := bearerToken(r)
	isWebsocket := strings.EqualFold(r.Header.Get("Upgrade"), "websocket")
	if token == "" && isWebsocket {
		token = tokenFromSubprotocols(r)
	}
	if token == "" {
		token = r.URL.Query().Get("access_token")
	}
	if token == "" {
		writeErr(w, errUnauthorized)
		return
	}
	rc, err := s.contextForToken(r.Context(), token)
	if err != nil {
		writeErr(w, errUnauthorized)
		return
	}

	var since int64
	if raw := r.URL.Query().Get("since"); raw != "" {
		parsed, err := strconv.ParseInt(raw, 10, 64)
		if err != nil || parsed < 0 {
			writeErr(w, errf(http.StatusBadRequest, "invalid_json", "since must be a non-negative integer"))
			return
		}
		since = parsed
	}

	if !isWebsocket {
		events, cursor, err := s.replayEvents(r.Context(), since, rc)
		if err != nil {
			writeErr(w, errInternal)
			return
		}
		writeData(w, http.StatusOK, map[string]any{"events": events, "cursor": cursor})
		return
	}

	conn, err := wsUpgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	sub := &subscriber{ch: make(chan RealtimeEvent, 256), userID: rc.User.ID, role: rc.Role}
	s.hub.add(sub)
	defer s.hub.remove(sub)

	replay, cursor, err := s.replayEvents(r.Context(), since, rc)
	if err == nil {
		for _, ev := range replay {
			if err := conn.WriteJSON(ev); err != nil {
				return
			}
		}
		_ = conn.WriteJSON(map[string]any{"type": "cursor", "cursor": cursor})
	}

	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()

	ping := time.NewTicker(25 * time.Second)
	defer ping.Stop()
	for {
		select {
		case <-done:
			return
		case <-r.Context().Done():
			return
		case ev, ok := <-sub.ch:
			if !ok {
				return
			}
			if ev.ID <= cursor {
				continue
			}
			cursor = ev.ID
			if err := conn.WriteJSON(ev); err != nil {
				return
			}
		case <-ping.C:
			if err := conn.WriteControl(websocket.PingMessage, nil, time.Now().Add(5*time.Second)); err != nil {
				return
			}
		}
	}
}

func (s *Server) replayEvents(ctx context.Context, since int64, rc *requestContext) ([]RealtimeEvent, int64, error) {
	rows, err := s.pool.Query(ctx,
		`SELECT id, type, entity_type, entity_id, payload, audience, user_ids, created_at
         FROM events WHERE id > $1 ORDER BY id ASC LIMIT 500`, since)
	if err != nil {
		return nil, 0, err
	}
	defer rows.Close()
	out := []RealtimeEvent{}
	cursor := since
	for rows.Next() {
		var ev RealtimeEvent
		var payload []byte
		var createdAt time.Time
		if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityID, &payload,
			&ev.audience, &ev.userIDs, &createdAt); err != nil {
			return nil, 0, err
		}
		ev.Payload = map[string]any{}
		if len(payload) > 0 {
			_ = json.Unmarshal(payload, &ev.Payload)
		}
		ev.CreatedAt = createdAt.UTC().Format(time.RFC3339Nano)
		cursor = ev.ID
		if !eventVisibleTo(ev, rc.User.ID, rc.Role) {
			continue
		}
		out = append(out, ev)
	}
	return out, cursor, rows.Err()
}
