	}
	defer rows.Close()
	out := []*SampleType{}
	for rows.Next() {
		t, err := scanSampleType(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, t)
	}
	return out, rows.Err()
}

// seedSampleTypes installs the four default named sample types.
func (s *Server) seedSampleTypes(ctx context.Context) error {
	defaults := []SampleType{
		{Name: "Amber", QualifiedCollectorRequired: true, RequiredQualification: "amber_collector",
			ContainerType: "standard", TemperatureMinC: 15, TemperatureMaxC: 30,
			RequiresCooledRoute: false, BatchingAllowed: true},
		{Name: "Indigo", QualifiedCollectorRequired: true, RequiredQualification: "indigo_collector",
			ContainerType: "sealed_vial", TemperatureMinC: 15, TemperatureMaxC: 30,
			RequiresCooledRoute: false, BatchingAllowed: true},
		{Name: "Frost", QualifiedCollectorRequired: true, RequiredQualification: "frost_collector",
			ContainerType: "cooled_box", TemperatureMinC: 2, TemperatureMaxC: 8,
			RequiresCooledRoute: true, BatchingAllowed: true},
		{Name: "Pulse", QualifiedCollectorRequired: true, RequiredQualification: "pulse_collector",
			ContainerType: "standard", TemperatureMinC: 15, TemperatureMaxC: 30,
			RequiresCooledRoute: false, BatchingAllowed: false},
	}
	ids := map[string]uuid.UUID{}
	for i := range defaults {
		d := defaults[i]
		var id uuid.UUID
		err := s.pool.QueryRow(ctx,
			`INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
                 container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
                 requires_cooled_route, batching_allowed)
             VALUES ($1, $2, $3, $4, $5, $6, $7, '{}', $8, $9)
             ON CONFLICT (name) DO UPDATE SET name = sample_types.name
             RETURNING id`,
			uuid.New(), d.Name, d.QualifiedCollectorRequired, d.RequiredQualification,
			d.ContainerType, d.TemperatureMinC, d.TemperatureMaxC,
			d.RequiresCooledRoute, d.BatchingAllowed).Scan(&id)
		if err != nil {
			return err
		}
		ids[d.Name] = id
	}
	// Indigo must not share a container with Amber.
	_, err := s.pool.Exec(ctx,
		`UPDATE sample_types SET incompatible_sample_types = $2 WHERE id = $1`,
		ids["Indigo"], []uuid.UUID{ids["Amber"]})
	if err != nil {
		return err
	}
	_, err = s.pool.Exec(ctx,
		`UPDATE sample_types SET incompatible_sample_types = $2 WHERE id = $1`,
		ids["Amber"], []uuid.UUID{ids["Indigo"]})
	return err
}

func (s *Server) laboratoryAccepts(ctx context.Context, q querier, labID, sampleTypeID uuid.UUID) (bool, error) {
	var accepts bool
	err := q.QueryRow(ctx,
		`SELECT accepts FROM laboratory_acceptance WHERE laboratory_id = $1 AND sample_type_id = $2`,
		labID, sampleTypeID).Scan(&accepts)
	if errors.Is(err, pgx.ErrNoRows) {
		return false, nil
	}
	if err != nil {
		return false, err
	}
	return accepts, nil
}

func (s *Server) acceptedTypesByLab(ctx context.Context, q querier) (map[uuid.UUID][]uuid.UUID, error) {
	rows, err := q.Query(ctx,
		`SELECT laboratory_id, sample_type_id FROM laboratory_acceptance WHERE accepts ORDER BY laboratory_id`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := map[uuid.UUID][]uuid.UUID{}
	for rows.Next() {
		var lab, st uuid.UUID
		if err := rows.Scan(&lab, &st); err != nil {
			return nil, err
		}
		out[lab] = append(out[lab], st)
	}
	return out, rows.Err()
}

func (s *Server) bumpNetworkRevision(ctx context.Context) {
	_, err := s.pool.Exec(ctx,
		`INSERT INTO app_meta (key, value) VALUES ('network_revision', '1'::jsonb)
         ON CONFLICT (key) DO UPDATE
         SET value = to_jsonb((app_meta.value)::int + 1)`)
	if err == nil {
		_ = s.rebuildServiceability(ctx)
	}
}

func (s *Server) networkRevision(ctx context.Context) int {
	var rev int
	err := s.pool.QueryRow(ctx, `SELECT (value)::int FROM app_meta WHERE key = 'network_revision'`).Scan(&rev)
	if err != nil {
		return 0
	}
	return rev
}

func isStale(recordedAt *time.Time, now time.Time) bool {
	if recordedAt == nil {
		return true
	}
	return now.Sub(*recordedAt) > staleLocationAfter
}

func timePtrString(t *time.Time) any {
	if t == nil {
		return nil
	}
	return t.UTC().Format(time.RFC3339Nano)
}
