{"command":"create","path":"/workspace/backend/internal/app/routing.go","file_text":"package app

import (
	"context"
	"sort"
	"time"

	"github.com/google/uuid"
)

// networkGraph is an immutable snapshot of the network used for routing decisions.
type networkGraph struct {
	locations   map[uuid.UUID]*Location
	outgoing    map[uuid.UUID][]*Connection
	connByPair  map[[2]uuid.UUID]*Connection
	acceptedBy  map[uuid.UUID]map[uuid.UUID]bool
	sampleTypes map[uuid.UUID]*SampleType
}

func (s *Server) loadGraph(ctx context.Context, q querier) (*networkGraph, error) {
	locs, err := s.allLocations(ctx, q)
	if err != nil {
		return nil, err
	}
	conns, err := s.allConnections(ctx, q)
	if err != nil {
		return nil, err
	}
	accepted, err := s.acceptedTypesByLab(ctx, q)
	if err != nil {
		return nil, err
	}
	types, err := s.allSampleTypes(ctx, q)
	if err != nil {
		return nil, err
	}
	g := &networkGraph{
		locations:   map[uuid.UUID]*Location{},
		outgoing:    map[uuid.UUID][]*Connection{},
		connByPair:  map[[2]uuid.UUID]*Connection{},
		acceptedBy:  map[uuid.UUID]map[uuid.UUID]bool{},
		sampleTypes: map[uuid.UUID]*SampleType{},
	}
	for _, l := range locs {
		g.locations[l.ID] = l
	}
	for _, c := range conns {
		g.outgoing[c.FromLocationID] = append(g.outgoing[c.FromLocationID], c)
		g.connByPair[[2]uuid.UUID{c.FromLocationID, c.ToLocationID}] = c
	}
	for lab, list := range accepted {
		set := map[uuid.UUID]bool{}
		for _, st := range list {
			set[st] = true
		}
		g.acceptedBy[lab] = set
	}
	for _, t := range types {
		g.sampleTypes[t.ID] = t
	}
	return g, nil
}

func (g *networkGraph) isActiveCollectionPoint(id uuid.UUID) bool {
	l, ok := g.locations[id]
	return ok && l.Active && l.Functions.CollectionPoint
}

func (g *networkGraph) isActiveLaboratory(id uuid.UUID) bool {
	l, ok := g.locations[id]
	return ok && l.Active && l.Functions.Laboratory
}

// canTransit reports whether a sample may move through a location that is not its endpoint.
func (g *networkGraph) canTransit(id uuid.UUID) bool {
	l, ok := g.locations[id]
	if !ok || !l.Active {
		return false
	}
	return l.Functions.TransferPoint || l.Functions.Hub || l.Functions.CollectionPoint || l.Functions.Laboratory
}

// route is a resolved path from a collection node to an accepting laboratory.
type route struct {
	Path          []uuid.UUID
	Connections   []*Connection
	TravelMinutes int
	CostUnits     float64
}

// nearestCollectionPoints returns active collection points within coverage of the origin,
// nearest first. Serviceability requires an origin within 5 km of an active collection node.
func (g *networkGraph) nearestCollectionPoints(origin Coordinate) []*Location {
	type scored struct {
		loc  *Location
		dist float64
	}
	var found []scored
	for _, l := range g.locations {
		if !l.Active || !l.Functions.CollectionPoint {
			continue
		}
		d := haversineKm(origin, l.Coordinate)
		limit := l.CoverageKm
		if limit <= 0 || limit > maxCoverageKm {
			limit = maxCoverageKm
		}
		if d <= limit+1e-9 {
			found = append(found, scored{loc: l, dist: d})
		}
	}
	sort.Slice(found, func(i, j int) bool { return found[i].dist < found[j].dist })
	out := make([]*Location, 0, len(found))
	for _, f := range found {
		out = append(out, f.loc)
	}
	return out
}

const maxCoverageKm = 5.0

// cheapestRoute finds the fastest active path from start to any laboratory accepting sampleType.
// requireCooled restricts the path to cooled connections. It returns nil when none exists.
func (g *networkGraph) cheapestRoute(start uuid.UUID, sampleTypeID uuid.UUID, requireCooled bool) *route {
	type state struct {
		minutes int
		cost    float64
		prev    uuid.UUID
		conn    *Connection
	}
	best := map[uuid.UUID]*state{start: {minutes: 0}}
	visited := map[uuid.UUID]bool{}
	for {
		var current uuid.UUID
		found := false
		bestMinutes := 0
		for id, st := range best {
			if visited[id] {
				continue
			}
			if !found || st.minutes < bestMinutes {
				current, bestMinutes, found = id, st.minutes, true
			}
		}
		if !found {
			break
		}
		visited[current] = true
		for _, c := range g.outgoing[current] {
			if !c.Active {
				continue
			}
			if requireCooled && !c.Cooled {
				continue
			}
			dest, ok := g.locations[c.ToLocationID]
			if !ok || !dest.Active {
				continue
			}
			if !g.canTransit(c.ToLocationID) {
				continue
			}
			minutes := bestMinutes + c.TravelMinutes + dest.HandlingMinutes
			cost := best[current].cost + c.CostUnits
			if existing, ok := best[c.ToLocationID]; !ok || minutes < existing.minutes {
				best[c.ToLocationID] = &state{minutes: minutes, cost: cost, prev: current, conn: c}
			}
		}
	}

	var bestLab uuid.UUID
	bestMinutes := -1
	for id, st := range best {
		if !g.isActiveLaboratory(id) {
			continue
		}
		if accepts, ok := g.acceptedBy[id]; !ok || !accepts[sampleTypeID] {
			continue
		}
		if bestMinutes < 0 || st.minutes < bestMinutes {
			bestLab, bestMinutes = id, st.minutes
		}
	}
	if bestMinutes < 0 {
		return nil
	}

	path := []uuid.UUID{bestLab}
	var conns []*Connection
	for cur := bestLab; cur != start; {
		st := best[cur]
		if st.conn == nil {
			break
		}
		conns = append(conns, st.conn)
		cur = st.prev
		path = append(path, cur)
	}
	for i, j := 0, len(path)-1; i < j; i, j = i+1, j-1 {
		path[i], path[j] = path[j], path[i]
	}
	for i, j := 0, len(conns)-1; i < j; i, j = i+1, j-1 {
		conns[i], conns[j] = conns[j], conns[i]
	}
	return &route{Path: path, Connections: conns, TravelMinutes: best[bestLab].minutes, CostUnits: best[bestLab].cost}
}

// routeToLab finds the fastest active path from start to one specific laboratory.
func (g *networkGraph) routeToLab(start, labID, sampleTypeID uuid.UUID, requireCooled bool) *route {
	if start == labID {
		return &route{Path: []uuid.UUID{start}}
	}
	saved := g.acceptedBy
	filtered := map[uuid.UUID]map[uuid.UUID]bool{}
	if accepts, ok := saved[labID]; ok {
		filtered[labID] = accepts
	}
	g.acceptedBy = filtered
	r := g.cheapestRoute(start, sampleTypeID, requireCooled)
	g.acceptedBy = saved
	return r
}

// serviceabilitySnapshot is one complete published serviceability calculation.
type serviceabilitySnapshot struct {
	Version                    int                     `json:"version"`
	Status                     string                  `json:"status"`
	ComputedAt                 string                  `json:"computedAt"`
	NetworkRevision            int                     `json:"networkRevision"`
	Regions                    []serviceabilityRegion  `json:"regions"`
	ActiveCollectionPointCount int                     `json:"activeCollectionPointCount"`
	reachable                  map[uuid.UUID]bool      `json:"-"`
	labFor                     map[uuid.UUID]uuid.UUID `json:"-"`
}

type serviceabilityRegion struct {
	LocationID string  `json:"locationId"`
	Name       string  `json:"name"`
	Latitude   float64 `json:"latitude"`
	Longitude  float64 `json:"longitude"`
	CoverageKm float64 `json:"coverageKm"`
}

// rebuildServiceability computes a complete snapshot and publishes it atomically. The previously
// published snapshot keeps serving requests until the new one is complete.
func (s *Server) rebuildServiceability(ctx context.Context) error {
	g, err := s.loadGraph(ctx, s.pool)
	if err != nil {
		return err
	}
	regions := []serviceabilityRegion{}
	for _, l := range g.locations {
		if !l.Active || !l.Functions.CollectionPoint {
			continue
		}
		coverage := l.CoverageKm
		if coverage <= 0 || coverage > maxCoverageKm {
			coverage = maxCoverageKm
		}
		regions = append(regions, serviceabilityRegion{
			LocationID: l.ID.String(), Name: l.Name,
			Latitude: l.Coordinate.Latitude, Longitude: l.Coordinate.Longitude,
			CoverageKm: coverage,
		})
	}
	sort.Slice(regions, func(i, j int) bool { return regions[i].Name < regions[j].Name })

	snapshot := &serviceabilitySnapshot{
		Status:                     "complete",
		ComputedAt:                 s.now().Format(time.RFC3339Nano),
		NetworkRevision:            s.networkRevision(ctx),
		Regions:                    regions,
		ActiveCollectionPointCount: len(regions),
	}

	var version int
	err = s.pool.QueryRow(ctx,
		`SELECT coalesce(max(version), 0) + 1 FROM serviceability_snapshots`).Scan(&version)
	if err != nil {
		return err
	}
	snapshot.Version = version

	regionsJSON := mustJSON(regions)
	if _, err := s.pool.Exec(ctx,
		`INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision,
             regions, active_collection_point_count)
         VALUES ($1, 'complete', $2, $3, $4, $5)
         ON CONFLICT (version) DO UPDATE SET status = 'complete', computed_at = EXCLUDED.computed_at,
             network_revision = EXCLUDED.network_revision, regions = EXCLUDED.regions,
             active_collection_point_count = EXCLUDED.active_collection_point_count`,
		version, snapshot.ComputedAt, snapshot.NetworkRevision, regionsJSON,
		snapshot.ActiveCollectionPointCount); err != nil {
		return err
	}

	s.svcMu.Lock()
	s.svcPublished = snapshot
	s.svcMu.Unlock()
	return nil
}

// publishedServiceability returns the latest complete snapshot, loading it from storage if needed.
func (s *Server) publishedServiceability(ctx context.Context) (*serviceabilitySnapshot, error) {
	s.svcMu.RLock()
	snap := s.svcPublished
	s.svcMu.RUnlock()
	if snap != nil {
		return snap, nil
	}
	var (
		loaded      serviceabilitySnapshot
		computedAt  time.Time
		regionsJSON []byte
	)
	err := s.pool.QueryRow(ctx,
		`SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
         FROM serviceability_snapshots WHERE status = 'complete' ORDER BY version DESC LIMIT 1`).
		Scan(&loaded.Version, &loaded.Status, &computedAt, &loaded.NetworkRevision, &regionsJSON,
			&loaded.ActiveCollectionPointCount)
	if err != nil {
		if err := s.rebuildServiceability(ctx); err != nil {
			return nil, err
		}
		s.svcMu.RLock()
		snap = s.svcPublished
		s.svcMu.RUnlock()
		return snap, nil
	}
	loaded.ComputedAt = computedAt.UTC().Format(time.RFC3339Nano)
	loaded.Regions = []serviceabilityRegion{}
	_ = jsonUnmarshal(regionsJSON, &loaded.Regions)
	s.svcMu.Lock()
	s.svcPublished = &loaded
	s.svcMu.Unlock()
	return &loaded, nil
}
