{"command":"create","path":"/workspace/backend/internal/app/planning.go","file_text":"package app

import (
	"context"
	"net/http"
	"time"

	"github.com/google/uuid"
)

// Serviceability reason codes from the pinned contract.
const (
	reasonServiceable           = "serviceable"
	reasonOutsideCoverage       = "outside_service_coverage"
	reasonNoAcceptingLaboratory = "no_accepting_laboratory"
	reasonNoRoute               = "no_route"
	reasonInsufficientCapacity  = "insufficient_capacity"
	reasonDeadlineUnreachable   = "deadline_unreachable"
	reasonHandlingUnsatisfiable = "handling_rules_unsatisfiable"
)

// planRequest describes what has to be planned.
type planRequest struct {
	Origin        Coordinate
	OriginType    string
	OriginNodeID  *uuid.UUID
	SampleType    *SampleType
	CollectionAt  time.Time
	Deadline      time.Time
	Presealed     bool
	SkipEntryLegs bool
	// FixedStartNode forces planning to start from an already-reached node (used for replanning).
	FixedStartNode *uuid.UUID
}

// plannedLeg is one assignment to create.
type plannedLeg struct {
	Kind                  string
	Sequence              int
	FromLocationID        *uuid.UUID
	ToLocationID          *uuid.UUID
	NodeID                *uuid.UUID
	LaboratoryID          *uuid.UUID
	ConnectionID          *uuid.UUID
	RequiredRole          string
	RequiredQualification string
	Cooled                bool
}

// plannedStop is one ordered stop on the journey.
type plannedStop struct {
	LocationID   *uuid.UUID
	Coordinate   Coordinate
	StopType     string
	Sequence     int
	EstimatedAt  time.Time
	DwellMinutes int
}

// plan is a complete, validated journey plan that has not been persisted yet.
type plan struct {
	Serviceable   bool
	Reason        string
	StartNodeID   uuid.UUID
	LaboratoryID  uuid.UUID
	Route         *route
	Cooled        bool
	CollectionAt  time.Time
	ArrivalAt     time.Time
	RouteMode     string
	Legs          []plannedLeg
	Stops         []plannedStop
	NodeResources []uuid.UUID
	ConnResources []uuid.UUID
	TotalCost     float64
}

// buildPlan evaluates serviceability and, when serviceable, produces the full plan.
// It never mutates state, so it is safe to use for dry-run serviceability checks.
func (s *Server) buildPlan(ctx context.Context, g *networkGraph, req planRequest) (*plan, error) {
	st := req.SampleType
	if st == nil {
		return nil, errNotFound
	}
	cooled := st.RequiresCooledRoute

	// Resolve the entry node.
	var startNode *Location
	switch {
	case req.FixedStartNode != nil:
		l, ok := g.locations[*req.FixedStartNode]
		if !ok || !l.Active {
			return &plan{Reason: reasonNoRoute}, nil
		}
		startNode = l
	case req.OriginType == "node":
		if req.OriginNodeID == nil {
			return &plan{Reason: reasonOutsideCoverage}, nil
		}
		l, ok := g.locations[*req.OriginNodeID]
		if !ok || !l.Active {
			return &plan{Reason: reasonOutsideCoverage}, nil
		}
		if !l.Functions.CollectionPoint && !l.Functions.Hub && !l.Functions.TransferPoint && !l.Functions.Laboratory {
			return &plan{Reason: reasonOutsideCoverage}, nil
		}
		startNode = l
	default:
		candidates := g.nearestCollectionPoints(req.Origin)
		if len(candidates) == 0 {
			return &plan{Reason: reasonOutsideCoverage}, nil
		}
		startNode = candidates[0]
	}

	// Is there any active laboratory accepting this sample type at all?
	anyLab := false
	for labID, accepts := range g.acceptedBy {
		if accepts[st.ID] && g.isActiveLaboratory(labID) {
			anyLab = true
			break
		}
	}
	if !anyLab {
		return &plan{Reason: reasonNoAcceptingLaboratory}, nil
	}

	if cooled && startNode.CooledCapacityUnits <= 0 {
		return &plan{Reason: reasonHandlingUnsatisfiable}, nil
	}

	r := g.cheapestRoute(startNode.ID, st.ID, cooled)
	if r == nil {
		return &plan{Reason: reasonNoRoute}, nil
	}
	labID := r.Path[len(r.Path)-1]

	// Capacity must be available for the whole path.
	nodeResources := append([]uuid.UUID{}, r.Path...)
	connResources := make([]uuid.UUID, 0, len(r.Connections))
	for _, c := range r.Connections {
		connResources = append(connResources, c.ID)
	}
	for _, id := range nodeResources {
		l := g.locations[id]
		if !hasLocationCapacity(l, cooled) {
			return &plan{Reason: reasonInsufficientCapacity}, nil
		}
	}
	for _, c := range r.Connections {
		if !hasConnectionCapacity(c, cooled) {
			return &plan{Reason: reasonInsufficientCapacity}, nil
		}
	}

	collectionAt := req.CollectionAt
	arrival := collectionAt.Add(time.Duration(startNode.HandlingMinutes+r.TravelMinutes) * time.Minute)
	if arrival.After(req.Deadline) {
		return &plan{Reason: reasonDeadlineUnreachable, LaboratoryID: labID, ArrivalAt: arrival}, nil
	}

	p := &plan{
		Serviceable:   true,
		Reason:        reasonServiceable,
		StartNodeID:   startNode.ID,
		LaboratoryID:  labID,
		Route:         r,
		Cooled:        cooled,
		CollectionAt:  collectionAt,
		ArrivalAt:     arrival,
		NodeResources: nodeResources,
		ConnResources: connResources,
		TotalCost:     r.CostUnits,
	}

	// Build legs and stops.
	seq := 1
	cursor := collectionAt
	startID := startNode.ID
	if !req.SkipEntryLegs && !req.Presealed && req.OriginType != "node" {
		p.Legs = append(p.Legs, plannedLeg{
			Kind: "collection", Sequence: seq, ToLocationID: &startID,
			RequiredRole: RoleCollectionPro, RequiredQualification: collectorQualification(st),
			Cooled: cooled,
		})
		seq++
	}
	p.Stops = append(p.Stops, plannedStop{
		LocationID: &startID, Coordinate: startNode.Coordinate, StopType: "pickup",
		Sequence: 1, EstimatedAt: cursor, DwellMinutes: startNode.HandlingMinutes,
	})
	cursor = cursor.Add(time.Duration(startNode.HandlingMinutes) * time.Minute)

	stopSeq := 2
	for i, c := range r.Connections {
		from := r.Path[i]
		to := r.Path[i+1]
		connID := c.ID
		fromID, toID := from, to
		p.Legs = append(p.Legs, plannedLeg{
			Kind: "transport", Sequence: seq, FromLocationID: &fromID, ToLocationID: &toID,
			ConnectionID: &connID, RequiredRole: RoleDeliveryPartner, Cooled: cooled,
		})
		seq++
		dest := g.locations[to]
		cursor = cursor.Add(time.Duration(c.TravelMinutes) * time.Minute)
		isFinal := i == len(r.Connections)-1
		stopType := "handoff"
		if isFinal {
			stopType = "delivery"
		}
		p.Stops = append(p.Stops, plannedStop{
			LocationID: &toID, Coordinate: dest.Coordinate, StopType: stopType,
			Sequence: stopSeq, EstimatedAt: cursor, DwellMinutes: dest.HandlingMinutes,
		})
		stopSeq++
		if isFinal {
			labIDCopy := to
			p.Legs = append(p.Legs, plannedLeg{
				Kind: "laboratory", Sequence: seq, LaboratoryID: &labIDCopy, ToLocationID: &labIDCopy,
				RequiredRole: RoleLaboratoryTeam, Cooled: cooled,
			})
			seq++
		} else {
			nodeIDCopy := to
			p.Legs = append(p.Legs, plannedLeg{
				Kind: "node", Sequence: seq, NodeID: &nodeIDCopy, ToLocationID: &nodeIDCopy,
				FromLocationID: &fromID, RequiredRole: RoleNodeHandler, Cooled: cooled,
			})
			seq++
		}
		cursor = cursor.Add(time.Duration(dest.HandlingMinutes) * time.Minute)
	}

	if len(r.Connections) == 0 {
		// The entry node is itself the accepting laboratory.
		labIDCopy := labID
		p.Legs = append(p.Legs, plannedLeg{
			Kind: "laboratory", Sequence: seq, LaboratoryID: &labIDCopy, ToLocationID: &labIDCopy,
			RequiredRole: RoleLaboratoryTeam, Cooled: cooled,
		})
		p.Stops[0].StopType = "delivery"
	}

	switch {
	case len(r.Connections) <= 1:
		p.RouteMode = "direct"
	default:
		p.RouteMode = "multi_stop"
	}
	return p, nil
}

func collectorQualification(st *SampleType) string {
	if !st.QualifiedCollectorRequired {
		return ""
	}
	return st.RequiredQualification
}

func hasLocationCapacity(l *Location, cooled bool) bool {
	if l == nil {
		return false
	}
	if cooled {
		return l.CooledCapacityUnits-l.CooledReservedUnits > 0
	}
	return l.CapacityUnits-l.ReservedUnits > 0
}

func hasConnectionCapacity(c *Connection, cooled bool) bool {
	if c == nil {
		return false
	}
	if cooled {
		return c.CooledCapacityUnits-c.CooledReservedUnits > 0
	}
	return c.CapacityUnits-c.ReservedUnits > 0
}

// reserveCapacity takes one unit from each node and connection pool the plan needs.
// It fails rather than overbooking any pool.
func (s *Server) reserveCapacity(ctx context.Context, q querier, journeyID, sampleID uuid.UUID,
	nodes, conns []uuid.UUID, cooled bool) error {
	for _, id := range nodes {
		if err := s.reserveOne(ctx, q, "location", id, journeyID, sampleID, cooled); err != nil {
			return err
		}
	}
	for _, id := range conns {
		if err := s.reserveOne(ctx, q, "connection", id, journeyID, sampleID, cooled); err != nil {
			return err
		}
	}
	return nil
}

func (s *Server) reserveOne(ctx context.Context, q querier, resourceType string, resourceID,
	journeyID, sampleID uuid.UUID, cooled bool) error {
	var table, reservedCol, capacityCol string
	switch resourceType {
	case "location":
		table = "locations"
	case "connection":
		table = "connections"
	default:
		return errf(http.StatusConflict, "invalid_reservation", "unknown resource type %q", resourceType)
	}
	if cooled {
		reservedCol, capacityCol = "cooled_reserved_units", "cooled_capacity_units"
	} else {
		reservedCol, capacityCol = "reserved_units", "capacity_units"
	}
	tag, err := q.Exec(ctx,
		`UPDATE `+table+` SET `+reservedCol+` = `+reservedCol+` + 1
         WHERE id = $1 AND `+reservedCol+` + 1 <= `+capacityCol, resourceID)
	if err != nil {
		return err
	}
	if tag.RowsAffected() == 0 {
		if cooled {
			return errf(http.StatusConflict, "cooled_capacity_exhausted",
				"cooled capacity is exhausted for %s %s", resourceType, resourceID)
		}
		return errf(http.StatusConflict, "capacity_exhausted",
			"capacity is exhausted for %s %s", resourceType, resourceID)
	}
	_, err = q.Exec(ctx,
		`INSERT INTO capacity_reservations (id, resource_type, resource_id, journey_id, sample_id, units, cooled)
         VALUES ($1, $2, $3, $4, $5, 1, $6)`,
		uuid.New(), resourceType, resourceID, journeyID, sampleID, cooled)
	return err
}

// releaseJourneyCapacity releases every reservation held by a journey.
func (s *Server) releaseJourneyCapacity(ctx context.Context, q querier, journeyID uuid.UUID) error {
	rows, err := q.Query(ctx,
		`SELECT id, resource_type, resource_id, cooled FROM capacity_reservations
         WHERE journey_id = $1 AND NOT released`, journeyID)
	if err != nil {
		return err
	}
	type res struct {
		id       uuid.UUID
		rType    string
		resource uuid.UUID
		cooled   bool
	}
	var list []res
	for rows.Next() {
		var r res
		if err := rows.Scan(&r.id, &r.rType, &r.resource, &r.cooled); err != nil {
			rows.Close()
			return err
		}
		list = append(list, r)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}
	for _, r := range list {
		table := "locations"
		if r.rType == "connection" {
			table = "connections"
		}
		col := "reserved_units"
		if r.cooled {
			col = "cooled_reserved_units"
		}
		if _, err := q.Exec(ctx,
			`UPDATE `+table+` SET `+col+` = greatest(`+col+` - 1, 0) WHERE id = $1`, r.resource); err != nil {
			return err
		}
		if _, err := q.Exec(ctx,
			`UPDATE capacity_reservations SET released = true WHERE id = $1`, r.id); err != nil {
			return err
		}
	}
	return nil
}
