// persistPlan writes a journey, its stops, legs and capacity reservations.
func (s *Server) persistPlan(ctx context.Context, q querier, p *plan, sampleIDs []uuid.UUID,
	parentJourneyID *uuid.UUID) (*Journey, []*Assignment, error) {
	journeyID := uuid.New()
	estimated := p.ArrivalAt
	if _, err := q.Exec(ctx,
		`INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status,
             estimated_delivery_at, total_cost_units)
         VALUES ($1, $2, 1, $3, 'planned', $4, $5)`,
		journeyID, parentJourneyID, p.RouteMode, estimated, p.TotalCost); err != nil {
		return nil, nil, err
	}
	for _, sid := range sampleIDs {
		if _, err := q.Exec(ctx,
			`INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1, $2)
             ON CONFLICT DO NOTHING`, journeyID, sid); err != nil {
			return nil, nil, err
		}
	}
	for _, st := range p.Stops {
		if _, err := q.Exec(ctx,
			`INSERT INTO journey_stops (id, journey_id, location_id, latitude, longitude, stop_type,
                 sequence, estimated_at, dwell_minutes)
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)`,
			uuid.New(), journeyID, st.LocationID, st.Coordinate.Latitude, st.Coordinate.Longitude,
			st.StopType, st.Sequence, st.EstimatedAt, st.DwellMinutes); err != nil {
			return nil, nil, err
		}
	}
	primarySample := uuid.Nil
	if len(sampleIDs) > 0 {
		primarySample = sampleIDs[0]
	}
	assignments := make([]*Assignment, 0, len(p.Legs))
	for _, leg := range p.Legs {
		id := uuid.New()
		if _, err := q.Exec(ctx,
			`INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status,
                 from_location_id, to_location_id, node_id, laboratory_id, required_role,
                 required_qualification, cooled, connection_id)
             VALUES ($1, $2, $3, $4, $5, 'pending', $6, $7, $8, $9, $10, $11, $12, $13)`,
			id, journeyID, primarySample, leg.Kind, leg.Sequence, leg.FromLocationID,
			leg.ToLocationID, leg.NodeID, leg.LaboratoryID, leg.RequiredRole,
			leg.RequiredQualification, leg.Cooled, leg.ConnectionID); err != nil {
			return nil, nil, err
		}
		a, err := s.assignmentByID(ctx, q, id)
		if err != nil {
			return nil, nil, err
		}
		assignments = append(assignments, a)
	}
	for _, sid := range sampleIDs {
		if err := s.reserveCapacity(ctx, q, journeyID, sid, p.NodeResources, p.ConnResources, p.Cooled); err != nil {
			return nil, nil, err
		}
	}
	j, err := s.journeyByID(ctx, q, journeyID)
	if err != nil {
		return nil, nil, err
	}
	return j, assignments, nil
}

// journeyPlanAPI renders the pinned JourneyPlan schema for a journey.
func (s *Server) journeyPlanAPI(ctx context.Context, q querier, j *Journey) (map[string]any, error) {
	stops, err := s.stopsForJourney(ctx, q, j.ID)
	if err != nil {
		return nil, err
	}
	assignments, err := s.assignmentsForJourney(ctx, q, j.ID)
	if err != nil {
		return nil, err
	}
	sampleIDs, err := s.journeySampleIDs(ctx, q, j.ID)
	if err != nil {
		return nil, err
	}

	orderedStops := make([]map[string]any, 0, len(stops))
	for _, st := range stops {
		orderedStops = append(orderedStops, st.API())
	}
	legs := []map[string]any{}
	workerIDs := []string{}
	seenWorker := map[uuid.UUID]bool{}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	transportIDs := []string{}
	for _, a := range assignments {
		if a.Kind == "transport" {
			legs = append(legs, a.legAPI())
			transportIDs = append(transportIDs, a.ID.String())
		}
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.ID.String())
		case "node":
			nodeIDs = append(nodeIDs, a.ID.String())
		case "laboratory":
			labIDs = append(labIDs, a.ID.String())
		}
		if a.WorkerID != nil && !seenWorker[*a.WorkerID] {
			seenWorker[*a.WorkerID] = true
			workerIDs = append(workerIDs, a.WorkerID.String())
		}
	}

	out := map[string]any{
		"journeyId":         j.ID.String(),
		"planVersion":       j.PlanVersion,
		"routeMode":         j.RouteMode,
		"status":            j.Status,
		"sampleIds":         uuidStrings(sampleIDs),
		"orderedStops":      orderedStops,
		"legs":              legs,
		"assignedWorkerIds": workerIDs,
		"totalCostUnits":    j.TotalCostUnits,
		"valid":             j.Status != "cancelled" && j.Status != "expired",
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = rfc3339(*j.EstimatedDeliveryAt)
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentIds"] = collectionIDs
		out["collectionAssignmentId"] = collectionIDs[0]
	}
	if len(nodeIDs) > 0 {
		out["nodeAssignmentIds"] = nodeIDs
	}
	if len(labIDs) > 0 {
		out["laboratoryAssignmentIds"] = labIDs
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentId"] = transportIDs[1]
		}
	}
	used, available, err := s.journeyCapacityUsage(ctx, q, j.ID)
	if err == nil {
		out["capacityUsed"] = used
		out["capacityAvailable"] = available
	}
	return out, nil
}

func (a *Assignment) legAPI() map[string]any {
	out := map[string]any{
		"assignmentId": a.ID.String(),
		"sequence":     a.Sequence,
		"status":       a.Status,
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = a.FromLocationID.String()
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = a.ToLocationID.String()
	}
	if a.WorkerID != nil {
		out["workerId"] = a.WorkerID.String()
	}
	if a.SampleID != nil {
		out["sampleId"] = a.SampleID.String()
	}
	return out
}

func (s *Server) journeyCapacityUsage(ctx context.Context, q querier, journeyID uuid.UUID) (int, int, error) {
	var used int
	if err := q.QueryRow(ctx,
		`SELECT coalesce(sum(units), 0) FROM capacity_reservations
         WHERE journey_id = $1 AND NOT released`, journeyID).Scan(&used); err != nil {
		return 0, 0, err
	}
	var available int
	if err := q.QueryRow(ctx,
		`SELECT coalesce(min(free), 0) FROM (
            SELECT least(l.capacity_units - l.reserved_units,
                         l.cooled_capacity_units - l.cooled_reserved_units) AS free
            FROM capacity_reservations r JOIN locations l ON l.id = r.resource_id
            WHERE r.journey_id = $1 AND NOT r.released AND r.resource_type = 'location'
         ) t`, journeyID).Scan(&available); err != nil {
		return used, 0, nil
	}
	if available < 0 {
		available = 0
	}
	return used, available, nil
}
