{"command":"create","path":"/workspace/backend/internal/app/offers.go","file_text":"package app

import (
	"context"
	"log"
	"sort"
	"time"

	"github.com/google/uuid"
)

// candidate is an eligible worker ranked for fair distribution of work.
type candidate struct {
	user          *User
	openCount     int
	recentCount   int
	lastOfferedAt time.Time
	penalised     bool
}

// eligibleWorkers finds active, available workers who hold the required role, hold the required
// qualification, are assigned to the required node/laboratory, and have not declined this offer.
func (s *Server) eligibleWorkers(ctx context.Context, q querier, a *Assignment, now time.Time) ([]candidate, error) {
	rows, err := q.Query(ctx, `SELECT `+userColumns+` FROM users
        WHERE active AND $1 = ANY(roles)`, a.RequiredRole)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var users []*User
	for rows.Next() {
		u, err := scanUser(rows)
		if err != nil {
			return nil, err
		}
		users = append(users, u)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	// A node or laboratory assignment may only be offered to a worker assigned to that resource.
	var requiredLocation *uuid.UUID
	switch a.Kind {
	case "node":
		requiredLocation = a.NodeID
	case "laboratory":
		requiredLocation = a.LaboratoryID
	}

	out := []candidate{}
	for _, u := range users {
		if !u.Available {
			continue
		}
		if containsUUID(a.DeclinedBy, u.ID) {
			continue
		}
		if a.RequiredQualification != "" && !u.HasQualification(a.RequiredQualification, now) {
			continue
		}
		if requiredLocation != nil {
			if u.AssignedLocationID == nil || *u.AssignedLocationID != *requiredLocation {
				continue
			}
		}
		openCount, recentCount, err := s.workerLoad(ctx, q, u.ID, now)
		if err != nil {
			return nil, err
		}
		if u.CapacityUnits > 0 && openCount >= u.CapacityUnits {
			continue
		}
		c := candidate{user: u, openCount: openCount, recentCount: recentCount}
		if u.LastOfferedAt != nil {
			c.lastOfferedAt = *u.LastOfferedAt
		}
		c.penalised = u.PenaltyUntil != nil && u.PenaltyUntil.After(now)
		out = append(out, c)
	}

	// Fair ordering: penalised workers last, then least current workload, then fewest recent
	// assignments, then least recently offered.
	sort.SliceStable(out, func(i, j int) bool {
		if out[i].penalised != out[j].penalised {
			return !out[i].penalised
		}
		if out[i].openCount != out[j].openCount {
			return out[i].openCount < out[j].openCount
		}
		if out[i].recentCount != out[j].recentCount {
			return out[i].recentCount < out[j].recentCount
		}
		if !out[i].lastOfferedAt.Equal(out[j].lastOfferedAt) {
			return out[i].lastOfferedAt.Before(out[j].lastOfferedAt)
		}
		return out[i].user.Username < out[j].user.Username
	})
	return out, nil
}

func (s *Server) workerLoad(ctx context.Context, q querier, workerID uuid.UUID, now time.Time) (int, int, error) {
	var open, recent int
	err := q.QueryRow(ctx,
		`SELECT
            count(*) FILTER (WHERE status IN ('offered', 'accepted', 'in_progress', 'at_pickup',
                'picked_up', 'in_transit', 'arrived', 'delivered')),
            count(*) FILTER (WHERE created_at > $2)
         FROM assignments WHERE worker_id = $1 OR offered_to = $1`,
		workerID, now.Add(-24*time.Hour)).Scan(&open, &recent)
	if err != nil {
		return 0, 0, err
	}
	return open, recent, nil
}

// offerAssignment offers pending work to the next eligible worker, one worker at a time.
// When no qualified worker exists at all it records the reason so the sample can be flagged.
func (s *Server) offerAssignment(ctx context.Context, q querier, a *Assignment, now time.Time) (*Assignment, error) {
	if a.Status != "pending" {
		return a, nil
	}
	candidates, err := s.eligibleWorkers(ctx, q, a, now)
	if err != nil {
		return nil, err
	}
	if len(candidates) == 0 {
		// No eligible worker right now. Leave the assignment pending; the sweeper will flag the
		// sample when nobody becomes available within a reasonable time.
		s.auditTx(ctx, q, auditRecord{Action: "offer_no_eligible_worker", Role: "system",
			EntityType: "assignment", EntityID: a.ID.String(), Success: false, OccurredAt: now,
			Details: map[string]any{
				"requiredRole":          a.RequiredRole,
				"requiredQualification": a.RequiredQualification,
				"kind":                  a.Kind,
			}})
		return a, nil
	}
	chosen := candidates[0].user
	expires := now.Add(offerResponseTimeout)
	if _, err := q.Exec(ctx,
		`UPDATE assignments SET status = 'offered', offered_to = $2, offer_expires_at = $3,
             updated_at = $4 WHERE id = $1`, a.ID, chosen.ID, expires, now); err != nil {
		return nil, err
	}
	if _, err := q.Exec(ctx,
		`UPDATE users SET last_offered_at = $2 WHERE id = $1`, chosen.ID, now); err != nil {
		return nil, err
	}
	s.auditTx(ctx, q, auditRecord{Action: "assignment_offered", Role: "system",
		EntityType: "assignment", EntityID: a.ID.String(), Success: true, OccurredAt: now,
		Details: map[string]any{"workerId": chosen.ID.String(), "kind": a.Kind,
			"offerExpiresAt": rfc3339(expires)}})
	sampleID := ""
	if a.SampleID != nil {
		sampleID = a.SampleID.String()
	}
	s.publishEvent(ctx, q, RealtimeEvent{
		Type: "assignment.offered", EntityType: "assignment", EntityID: a.ID.String(),
		Payload: map[string]any{"assignmentId": a.ID.String(), "kind": a.Kind,
			"workerId": chosen.ID.String(), "sampleId": sampleID},
		audience: []string{a.RequiredRole, RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{chosen.ID},
	})
	return s.assignmentByID(ctx, q, a.ID)
}

// offerJourneyWork offers every pending assignment of a journey.
func (s *Server) offerJourneyWork(ctx context.Context, q querier, assignments []*Assignment, now time.Time) error {
	for _, a := range assignments {
		if a.Status != "pending" {
			continue
		}
		if _, err := s.offerAssignment(ctx, q, a, now); err != nil {
			return err
		}
	}
	return nil
}

// expireStaleOffers treats unanswered offers as declines and re-offers them, and flags samples
// that have no qualified worker available for a reasonable time.
func (s *Server) expireStaleOffers(ctx context.Context) error {
	now := s.now()
	rows, err := s.pool.Query(ctx, `SELECT `+assignmentColumns+` FROM assignments
        WHERE status = 'offered' AND offer_expires_at IS NOT NULL AND offer_expires_at < $1`, now)
	if err != nil {
		return err
	}
	var expired []*Assignment
	for rows.Next() {
		a, err := scanAssignment(rows)
		if err != nil {
			rows.Close()
			return err
		}
		expired = append(expired, a)
	}
	rows.Close()

	for _, a := range expired {
		tx, err := s.pool.Begin(ctx)
		if err != nil {
			return err
		}
		if a.OfferedTo != nil {
			if _, err := tx.Exec(ctx,
				`UPDATE assignments SET status = 'pending', offered_to = NULL, offer_expires_at = NULL,
                     declined_by = array_append(declined_by, $2), updated_at = $3 WHERE id = $1`,
				a.ID, *a.OfferedTo, now); err != nil {
				_ = tx.Rollback(ctx)
				return err
			}
			if err := s.applyDeclinePenalty(ctx, tx, *a.OfferedTo, now); err != nil {
				_ = tx.Rollback(ctx)
				return err
			}
			s.auditTx(ctx, tx, auditRecord{Action: "assignment_offer_timed_out", Role: "system",
				EntityType: "assignment", EntityID: a.ID.String(), Success: true, OccurredAt: now,
				Details: map[string]any{"workerId": a.OfferedTo.String(), "treatedAs": "declined"}})
		}
		refreshed, err := s.assignmentByID(ctx, tx, a.ID)
		if err != nil {
			_ = tx.Rollback(ctx)
			return err
		}
		if _, err := s.offerAssignment(ctx, tx, refreshed, now); err != nil {
			_ = tx.Rollback(ctx)
			return err
		}
		if err := tx.Commit(ctx); err != nil {
			return err
		}
	}

	return s.flagUnstaffableWork(ctx, now)
}

// flagUnstaffableWork marks samples as an exception when work requiring a qualified worker has
// found nobody for a reasonable time. That exception is distinct from a missed delivery deadline.
func (s *Server) flagUnstaffableWork(ctx context.Context, now time.Time) error {
	rows, err := s.pool.Query(ctx, `SELECT `+assignmentColumns+` FROM assignments
        WHERE status = 'pending' AND required_qualification <> '' AND created_at < $1`,
		now.Add(-qualifiedWaitBeforeFlag))
	if err != nil {
		return err
	}
	var stuck []*Assignment
	for rows.Next() {
		a, err := scanAssignment(rows)
		if err != nil {
			rows.Close()
			return err
		}
		stuck = append(stuck, a)
	}
	rows.Close()

	for _, a := range stuck {
		candidates, err := s.eligibleWorkers(ctx, s.pool, a, now)
		if err != nil {
			return err
		}
		if len(candidates) > 0 {
			if _, err := s.offerAssignment(ctx, s.pool, a, now); err != nil {
				log.Printf("re-offer after availability: %v", err)
			}
			continue
		}
		if a.SampleID == nil {
			continue
		}
		if err := s.markSampleException(ctx, s.pool, *a.SampleID, exceptionNoQualifiedWorker,
			"no qualified worker available for the required collection", now, nil); err != nil {
			return err
		}
	}
	return nil
}

func (s *Server) applyDeclinePenalty(ctx context.Context, q querier, workerID uuid.UUID, now time.Time) error {
	// Repeated declines lower priority for a limited time but never permanently exclude a worker.
	_, err := q.Exec(ctx,
		`UPDATE users SET decline_count = decline_count + 1,
             penalty_until = CASE WHEN decline_count + 1 >= 2 THEN $2 ELSE penalty_until END
         WHERE id = $1`, workerID, now.Add(declinePenaltyDuration))
	return err
}
