{"command":"create","path":"/workspace/backend/internal/app/sample.go","file_text":"package app

import (
	"context"
	"errors"
	"time"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

// Sample lifecycle statuses.
const (
	statusRequested   = "requested"
	statusScheduled   = "scheduled"
	statusCollected   = "collected"
	statusSealed      = "sealed"
	statusInTransit   = "in_transit"
	statusAtNode      = "at_node"
	statusAtLab       = "at_laboratory"
	statusReceived    = "received"
	statusException   = "exception"
	statusExpired     = "expired"
	statusCancelled   = "cancelled"
	statusUnservicabl = "unserviceable"
)

// Exception kinds, kept distinguishable from one another.
const (
	exceptionNoQualifiedWorker = "no_qualified_worker"
	exceptionDeadlineMissed    = "delivery_deadline_missed"
	exceptionHandlingBreach    = "handling_breach"
	exceptionLaboratory        = "laboratory_exception"
	exceptionNoRoute           = "no_valid_route"
)

func sampleTerminal(status string) bool {
	switch status {
	case statusReceived, statusExpired, statusCancelled, statusUnservicabl:
		return true
	}
	return false
}

// Sample is a physical clinical sample tracked through the network.
type Sample struct {
	ID                   uuid.UUID
	RequestID            uuid.UUID
	RequesterID          uuid.UUID
	SampleTypeID         uuid.UUID
	Status               string
	Sealed               bool
	Presealed            bool
	CurrentHolderID      *uuid.UUID
	ActiveJourneyID      *uuid.UUID
	TargetLaboratoryID   *uuid.UUID
	ReceivedLaboratoryID *uuid.UUID
	SealedAt             *time.Time
	ReceivedAt           *time.Time
	Exception            map[string]any
	LatestLatitude       *float64
	LatestLongitude      *float64
	LocationRecordedAt   *time.Time
}

const sampleColumns = `id, request_id, requester_id, sample_type_id, status, sealed, presealed,
    current_holder_id, active_journey_id, target_laboratory_id, received_laboratory_id, sealed_at,
    received_at, exception, latest_latitude, latest_longitude, location_recorded_at`

func scanSample(row pgx.Row) (*Sample, error) {
	var s Sample
	var exc []byte
	if err := row.Scan(&s.ID, &s.RequestID, &s.RequesterID, &s.SampleTypeID, &s.Status, &s.Sealed,
		&s.Presealed, &s.CurrentHolderID, &s.ActiveJourneyID, &s.TargetLaboratoryID,
		&s.ReceivedLaboratoryID, &s.SealedAt, &s.ReceivedAt, &exc, &s.LatestLatitude,
		&s.LatestLongitude, &s.LocationRecordedAt); err != nil {
		return nil, err
	}
	if len(exc) > 0 {
		s.Exception = map[string]any{}
		_ = jsonUnmarshal(exc, &s.Exception)
	}
	return &s, nil
}

func (s *Server) sampleByID(ctx context.Context, q querier, id uuid.UUID) (*Sample, error) {
	sm, err := scanSample(q.QueryRow(ctx, `SELECT `+sampleColumns+` FROM samples WHERE id = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errNotFound
	}
	if err != nil {
		return nil, err
	}
	return sm, nil
}

// CollectionRequest records where and when a sample may be collected and its delivery deadline.
type CollectionRequest struct {
	ID                   uuid.UUID
	RequesterID          uuid.UUID
	Origin               Coordinate
	OriginType           string
	OriginNodeID         *uuid.UUID
	RequestedAt          time.Time
	DeliveryDeadline     time.Time
	EarliestCollectionAt time.Time
	LatestCollectionAt   time.Time
	SampleTypeID         uuid.UUID
	ContainerType        string
	TemperatureMinC      float64
	TemperatureMaxC      float64
	IncompatibleTypes    []uuid.UUID
	Serviceability       string
	ServiceabilityReason string
	Presealed            bool
}

const requestColumns = `id, requester_id, origin_latitude, origin_longitude, origin_type,
    origin_node_id, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at,
    sample_type_id, container_type, temperature_min_c, temperature_max_c, incompatible_types,
    serviceability, serviceability_reason, presealed`

func scanRequest(row pgx.Row) (*CollectionRequest, error) {
	var r CollectionRequest
	if err := row.Scan(&r.ID, &r.RequesterID, &r.Origin.Latitude, &r.Origin.Longitude,
		&r.OriginType, &r.OriginNodeID, &r.RequestedAt, &r.DeliveryDeadline,
		&r.EarliestCollectionAt, &r.LatestCollectionAt, &r.SampleTypeID, &r.ContainerType,
		&r.TemperatureMinC, &r.TemperatureMaxC, &r.IncompatibleTypes, &r.Serviceability,
		&r.ServiceabilityReason, &r.Presealed); err != nil {
		return nil, err
	}
	if r.IncompatibleTypes == nil {
		r.IncompatibleTypes = []uuid.UUID{}
	}
	return &r, nil
}

func (s *Server) requestByID(ctx context.Context, q querier, id uuid.UUID) (*CollectionRequest, error) {
	r, err := scanRequest(q.QueryRow(ctx, `SELECT `+requestColumns+` FROM requests WHERE id = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errNotFound
	}
	if err != nil {
		return nil, err
	}
	return r, nil
}

// markSampleException flags a sample with a specific, distinguishable exception reason.
func (s *Server) markSampleException(ctx context.Context, q querier, sampleID uuid.UUID,
	kind, reason string, now time.Time, labID *uuid.UUID) error {
	sm, err := s.sampleByID(ctx, q, sampleID)
	if err != nil {
		return err
	}
	if sm.Status == statusReceived {
		return nil
	}
	if existing, ok := sm.Exception["kind"].(string); ok && existing == kind {
		return nil
	}
	exc := map[string]any{"kind": kind, "reason": reason, "observedAt": rfc3339(now)}
	if labID != nil {
		exc["laboratoryId"] = labID.String()
	}
	if _, err := q.Exec(ctx,
		`UPDATE samples SET status = $2, exception = $3, updated_at = $4 WHERE id = $1`,
		sampleID, statusException, mustJSON(exc), now); err != nil {
		return err
	}
	if _, err := q.Exec(ctx,
		`INSERT INTO sample_exceptions (id, sample_id, kind, reason, laboratory_id, observed_at)
         VALUES ($1, $2, $3, $4, $5, $6)`,
		uuid.New(), sampleID, kind, reason, labID, now); err != nil {
		return err
	}
	s.auditTx(ctx, q, auditRecord{Action: "sample_exception", Role: "system", EntityType: "sample",
		EntityID: sampleID.String(), Success: false, OccurredAt: now, Details: exc})
	s.publishEvent(ctx, q, RealtimeEvent{
		Type: "sample.exception", EntityType: "sample", EntityID: sampleID.String(),
		Payload:  exc,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{sm.RequesterID},
	})
	return nil
}

// setSampleStatus records a status change and its timeline entry.
func (s *Server) setSampleStatus(ctx context.Context, q querier, sampleID uuid.UUID, status string,
	actor *requestContext, action string, now time.Time, details map[string]any) error {
	if _, err := q.Exec(ctx,
		`UPDATE samples SET status = $2, updated_at = $3 WHERE id = $1`, sampleID, status, now); err != nil {
		return err
	}
	if details == nil {
		details = map[string]any{}
	}
	details["status"] = status
	rec := auditRecord{Action: action, EntityType: "sample", EntityID: sampleID.String(),
		Success: true, OccurredAt: now, Details: details}
	if actor != nil {
		rec.ActorID = actor.actorID()
		rec.Role = actor.Role
	} else {
		rec.Role = "system"
	}
	s.auditTx(ctx, q, rec)
	s.publishEvent(ctx, q, RealtimeEvent{
		Type: "sample.status", EntityType: "sample", EntityID: sampleID.String(),
		Payload:  details,
		audience: []string{RoleDispatcher, RoleAdministrator},
	})
	return nil
}

// recordSampleLocation stores the sample's latest known position.
func (s *Server) recordSampleLocation(ctx context.Context, q querier, sampleID uuid.UUID,
	c Coordinate, at time.Time) error {
	_, err := q.Exec(ctx,
		`UPDATE samples SET latest_latitude = $2, latest_longitude = $3,
             location_recorded_at = $4, updated_at = $4
         WHERE id = $1 AND (location_recorded_at IS NULL OR location_recorded_at <= $4)`,
		sampleID, c.Latitude, c.Longitude, at)
	return err
}

func (sm *Sample) latestCoordinate() *Coordinate {
	if sm.LatestLatitude == nil || sm.LatestLongitude == nil {
		return nil
	}
	return &Coordinate{Latitude: *sm.LatestLatitude, Longitude: *sm.LatestLongitude}
}

// sampleStateAPI renders the pinned SampleState schema.
func (s *Server) sampleStateAPI(ctx context.Context, q querier, sm *Sample, now time.Time) (map[string]any, error) {
	req, err := s.requestByID(ctx, q, sm.RequestID)
	if err != nil {
		return nil, err
	}
	assignments, err := s.assignmentsForSample(ctx, q, sm.ID)
	if err != nil {
		return nil, err
	}
	active := []string{}
	for _, a := range assignments {
		if !assignmentTerminal(a.Status) {
			active = append(active, a.ID.String())
		}
	}
	timeline, err := s.sampleTimeline(ctx, q, sm, assignments)
	if err != nil {
		return nil, err
	}
	out := map[string]any{
		"sampleId":                sm.ID.String(),
		"requestId":               sm.RequestID.String(),
		"requesterId":             sm.RequesterID.String(),
		"origin":                  req.Origin,
		"originType":              req.OriginType,
		"requestedAt":             rfc3339(req.RequestedAt),
		"deliveryDeadline":        rfc3339(req.DeliveryDeadline),
		"sampleTypeId":            sm.SampleTypeID.String(),
		"containerType":           req.ContainerType,
		"temperatureMinC":         req.TemperatureMinC,
		"temperatureMaxC":         req.TemperatureMaxC,
		"incompatibleSampleTypes": uuidStrings(req.IncompatibleTypes),
		"serviceability":          req.Serviceability,
		"activeAssignmentIds":     active,
		"state":                   map[string]any{"status": sm.Status},
		"timeline":                timeline,
		"locationStale":           isStale(sm.LocationRecordedAt, now),
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = sm.ActiveJourneyID.String()
	}
	if sm.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = sm.TargetLaboratoryID.String()
	}
	if c := sm.latestCoordinate(); c != nil {
		out["latestLocation"] = c
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = rfc3339(*sm.LocationRecordedAt)
	}
	return out, nil
}

// sampleTimeline merges the sample's own history with the history of its work items so the
// ordered status history is complete.
func (s *Server) sampleTimeline(ctx context.Context, q querier, sm *Sample, assignments []*Assignment) ([]TimelineEntry, error) {
	pairs := [][2]string{{"sample", sm.ID.String()}, {"request", sm.RequestID.String()}}
	for _, a := range assignments {
		pairs = append(pairs, [2]string{"assignment", a.ID.String()})
	}
	journeyIDs := map[uuid.UUID]bool{}
	if sm.ActiveJourneyID != nil {
		journeyIDs[*sm.ActiveJourneyID] = true
	}
	for _, a := range assignments {
		if a.JourneyID != nil {
			journeyIDs[*a.JourneyID] = true
		}
	}
	for id := range journeyIDs {
		pairs = append(pairs, [2]string{"journey", id.String()})
	}
	rows, err := q.Query(ctx, `SELECT id FROM handoffs WHERE sample_id = $1`, sm.ID)
	if err != nil {
		return nil, err
	}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return nil, err
		}
		pairs = append(pairs, [2]string{"handoff", id.String()})
	}
	rows.Close()
	return s.timelineForMany(ctx, q, pairs)
}

// sampleLifecycleAPI renders the pinned SampleLifecycle schema.
func (s *Server) sampleLifecycleAPI(ctx context.Context, q querier, sm *Sample, now time.Time) (map[string]any, error) {
	assignments, err := s.assignmentsForSample(ctx, q, sm.ID)
	if err != nil {
		return nil, err
	}
	completed := []string{}
	for _, a := range assignments {
		if a.Status == "completed" {
			completed = append(completed, a.ID.String())
		}
	}
	timeline, err := s.sampleTimeline(ctx, q, sm, assignments)
	if err != nil {
		return nil, err
	}
	replacements, err := s.activeReplacementPlans(ctx, q, sm.ID)
	if err != nil {
		return nil, err
	}
	out := map[string]any{
		"sampleId":                 sm.ID.String(),
		"status":                   sm.Status,
		"sealed":                   sm.Sealed,
		"completedLegIds":          completed,
		"activeReplacementPlanIds": replacements,
		"timeline":                 timeline,
		"locationStale":            isStale(sm.LocationRecordedAt, now),
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = sm.ActiveJourneyID.String()
	}
	if sm.CurrentHolderID != nil {
		out["currentHolderId"] = sm.CurrentHolderID.String()
	}
	if sm.ReceivedLaboratoryID != nil {
		out["receivedLaboratoryId"] = sm.ReceivedLaboratoryID.String()
	}
	if sm.Exception != nil {
		out["exception"] = sm.Exception
	}
	if c := sm.latestCoordinate(); c != nil {
		out["latestLocation"] = c
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = rfc3339(*sm.LocationRecordedAt)
	}
	pending, err := s.pendingHandoff(ctx, q, sm.ID)
	if err != nil {
		return nil, err
	}
	if pending != nil {
		out["pendingHandoffId"] = pending.ID.String()
		out["pendingHandoff"] = pending.API()
	}
	return out, nil
}

// activeReplacementPlans lists replacement journeys currently active for a sample. Only one
// replacement plan may be active at a time.
func (s *Server) activeReplacementPlans(ctx context.Context, q querier, sampleID uuid.UUID) ([]string, error) {
	rows, err := q.Query(ctx,
		`SELECT j.id FROM journeys j
         JOIN journey_samples js ON js.journey_id = j.id
         WHERE js.sample_id = $1 AND j.parent_journey_id IS NOT NULL
           AND j.status NOT IN ('cancelled', 'completed', 'superseded', 'expired')
         ORDER BY j.created_at DESC`, sampleID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []string{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		out = append(out, id.String())
	}
	return out, rows.Err()
}
