// Handoff is a two-sided transfer of custody. Until both sides confirm, the sender remains
// responsible for the sample.
type Handoff struct {
	ID                uuid.UUID
	SampleID          uuid.UUID
	FromAssignmentID  *uuid.UUID
	ToAssignmentID    *uuid.UUID
