	ReceiverConfirmed bool
	InitiatedAt       time.Time
	CompletedAt       *time.Time
}

// API renders a handoff for API responses.
func (h *Handoff) API() map[string]any {
	out := map[string]any{
		"handoffId":         h.ID.String(),
		"sampleId":          h.SampleID.String(),
		"senderId":          h.SenderID.String(),
		"receiverId":        h.ReceiverID.String(),
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
		"initiatedAt":       rfc3339(h.InitiatedAt),
	}
	if h.FromAssignmentID != nil {
		out["fromAssignmentId"] = h.FromAssignmentID.String()
	}
	if h.ToAssignmentID != nil {
		out["toAssignmentId"] = h.ToAssignmentID.String()
	}
	if h.CompletedAt != nil {
		out["completedAt"] = rfc3339(*h.CompletedAt)
	}
	return out
}

const handoffColumns = `id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id,
    status, sender_confirmed, receiver_confirmed, initiated_at, completed_at`

func scanHandoff(row pgx.Row) (*Handoff, error) {
	var h Handoff
	if err := row.Scan(&h.ID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID,
		&h.ReceiverID, &h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.InitiatedAt,
		&h.CompletedAt); err != nil {
		return nil, err
	}
	return &h, nil
}

func (s *Server) handoffByID(ctx context.Context, q querier, id uuid.UUID) (*Handoff, error) {
	h, err := scanHandoff(q.QueryRow(ctx, `SELECT `+handoffColumns+` FROM handoffs WHERE id = $1`, id))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, errNotFound
	}
	if err != nil {
		return nil, err
	}
	return h, nil
}

func (s *Server) pendingHandoff(ctx context.Context, q querier, sampleID uuid.UUID) (*Handoff, error) {
	h, err := scanHandoff(q.QueryRow(ctx, `SELECT `+handoffColumns+` FROM handoffs
        WHERE sample_id = $1 AND status = 'pending' ORDER BY created_at DESC LIMIT 1`, sampleID))
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	return h, nil
}

// transferCustody sets the new sole current holder for a sealed sample.
func (s *Server) transferCustody(ctx context.Context, q querier, sampleID, holderID uuid.UUID,
	actor *requestContext, action string, now time.Time, details map[string]any) error {
	if _, err := q.Exec(ctx,
		`UPDATE samples SET current_holder_id = $2, updated_at = $3 WHERE id = $1`,
		sampleID, holderID, now); err != nil {
		return err
	}
	if details == nil {
		details = map[string]any{}
	}
	details["currentHolderId"] = holderID.String()
	rec := auditRecord{Action: action, EntityType: "sample", EntityID: sampleID.String(),
		Success: true, OccurredAt: now, Details: details}
	if actor != nil {
		rec.ActorID = actor.actorID()
		rec.Role = actor.Role
	} else {
		rec.Role = "system"
	}
	s.auditTx(ctx, q, rec)
	s.publishEvent(ctx, q, RealtimeEvent{
		Type: "sample.custody", EntityType: "sample", EntityID: sampleID.String(),
		Payload:  details,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{holderID},
	})
	return nil
}

// custodyRoles are the roles permitted to hold custody of a sealed sample.
var custodyRoles = []string{RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam}

func isCustodyRole(role string) bool { return containsString(custodyRoles, role) }
