{"command":"create","path":"/workspace/backend/internal/app/idempotency.go","file_text":"package app

import (
	"context"
	"encoding/json"
	"errors"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"
)

type storedResponse struct {
	StatusCode int
	Body       json.RawMessage
}

// lookupIdempotent returns a previously stored response for this scope and key. A reuse of the
// same key with a different payload is a conflict, so repeated or delayed retries never create
// duplicate work.
func (s *Server) lookupIdempotent(ctx context.Context, scope, key string, actorID uuid.UUID,
	requestHash string) (*storedResponse, error) {
	if key == "" {
		return nil, errIdemRequired
	}
	var (
		storedHash  string
		storedActor *uuid.UUID
		status      int
		body        []byte
	)
	err := s.pool.QueryRow(ctx,
		`SELECT request_hash, actor_id, status_code, response FROM idempotency_keys
         WHERE scope = $1 AND key = $2`, scope, key).Scan(&storedHash, &storedActor, &status, &body)
	if errors.Is(err, pgx.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	if storedHash != requestHash {
		return nil, errIdemConflict
	}
	if storedActor != nil && *storedActor != actorID {
		return nil, errIdemConflict
	}
	return &storedResponse{StatusCode: status, Body: body}, nil
}

func (s *Server) saveIdempotent(ctx context.Context, q querier, scope, key string,
	actorID uuid.UUID, requestHash string, status int, body any) error {
	if key == "" {
		return nil
	}
	_, err := q.Exec(ctx,
		`INSERT INTO idempotency_keys (scope, key, actor_id, request_hash, status_code, response)
         VALUES ($1, $2, $3, $4, $5, $6)
         ON CONFLICT (scope, key) DO NOTHING`,
		scope, key, actorID, requestHash, status, mustJSON(body))
	return err
}
