func isUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	if ok := asPgError(err, &pgErr); ok {
		return pgErr.Code == "23505" || pgErr.Code == "23505" || pgErr.Code == "23505" ||
			pgErr.Code == "23505" || pgErr.Code == "23505" || pgErr.Code == "23505" ||
