	if err := decodeBody(r, &body); err != nil {
		return err
	}
	from, okFrom := parseUUID(body.FromLocationID)
	to, okTo := parseUUID(body.ToLocationID)
	if !okFrom || !okTo {
		return errf(http.StatusBadRequest, "invalid_connection", "both endpoints are required")
	}
	if from == to {
		return errf(http.StatusBadRequest, "invalid_connection",
			"a connection must join two different locations")
	}
	if body.TravelMinutes < 0 {
		return errf(http.StatusBadRequest, "invalid_connection", "travelMinutes must not be negative")
	}
	if body.CostUnits < 0 {
		return errf(http.StatusBadRequest, "invalid_connection", "costUnits must not be negative")
	}
	if _, err := s.locationByID(r.Context(), s.pool, from); err != nil {
		return errf(http.StatusBadRequest, "invalid_connection", "fromLocationId does not exist")
	}
	if _, err := s.locationByID(r.Context(), s.pool, to); err != nil {
		return errf(http.StatusBadRequest, "invalid_connection", "toLocationId does not exist")
	}

	id := uuid.New()
	if _, err := s.pool.Exec(r.Context(),
		`INSERT INTO connections (id, from_location_id, to_location_id, travel_minutes, cost_units,
             cooled, active) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		id, from, to, body.TravelMinutes, body.CostUnits, body.Cooled, body.Active); err != nil {
		return errInternal
	}
	conn, err := s.connectionByID(r.Context(), s.pool, id)
	if err != nil {
		return errInternal
	}
	s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "create_connection", EntityType: "connection", EntityID: id.String(), Success: true,
		Details: map[string]any{"fromLocationId": from.String(), "toLocationId": to.String(),
			"travelMinutes": body.TravelMinutes, "cooled": body.Cooled, "active": body.Active}})
