// handleConfigureCapacity sets regular and cooled capacity for a node, laboratory or connection.
func (s *Server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	if rc.Role == "" {
		return errRoleNotSet
	}
	var body struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	id, ok := parseUUID(body.ResourceID)
	if !ok {
		return errf(http.StatusBadRequest, "invalid_capacity", "resourceId is not a valid id")
	}
	if body.CapacityUnits < 0 {
		return errf(http.StatusBadRequest, "invalid_capacity", "capacityUnits must not be negative")
	}
	if body.CooledCapacityUnits != nil && *body.CooledCapacityUnits < 0 {
		return errf(http.StatusBadRequest, "invalid_capacity",
			"cooledCapacityUnits must not be negative")
	}

	loc, locErr := s.locationByID(r.Context(), s.pool, id)
	if locErr == nil {
		// Node handlers and laboratory operators may configure only their own assigned location.
		switch rc.Role {
		case RoleAdministrator, RoleDispatcher:
		case RoleNodeHandler, RoleLaboratoryTeam:
			if rc.User.AssignedLocationID == nil || *rc.User.AssignedLocationID != id {
				return errForbidden
			}
		default:
			return errForbidden
		}
		cooled := loc.CooledCapacityUnits
		if body.CooledCapacityUnits != nil {
			cooled = *body.CooledCapacityUnits
		}
		if body.CapacityUnits < loc.ReservedUnits || cooled < loc.CooledReservedUnits {
			return errf(http.StatusConflict, "capacity_reserved",
				"capacity is already reserved above the requested configuration")
		}
		if _, err := s.pool.Exec(r.Context(),
			`UPDATE locations SET capacity_units = $2, cooled_capacity_units = $3 WHERE id = $1`,
			id, body.CapacityUnits, cooled); err != nil {
			return errInternal
		}
		s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role,
			Action: "configure_capacity", EntityType: "location", EntityID: id.String(),
			Success: true, Details: map[string]any{"capacityUnits": body.CapacityUnits,
				"cooledCapacityUnits": cooled}})
		s.bumpNetworkRevision(r.Context())
		writeData(w, http.StatusOK, map[string]any{"resourceId": id.String(),
			"capacityUnits": body.CapacityUnits, "cooledCapacityUnits": cooled})
		return nil
	}

	conn, connErr := s.connectionByID(r.Context(), s.pool, id)
	if connErr != nil {
		return errf(http.StatusBadRequest, "invalid_capacity", "resourceId does not exist")
	}
	if err := rc.requireRole(RoleAdministrator, RoleDispatcher); err != nil {
		return err
	}
	cooled := conn.CooledCapacityUnits
	if body.CooledCapacityUnits != nil {
		cooled = *body.CooledCapacityUnits
	}
	if body.CapacityUnits < conn.ReservedUnits || cooled < conn.CooledReservedUnits {
		return errf(http.StatusConflict, "capacity_reserved",
			"capacity is already reserved above the requested configuration")
	}
	if _, err := s.pool.Exec(r.Context(),
		`UPDATE connections SET capacity_units = $2, cooled_capacity_units = $3 WHERE id = $1`,
		id, body.CapacityUnits, cooled); err != nil {
		return errInternal
	}
	s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "configure_capacity", EntityType: "connection", EntityID: id.String(),
		Success: true, Details: map[string]any{"capacityUnits": body.CapacityUnits,
			"cooledCapacityUnits": cooled}})
	s.bumpNetworkRevision(r.Context())
	writeData(w, http.StatusOK, map[string]any{"resourceId": id.String(),
		"capacityUnits": body.CapacityUnits, "cooledCapacityUnits": cooled})
	return nil
}

func (s *Server) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	if err := rc.requireRole(RoleAdministrator); err != nil {
		return err
	}
	var body struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	labID, okLab := parseUUID(body.LaboratoryID)
	typeID, okType := parseUUID(body.SampleTypeID)
	if !okLab || !okType {
		return errf(http.StatusBadRequest, "invalid_acceptance",
			"laboratoryId and sampleTypeId are required")
	}
	loc, err := s.locationByID(r.Context(), s.pool, labID)
	if err != nil {
		return errf(http.StatusBadRequest, "invalid_acceptance", "laboratoryId does not exist")
	}
	if !loc.Functions.Laboratory {
		return errf(http.StatusBadRequest, "invalid_acceptance",
			"location %q does not provide the laboratory function", loc.Name)
	}
	if _, err := s.sampleTypeByID(r.Context(), s.pool, typeID); err != nil {
		return errf(http.StatusBadRequest, "invalid_acceptance", "sampleTypeId does not exist")
	}
	var acceptanceID uuid.UUID
	if err := s.pool.QueryRow(r.Context(),
		`INSERT INTO laboratory_acceptance (id, laboratory_id, sample_type_id, accepts)
         VALUES ($1, $2, $3, $4)
         ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts = EXCLUDED.accepts
         RETURNING id`,
