		return errInternal
	}
	s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "configure_laboratory_acceptance", EntityType: "location", EntityID: labID.String(),
		Success: true, Details: map[string]any{"sampleTypeId": typeID.String(), "accepts": body.Accepts}})
	s.bumpNetworkRevision(r.Context())
	writeData(w, http.StatusOK, map[string]any{
		"acceptanceId": acceptanceID.String(), "accepts": body.Accepts})
	return nil
}

func (s *Server) handleCreateSampleType(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	if err := rc.requireRole(RoleAdministrator); err != nil {
		return err
	}
	var body struct {
		Name                       string   `json:"name"`
		QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        bool     `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
