	}
	if body.TemperatureMinC > body.TemperatureMaxC {
		return errf(http.StatusBadRequest, "invalid_handling_rule",
			"temperatureMinC must not exceed temperatureMaxC")
	}
	if body.QualifiedCollectorRequired && strings.TrimSpace(body.RequiredQualification) == "" {
		return errf(http.StatusBadRequest, "invalid_handling_rule",
			"requiredQualification is required when a qualified collector is required")
	}
	incompatible, err := s.resolveSampleTypeIDs(r, body.IncompatibleSampleTypes)
	if err != nil {
		return err
	}
	batching := true
	if body.BatchingAllowed != nil {
		batching = *body.BatchingAllowed
	}
	id := uuid.New()
	if _, err := s.pool.Exec(r.Context(),
		`INSERT INTO sample_types (id, name, qualified_collector_required, required_qualification,
             container_type, temperature_min_c, temperature_max_c, incompatible_sample_types,
