	}
	st, err := s.sampleTypeByID(r.Context(), s.pool, id)
	if err != nil {
		return errInternal
	}
	s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "create_sample_type", EntityType: "sample_type", EntityID: id.String(),
		Success: true, Details: st.API()})
	s.bumpNetworkRevision(r.Context())
	writeData(w, http.StatusCreated, st.API())
	return nil
}

func (s *Server) handleUpdateSampleType(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	if err := rc.requireRole(RoleAdministrator); err != nil {
		return err
	}
	var body struct {
		SampleTypeID               string   `json:"sampleTypeId"`
		QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
		RequiredQualification      *string  `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
		BatchingAllowed            *bool    `json:"batchingAllowed"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	id, ok := parseUUID(body.SampleTypeID)
	if !ok {
		return errNotFound
	}
	existing, err := s.sampleTypeByID(r.Context(), s.pool, id)
	if err != nil {
		return err
	}
	if strings.TrimSpace(body.ContainerType) == "" {
		return errf(http.StatusBadRequest, "invalid_handling_rule", "containerType is required")
	}
	if body.TemperatureMinC > body.TemperatureMaxC {
		return errf(http.StatusBadRequest, "invalid_handling_rule",
			"temperatureMinC must not exceed temperatureMaxC")
	}
	qualifiedRequired := existing.QualifiedCollectorRequired
	if body.QualifiedCollectorRequired != nil {
		qualifiedRequired = *body.QualifiedCollectorRequired
	}
	qualification := existing.RequiredQualification
	if body.RequiredQualification != nil {
		qualification = *body.RequiredQualification
	}
	if qualifiedRequired && strings.TrimSpace(qualification) == "" {
		return errf(http.StatusBadRequest, "invalid_handling_rule",
			"requiredQualification is required when a qualified collector is required")
	}
	incompatible := existing.IncompatibleSampleTypes
	if body.IncompatibleSampleTypes != nil {
		incompatible, err = s.resolveSampleTypeIDs(r, body.IncompatibleSampleTypes)
		if err != nil {
			return err
		}
	}
	cooled := existing.RequiresCooledRoute
	if body.RequiresCooledRoute != nil {
		cooled = *body.RequiresCooledRoute
	}
	batching := existing.BatchingAllowed
	if body.BatchingAllowed != nil {
		batching = *body.BatchingAllowed
	}
	if _, err := s.pool.Exec(r.Context(),
		`UPDATE sample_types SET qualified_collector_required = $2, required_qualification = $3,
             container_type = $4, temperature_min_c = $5, temperature_max_c = $6,
             incompatible_sample_types = $7, requires_cooled_route = $8, batching_allowed = $9
         WHERE id = $1`,
		id, qualifiedRequired, qualification, body.ContainerType, body.TemperatureMinC,
		body.TemperatureMaxC, incompatible, cooled, batching); err != nil {
		return errInternal
	}
	st, err := s.sampleTypeByID(r.Context(), s.pool, id)
	if err != nil {
		return errInternal
	}
	s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "update_sample_type", EntityType: "sample_type", EntityID: id.String(),
		Success: true, Details: st.API()})
	s.bumpNetworkRevision(r.Context())
	writeData(w, http.StatusCreated, st.API())
	return nil
}

func (s *Server) resolveSampleTypeIDs(r *http.Request, raw []string) ([]uuid.UUID, error) {
	out := []uuid.UUID{}
	for _, value := range raw {
		id, ok := parseUUID(value)
		if !ok {
			return nil, errf(http.StatusBadRequest, "invalid_handling_rule",
				"incompatibleSampleTypes contains an invalid id")
		}
		if _, err := s.sampleTypeByID(r.Context(), s.pool, id); err != nil {
			return nil, errf(http.StatusBadRequest, "invalid_handling_rule",
				"incompatibleSampleTypes references an unknown sample type")
		}
		out = append(out, id)
	}
	return out, nil
}
