		out["journeyId"] = journey.ID.String()
		out["targetLaboratoryId"] = p.LaboratoryID.String()
	}

	if in.IdempotencyKey != "" {
		if err := s.saveIdempotent(r.Context(), tx, scope, in.IdempotencyKey, rc.User.ID, hash,
			http.StatusCreated, map[string]any{"data": out}); err != nil {
			return errInternal
		}
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "sample.created", EntityType: "sample",
		EntityID: sampleID.String(),
