// handleAcceptAssignment accepts an offer. An assignment cannot be accepted by anyone other than
// the worker it was offered to.
func (s *Server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	id, ok := parseUUID(body.AssignmentID)
	if !ok {
		return errNotFound
	}
	stored, err := s.lookupIdempotent(r.Context(), "accept-assignment", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	now := s.now()
	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	var locked uuid.UUID
	if err := tx.QueryRow(r.Context(),
		`SELECT id FROM assignments WHERE id = $1 FOR UPDATE`, id).Scan(&locked); err != nil {
		return errNotFound
	}
	a, err := s.assignmentByID(r.Context(), tx, id)
	if err != nil {
		return err
	}
	if rc.Role != roleForAssignmentKind(a.Kind) {
		return errForbidden
	}
	if assignmentTerminal(a.Status) {
		return errf(http.StatusConflict, "assignment_inactive",
			"assignment is no longer active (status %s)", a.Status)
	}
	if a.Status == "accepted" || a.WorkerID != nil {
		if a.WorkerID != nil && *a.WorkerID == rc.User.ID {
			out := map[string]any{"assignmentId": id.String(), "workerId": rc.User.ID.String(),
				"status": "accepted"}
			if err := s.saveIdempotent(r.Context(), tx, "accept-assignment", body.IdempotencyKey,
				rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
				return errInternal
			}
			if err := tx.Commit(r.Context()); err != nil {
				return errInternal
			}
			writeData(w, http.StatusCreated, out)
			return nil
		}
		return errf(http.StatusConflict, "assignment_taken",
			"assignment has already been accepted by another worker")
	}
	if a.Status != "offered" || a.OfferedTo == nil {
		return errf(http.StatusConflict, "offer_not_available",
			"assignment is not currently offered")
	}
	if *a.OfferedTo != rc.User.ID {
		return errf(http.StatusConflict, "offer_not_offered",
			"assignment was offered to another worker")
	}
	if !rc.User.Available {
		return errf(http.StatusConflict, "worker_unavailable", "worker is marked unavailable")
	}
	if a.RequiredQualification != "" && !rc.User.HasQualification(a.RequiredQualification, now) {
		return errf(http.StatusForbidden, "ineligible_worker",
			"worker does not hold qualification %q", a.RequiredQualification)
	}
	if requiredLocation := assignmentLocation(a); requiredLocation != nil {
		if rc.User.AssignedLocationID == nil || *rc.User.AssignedLocationID != *requiredLocation {
			return errf(http.StatusForbidden, "ineligible_worker",
				"worker is not assigned to the required node or laboratory")
		}
	}

	if _, err := tx.Exec(r.Context(),
		`UPDATE assignments SET status = 'accepted', worker_id = $2, offered_to = NULL,
             offer_expires_at = NULL, accepted_at = $3, updated_at = $3 WHERE id = $1`,
		id, rc.User.ID, now); err != nil {
		return errInternal
	}
	// Accepting work clears the temporary decline penalty.
	if _, err := tx.Exec(r.Context(),
		`UPDATE users SET decline_count = 0, penalty_until = NULL WHERE id = $1`, rc.User.ID); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "accept_assignment", EntityType: "assignment", EntityID: id.String(),
		Success: true, OccurredAt: now,
		Details: map[string]any{"kind": a.Kind, "workerId": rc.User.ID.String(),
			"sampleId": uuidPtrString(a.SampleID)}})

	out := map[string]any{"assignmentId": id.String(), "workerId": rc.User.ID.String(),
		"status": "accepted"}
	if err := s.saveIdempotent(r.Context(), tx, "accept-assignment", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "assignment.accepted",
		EntityType: "assignment", EntityID: id.String(),
		Payload: map[string]any{"assignmentId": id.String(), "workerId": rc.User.ID.String(),
			"kind": a.Kind, "sampleId": uuidPtrString(a.SampleID)},
		audience: []string{RoleDispatcher, RoleAdministrator, a.RequiredRole},
		userIDs:  []uuid.UUID{rc.User.ID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

func assignmentLocation(a *Assignment) *uuid.UUID {
	switch a.Kind {
	case "node":
		return a.NodeID
	case "laboratory":
		return a.LaboratoryID
	}
	return nil
}

// handleDeclineAssignment declines an offer and re-offers it to the next eligible worker. A
// worker who declines may still receive suitable work later.
func (s *Server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		AssignmentID   string  `json:"assignmentId"`
		Reason         *string `json:"reason"`
		DeclinedAt     *string `json:"declinedAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	id, ok := parseUUID(body.AssignmentID)
	if !ok {
		return errNotFound
	}
	now := s.now()
	if body.DeclinedAt != nil && *body.DeclinedAt != "" {
		now, err = parseTimeCode(*body.DeclinedAt, "invalid_time")
		if err != nil {
			return err
		}
	}
	stored, err := s.lookupIdempotent(r.Context(), "decline-assignment", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	var locked uuid.UUID
	if err := tx.QueryRow(r.Context(),
		`SELECT id FROM assignments WHERE id = $1 FOR UPDATE`, id).Scan(&locked); err != nil {
		return errNotFound
	}
	a, err := s.assignmentByID(r.Context(), tx, id)
	if err != nil {
		return err
	}
	if rc.Role != roleForAssignmentKind(a.Kind) {
		return errForbidden
	}
	if a.Status != "offered" || a.OfferedTo == nil || *a.OfferedTo != rc.User.ID {
		return errf(http.StatusConflict, "offer_not_available",
			"assignment is not currently offered to this worker")
	}

	if _, err := tx.Exec(r.Context(),
		`UPDATE assignments SET status = 'pending', offered_to = NULL, offer_expires_at = NULL,
             declined_by = array_append(declined_by, $2), updated_at = $3 WHERE id = $1`,
		id, rc.User.ID, now); err != nil {
		return errInternal
	}
	if err := s.applyDeclinePenalty(r.Context(), tx, rc.User.ID, now); err != nil {
		return errInternal
	}
	reason := ""
	if body.Reason != nil {
		reason = *body.Reason
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "decline_assignment", EntityType: "assignment", EntityID: id.String(),
		Success: true, OccurredAt: now,
		Details: map[string]any{"kind": a.Kind, "reason": reason, "workerId": rc.User.ID.String()}})

	refreshed, err := s.assignmentByID(r.Context(), tx, id)
	if err != nil {
		return errInternal
	}
	reoffered, err := s.offerAssignment(r.Context(), tx, refreshed, now)
	if err != nil {
		return err
	}

	out := map[string]any{
		"assignmentId": id.String(),
		"status":       "pending",
		"declinedBy":   rc.User.ID.String(),
		"declinedAt":   rfc3339(now),
	}
	if reoffered != nil && reoffered.OfferedTo != nil {
		out["reofferedTo"] = reoffered.OfferedTo.String()
	}
	if err := s.saveIdempotent(r.Context(), tx, "decline-assignment", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleCollectAndSealSample records that a sample was collected and sealed inside its window.
func (s *Server) handleCollectAndSealSample(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if err := rc.requireRole(RoleCollectionPro); err != nil {
		return err
	}
	sampleID, okSample := parseUUID(body.SampleID)
	assignmentID, okAssignment := parseUUID(body.AssignmentID)
	if !okSample || !okAssignment {
		return errNotFound
	}
	collectedAt, err := parseTimeCode(body.CollectedAt, "invalid_time")
	if err != nil {
		return err
	}
	stored, err := s.lookupIdempotent(r.Context(), "collect-and-seal-sample", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	now := s.now()
	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	a, err := s.assignmentByID(r.Context(), tx, assignmentID)
	if err != nil {
		return err
	}
	if a.Kind != "collection" {
		return errf(http.StatusConflict, "invalid_sample_state",
			"assignment %s is not a collection assignment", assignmentID)
	}
	if a.WorkerID == nil || *a.WorkerID != rc.User.ID {
		return errForbidden
	}
	if assignmentTerminal(a.Status) {
		return errf(http.StatusConflict, "assignment_inactive",
			"collection assignment is no longer active")
	}
	if a.SampleID == nil || *a.SampleID != sampleID {
		return errf(http.StatusConflict, "invalid_sample_state",
			"assignment does not cover sample %s", sampleID)
	}
	sm, err := s.sampleByID(r.Context(), tx, sampleID)
	if err != nil {
		return err
	}
	if sm.Sealed {
		return errf(http.StatusConflict, "invalid_sample_state", "sample is already sealed")
	}
	if sampleTerminal(sm.Status) {
		return errf(http.StatusConflict, "invalid_sample_state",
			"sample is in terminal state %s", sm.Status)
	}
	req, err := s.requestByID(r.Context(), tx, sm.RequestID)
	if err != nil {
		return errInternal
	}
	// Collection must take place inside the collection window.
	if collectedAt.Before(req.EarliestCollectionAt) || collectedAt.After(req.LatestCollectionAt) {
		return errf(http.StatusConflict, "outside_collection_window",
			"collectedAt is outside the collection window %s..%s",
			rfc3339(req.EarliestCollectionAt), rfc3339(req.LatestCollectionAt))
	}
	st, err := s.sampleTypeByID(r.Context(), tx, sm.SampleTypeID)
	if err != nil {
		return errInternal
	}
	// Only a certified collection professional holding the matching qualification may collect.
	if st.QualifiedCollectorRequired {
		if !rc.User.HasQualification(st.RequiredQualification, now) {
			return errf(http.StatusForbidden, "ineligible_worker",
				"worker does not hold qualification %q", st.RequiredQualification)
		}
		if !rc.User.CertificationActive(st.RequiredQualification, now) {
			return errf(http.StatusConflict, "certification_inactive",
				"certification %q is not currently active", st.RequiredQualification)
		}
	}

	compliant := body.ContainerType == st.ContainerType &&
		body.ObservedTemperatureC >= st.TemperatureMinC-1e-9 &&
		body.ObservedTemperatureC <= st.TemperatureMaxC+1e-9
	if _, err := tx.Exec(r.Context(),
		`INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id,
             container_type, observed_temperature, compliant, recorded_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
		uuid.New(), sampleID, assignmentID, a.ToLocationID, body.ContainerType,
		body.ObservedTemperatureC, compliant, collectedAt); err != nil {
		return errInternal
	}
	if !compliant {
		s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
			Action: "collect_and_seal_sample", EntityType: "sample", EntityID: sampleID.String(),
			Success: false, OccurredAt: collectedAt,
			Details: map[string]any{"reason": "handling_noncompliant",
				"containerType": body.ContainerType, "observedTemperatureC": body.ObservedTemperatureC,
				"requiredContainerType": st.ContainerType}})
		if err := s.markSampleException(r.Context(), tx, sampleID, exceptionHandlingBreach,
			"observed container or temperature is outside the required range", collectedAt, nil); err != nil {
			return errInternal
		}
		if err := tx.Commit(r.Context()); err != nil {
			return errInternal
		}
		return errf(http.StatusBadRequest, "handling_noncompliant",
			"observed container or temperature is outside the required range for %s", st.Name)
	}

	// The collector becomes the sole current holder of the sealed sample.
	if _, err := tx.Exec(r.Context(),
		`UPDATE samples SET status = $2, sealed = true, sealed_at = $3, current_holder_id = $4,
             updated_at = $3 WHERE id = $1`,
		sampleID, statusSealed, collectedAt, rc.User.ID); err != nil {
		return errInternal
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE assignments SET status = 'completed', completed_at = $2, updated_at = $2
         WHERE id = $1`, assignmentID, collectedAt); err != nil {
		return errInternal
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE journey_stops SET completed_at = $2 WHERE journey_id = $3 AND sequence = 1
             AND completed_at IS NULL`, nil, collectedAt, a.JourneyID); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "collect_and_seal_sample", EntityType: "sample", EntityID: sampleID.String(),
		Success: true, OccurredAt: collectedAt,
		Details: map[string]any{"status": statusSealed, "sealedAt": rfc3339(collectedAt),
			"currentHolderId": rc.User.ID.String(), "containerType": body.ContainerType,
			"observedTemperatureC": body.ObservedTemperatureC, "assignmentId": assignmentID.String()}})
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "custody_assumed", EntityType: "assignment", EntityID: assignmentID.String(),
		Success: true, OccurredAt: collectedAt,
		Details: map[string]any{"sampleId": sampleID.String(), "status": "completed"}})

	out := map[string]any{
		"sampleId":          sampleID.String(),
		"status":            statusSealed,
		"currentHolderId":   rc.User.ID.String(),
		"sealedAt":          rfc3339(collectedAt),
		"handlingCompliant": true,
	}
	if err := s.saveIdempotent(r.Context(), tx, "collect-and-seal-sample", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "sample.sealed", EntityType: "sample",
		EntityID: sampleID.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator, RoleDeliveryPartner},
		userIDs:  []uuid.UUID{sm.RequesterID, rc.User.ID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleRecordWorkerLocation records the worker's current position on an assignment.
func (s *Server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		Sequence     int        `json:"sequence"`
		RecordedAt   string     `json:"recordedAt"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	id, ok := parseUUID(body.AssignmentID)
	if !ok {
		return errNotFound
	}
	if !body.Coordinate.valid() {
		return errf(http.StatusBadRequest, "invalid_coordinate", "coordinate is out of range")
	}
	if body.Sequence < 0 {
		return errf(http.StatusBadRequest, "invalid_sequence", "sequence must not be negative")
	}
	recordedAt, err := parseTimeCode(body.RecordedAt, "invalid_time")
	if err != nil {
		return err
	}

	a, err := s.assignmentByID(r.Context(), s.pool, id)
	if err != nil {
		return err
	}
	if a.WorkerID == nil || *a.WorkerID != rc.User.ID {
		return errForbidden
	}
	if rc.Role != roleForAssignmentKind(a.Kind) {
		return errForbidden
	}

	// Out-of-order updates must not overwrite a newer position.
	var latestSeq *int
	if err := s.pool.QueryRow(r.Context(),
		`SELECT max(sequence) FROM worker_locations WHERE worker_id = $1 AND assignment_id = $2`,
		rc.User.ID, id).Scan(&latestSeq); err != nil {
		return errInternal
	}
	if latestSeq != nil && body.Sequence <= *latestSeq {
		return errf(http.StatusConflict, "stale_location",
			"a location with sequence %d has already been recorded", *latestSeq)
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	if _, err := tx.Exec(r.Context(),
		`INSERT INTO worker_locations (id, worker_id, assignment_id, latitude, longitude,
             sequence, recorded_at) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		uuid.New(), rc.User.ID, id, body.Coordinate.Latitude, body.Coordinate.Longitude,
		body.Sequence, recordedAt); err != nil {
		return errInternal
	}
	if a.SampleID != nil {
		sm, err := s.sampleByID(r.Context(), tx, *a.SampleID)
		if err == nil && sm.CurrentHolderID != nil && *sm.CurrentHolderID == rc.User.ID {
			if err := s.recordSampleLocation(r.Context(), tx, *a.SampleID, body.Coordinate, recordedAt); err != nil {
				return errInternal
			}
		}
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "record_worker_location", EntityType: "assignment", EntityID: id.String(),
		Success: true, OccurredAt: recordedAt,
		Details: map[string]any{"coordinate": body.Coordinate, "sequence": body.Sequence,
			"sampleId": uuidPtrString(a.SampleID)}})
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "worker.location", EntityType: "worker",
		EntityID: rc.User.ID.String(),
		Payload: map[string]any{"workerId": rc.User.ID.String(), "assignmentId": id.String(),
			"coordinate": body.Coordinate, "recordedAt": rfc3339(recordedAt)},
		audience: []string{RoleDispatcher, RoleAdministrator}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, map[string]any{
		"assignmentId": id.String(),
		"coordinate":   body.Coordinate,
		"sequence":     body.Sequence,
		"recordedAt":   rfc3339(recordedAt),
	})
	return nil
}

// handleRecordHandlingCheckpoint records observed container and temperature while holding custody.
func (s *Server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
