		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if !isCustodyRole(rc.Role) {
		return errForbidden
	}
	sampleID, okSample := parseUUID(body.SampleID)
	assignmentID, okAssignment := parseUUID(body.AssignmentID)
	if !okSample || !okAssignment {
		return errNotFound
	}
	recordedAt, err := parseTimeCode(body.RecordedAt, "invalid_time")
	if err != nil {
		return err
	}
	stored, err := s.lookupIdempotent(r.Context(), "record-handling-checkpoint", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	a, err := s.assignmentByID(r.Context(), s.pool, assignmentID)
	if err != nil {
		return err
	}
	if a.WorkerID == nil || *a.WorkerID != rc.User.ID {
		return errForbidden
	}
	if assignmentTerminal(a.Status) {
		return errf(http.StatusConflict, "assignment_inactive", "assignment is no longer active")
	}
	sm, err := s.sampleByID(r.Context(), s.pool, sampleID)
	if err != nil {
		return err
	}
	if sampleTerminal(sm.Status) {
		return errf(http.StatusConflict, "terminal_sample",
			"sample is in terminal state %s", sm.Status)
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != rc.User.ID {
		return errf(http.StatusForbidden, "forbidden", "only the current holder may record a checkpoint")
	}
	st, err := s.sampleTypeByID(r.Context(), s.pool, sm.SampleTypeID)
	if err != nil {
		return errInternal
	}
	var locationID *uuid.UUID
	if body.LocationID != nil && *body.LocationID != "" {
		id, ok := parseUUID(*body.LocationID)
		if !ok {
			return errf(http.StatusBadRequest, "invalid_json", "locationId is not a valid id")
		}
		locationID = &id
	}

	compliant := body.ContainerType == st.ContainerType &&
		body.ObservedTemperatureC >= st.TemperatureMinC-1e-9 &&
		body.ObservedTemperatureC <= st.TemperatureMaxC+1e-9

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	checkpointID := uuid.New()
	if _, err := tx.Exec(r.Context(),
		`INSERT INTO handling_checkpoints (id, sample_id, assignment_id, location_id,
             container_type, observed_temperature, compliant, recorded_at)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8)`,
		checkpointID, sampleID, assignmentID, locationID, body.ContainerType,
		body.ObservedTemperatureC, compliant, recordedAt); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "record_handling_checkpoint", EntityType: "sample", EntityID: sampleID.String(),
		Success: compliant, OccurredAt: recordedAt,
		Details: map[string]any{"checkpointId": checkpointID.String(), "compliant": compliant,
			"containerType": body.ContainerType, "observedTemperatureC": body.ObservedTemperatureC,
			"assignmentId": assignmentID.String()}})

	status := sm.Status
	if !compliant {
		// An observation outside the required range marks the sample as an exception.
		if err := s.markSampleException(r.Context(), tx, sampleID, exceptionHandlingBreach,
			"observed container or temperature is outside the required range", recordedAt, nil); err != nil {
			return errInternal
		}
		status = statusException
	}
	out := map[string]any{
		"checkpointId": checkpointID.String(),
		"sampleId":     sampleID.String(),
		"compliant":    compliant,
		"sampleStatus": status,
	}
	if err := s.saveIdempotent(r.Context(), tx, "record-handling-checkpoint", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// progressOrder defines the permitted forward transitions for an assignment.
var progressOrder = map[string]int{
	"accepted": 0, "at_pickup": 1, "picked_up": 2, "in_transit": 3, "arrived": 4,
	"delivered": 5, "in_progress": 1, "completed": 6,
}

// handleUpdateAssignmentProgress records progress on an assignment. Pickup must happen before
// delivery and custody is required before a sealed sample can move.
func (s *Server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	id, ok := parseUUID(body.AssignmentID)
	if !ok {
		return errNotFound
	}
	if _, valid := progressOrder[body.Status]; !valid {
		return errf(http.StatusBadRequest, "invalid_json", "unknown status %q", body.Status)
	}
	occurredAt, err := parseTimeCode(body.OccurredAt, "invalid_time")
	if err != nil {
		return err
	}
	stored, err := s.lookupIdempotent(r.Context(), "update-assignment-progress", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	var locked uuid.UUID
	if err := tx.QueryRow(r.Context(),
		`SELECT id FROM assignments WHERE id = $1 FOR UPDATE`, id).Scan(&locked); err != nil {
		return errNotFound
	}
	a, err := s.assignmentByID(r.Context(), tx, id)
	if err != nil {
		return err
	}
	if a.WorkerID == nil || *a.WorkerID != rc.User.ID {
		return errForbidden
	}
	if rc.Role != roleForAssignmentKind(a.Kind) {
		return errForbidden
	}
	if assignmentTerminal(a.Status) {
		return errf(http.StatusConflict, "assignment_inactive",
			"assignment is no longer active (status %s)", a.Status)
	}
	if a.Status == "pending" || a.Status == "offered" {
		return errf(http.StatusConflict, "assignment_not_ready",
			"assignment has not been accepted yet")
	}
	currentRank, ok := progressOrder[a.Status]
	if !ok {
		currentRank = 0
	}
	newRank := progressOrder[body.Status]
	if newRank <= currentRank {
		return errf(http.StatusConflict, "invalid_transition",
			"cannot move from %s to %s", a.Status, body.Status)
	}

	if a.SampleID != nil {
		sm, err := s.sampleByID(r.Context(), tx, *a.SampleID)
		if err != nil {
			return errInternal
		}
		req, err := s.requestByID(r.Context(), tx, sm.RequestID)
		if err != nil {
			return errInternal
		}
		if a.Kind == "transport" {
			// Collection must happen before transport.
			if !sm.Sealed {
				return errf(http.StatusConflict, "collection_required",
					"the sample has not been collected and sealed yet")
			}
			// Responsibility must be transferred through a confirmed handoff before continuing.
			if sm.CurrentHolderID == nil || *sm.CurrentHolderID != rc.User.ID {
				return errf(http.StatusConflict, "custody_required",
					"custody of the sample has not been transferred to this worker")
			}
			if err := s.requirePriorLegsComplete(r.Context(), tx, a); err != nil {
				return err
			}
		}
		if newRank >= progressOrder["delivered"] && occurredAt.After(req.DeliveryDeadline) {
			if err := s.markSampleException(r.Context(), tx, *a.SampleID, exceptionDeadlineMissed,
				"the delivery deadline passed before the sample was delivered", occurredAt, nil); err != nil {
				return errInternal
			}
			if err := tx.Commit(r.Context()); err != nil {
				return errInternal
			}
			return errf(http.StatusConflict, "delivery_deadline_exceeded",
				"the delivery deadline %s has passed", rfc3339(req.DeliveryDeadline))
		}
	}

	newStatus := body.Status
	pickedUp := a.PickedUp || newRank >= progressOrder["picked_up"]
	var completedAt *time.Time
	if newStatus == "completed" {
		completedAt = &occurredAt
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE assignments SET status = $2, picked_up = $3, completed_at = $4, updated_at = $5
         WHERE id = $1`, id, newStatus, pickedUp, completedAt, occurredAt); err != nil {
		return errInternal
	}
	if a.SampleID != nil {
		sampleStatus := ""
		switch {
		case a.Kind == "transport" && newRank >= progressOrder["in_transit"] && newRank < progressOrder["delivered"]:
			sampleStatus = statusInTransit
		case a.Kind == "transport" && newRank >= progressOrder["delivered"]:
			sampleStatus = statusAtNode
		case a.Kind == "node" && newRank >= progressOrder["in_progress"]:
			sampleStatus = statusAtNode
		case a.Kind == "laboratory" && newRank >= progressOrder["in_progress"]:
			sampleStatus = statusAtLab
		}
		if sampleStatus != "" {
			sm, err := s.sampleByID(r.Context(), tx, *a.SampleID)
			if err == nil && sm.Status != statusException && !sampleTerminal(sm.Status) {
				if err := s.setSampleStatus(r.Context(), tx, *a.SampleID, sampleStatus, rc,
					"assignment_progress", occurredAt,
					map[string]any{"assignmentId": id.String(), "assignmentStatus": newStatus}); err != nil {
					return errInternal
				}
			}
		}
		if newStatus == "delivered" || newStatus == "arrived" {
			if a.ToLocationID != nil {
				loc, err := s.locationByID(r.Context(), tx, *a.ToLocationID)
				if err == nil {
					if err := s.recordSampleLocation(r.Context(), tx, *a.SampleID, loc.Coordinate, occurredAt); err != nil {
						return errInternal
					}
					if _, err := tx.Exec(r.Context(),
						`UPDATE journey_stops SET completed_at = $3
                         WHERE journey_id = $1 AND location_id = $2 AND completed_at IS NULL`,
						a.JourneyID, *a.ToLocationID, occurredAt); err != nil {
						return errInternal
					}
				}
			}
		}
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "update_assignment_progress", EntityType: "assignment", EntityID: id.String(),
		Success: true, OccurredAt: occurredAt,
		Details: map[string]any{"status": newStatus, "previousStatus": a.Status,
			"sampleId": uuidPtrString(a.SampleID), "kind": a.Kind}})

	out := map[string]any{
		"assignmentId": id.String(),
		"sampleId":     uuidPtrString(a.SampleID),
		"status":       newStatus,
	}
	if err := s.saveIdempotent(r.Context(), tx, "update-assignment-progress", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "assignment.progress",
		EntityType: "assignment", EntityID: id.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{rc.User.ID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// requirePriorLegsComplete ensures earlier transport legs of the same journey have finished.
func (s *Server) requirePriorLegsComplete(ctx contextT, q querier, a *Assignment) error {
	if a.JourneyID == nil {
		return nil
	}
	var incomplete int
	if err := q.QueryRow(ctx,
		`SELECT count(*) FROM assignments
         WHERE journey_id = $1 AND sequence < $2 AND kind = 'transport'
           AND status NOT IN ('completed', 'cancelled', 'superseded')`,
		*a.JourneyID, a.Sequence).Scan(&incomplete); err != nil {
		return errInternal
	}
	if incomplete > 0 {
		return errf(http.StatusConflict, "prior_leg_incomplete",
			"an earlier transport leg has not been completed")
	}
	return nil
}
