{"command":"create","path":"/workspace/backend/internal/app/handlers_custody.go","file_text":"package app

import (
	"net/http"

	"github.com/google/uuid"
)

// handleInitiateHandoff starts a two-sided transfer of custody between adjacent legs.
func (s *Server) handleInitiateHandoff(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		SampleID       string `json:"sampleId"`
		FromAssignment string `json:"fromAssignmentId"`
		ToAssignment   string `json:"toAssignmentId"`
		ReceiverID     string `json:"receiverId"`
		InitiatedAt    string `json:"initiatedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if !isCustodyRole(rc.Role) {
		return errForbidden
	}
	sampleID, okSample := parseUUID(body.SampleID)
	fromID, okFrom := parseUUID(body.FromAssignment)
	toID, okTo := parseUUID(body.ToAssignment)
	receiverID, okReceiver := parseUUID(body.ReceiverID)
	if !okSample || !okFrom || !okTo {
		return errNotFound
	}
	if !okReceiver {
		return errf(http.StatusBadRequest, "invalid_receiver", "receiverId is required")
	}
	initiatedAt, err := parseTimeCode(body.InitiatedAt, "invalid_time")
	if err != nil {
		return err
	}
	stored, err := s.lookupIdempotent(r.Context(), "initiate-handoff", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	var lockedSample uuid.UUID
	if err := tx.QueryRow(r.Context(),
		`SELECT id FROM samples WHERE id = $1 FOR UPDATE`, sampleID).Scan(&lockedSample); err != nil {
		return errNotFound
	}
	sm, err := s.sampleByID(r.Context(), tx, sampleID)
	if err != nil {
		return err
	}
	if !sm.Sealed {
		return errf(http.StatusConflict, "invalid_assignment_state",
			"the sample has not been sealed yet")
	}
	// Until both sides confirm, the sender remains responsible; only the current holder may send.
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != rc.User.ID {
		return errf(http.StatusConflict, "not_current_holder",
			"only the current holder may initiate a handoff")
	}
	// Repeated handoff initiations must not create duplicate transfers of custody.
	if pending, err := s.pendingHandoff(r.Context(), tx, sampleID); err != nil {
		return errInternal
	} else if pending != nil {
		return errf(http.StatusConflict, "pending_handoff_exists",
			"a handoff for this sample is already pending confirmation")
	}

	from, err := s.assignmentByID(r.Context(), tx, fromID)
	if err != nil {
		return err
	}
	to, err := s.assignmentByID(r.Context(), tx, toID)
	if err != nil {
		return err
	}
	if from.WorkerID == nil || *from.WorkerID != rc.User.ID {
		return errf(http.StatusForbidden, "sender_assignment_mismatch",
			"fromAssignmentId does not belong to the sender")
	}
	if to.WorkerID == nil {
		return errf(http.StatusConflict, "receiver_assignment_mismatch",
			"the receiving assignment has no accepted worker")
	}
	if *to.WorkerID != receiverID {
		return errf(http.StatusConflict, "receiver_assignment_mismatch",
			"receiverId does not match the worker on the receiving assignment")
	}
	if receiverID == rc.User.ID {
		return errf(http.StatusBadRequest, "invalid_receiver",
			"a sample cannot be handed off to its current holder")
	}
	if from.JourneyID == nil || to.JourneyID == nil || *from.JourneyID != *to.JourneyID {
		return errf(http.StatusConflict, "invalid_handoff_route",
			"both assignments must belong to the same journey")
	}
	// The two legs must be adjacent in the journey.
	if to.Sequence <= from.Sequence {
		return errf(http.StatusConflict, "nonadjacent_handoff",
			"the receiving leg does not follow the sending leg")
	}
	var between int
	if err := tx.QueryRow(r.Context(),
		`SELECT count(*) FROM assignments WHERE journey_id = $1 AND sequence > $2 AND sequence < $3
             AND status NOT IN ('cancelled', 'superseded')`,
		*from.JourneyID, from.Sequence, to.Sequence).Scan(&between); err != nil {
		return errInternal
	}
	if between > 0 {
		return errf(http.StatusConflict, "nonadjacent_handoff",
			"another leg lies between the sending and receiving legs")
	}
	if from.Kind == "transport" && !from.PickedUp {
		return errf(http.StatusConflict, "transport_leg_incomplete",
			"the sending transport leg has not picked up the sample")
	}
	if assignmentTerminal(to.Status) {
		return errf(http.StatusConflict, "invalid_assignment_state",
			"the receiving assignment is no longer active")
	}
	receiver, err := s.userByID(r.Context(), tx, receiverID)
	if err != nil {
		return err
	}
	if !receiver.Active {
		return errf(http.StatusConflict, "receiver_unavailable", "the receiver is not active")
	}
	if requiredLocation := assignmentLocation(to); requiredLocation != nil {
		if receiver.AssignedLocationID == nil || *receiver.AssignedLocationID != *requiredLocation {
			return errf(http.StatusConflict, "node_assignment_mismatch",
				"the receiver is not assigned to the receiving node or laboratory")
		}
	}

	handoffID := uuid.New()
	if _, err := tx.Exec(r.Context(),
		`INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id,
             receiver_id, status, initiated_at) VALUES ($1, $2, $3, $4, $5, $6, 'pending', $7)`,
		handoffID, sampleID, fromID, toID, rc.User.ID, receiverID, initiatedAt); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "initiate_handoff", EntityType: "handoff", EntityID: handoffID.String(),
		Success: true, OccurredAt: initiatedAt,
		Details: map[string]any{"sampleId": sampleID.String(), "senderId": rc.User.ID.String(),
			"receiverId": receiverID.String(), "fromAssignmentId": fromID.String(),
			"toAssignmentId": toID.String(), "status": "pending"}})

	out := map[string]any{
		"handoffId":       handoffID.String(),
		"senderId":        rc.User.ID.String(),
		"receiverId":      receiverID.String(),
		"currentHolderId": rc.User.ID.String(),
		"status":          "pending",
	}
	if err := s.saveIdempotent(r.Context(), tx, "initiate-handoff", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "handoff.initiated", EntityType: "handoff",
		EntityID: handoffID.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{rc.User.ID, receiverID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleConfirmHandoff records one side's confirmation. The receiver becomes the current holder
// only once both sides have confirmed.
func (s *Server) handleConfirmHandoff(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	id, ok := parseUUID(body.HandoffID)
	if !ok {
		return errNotFound
	}
	if body.ConfirmationSide != "sender" && body.ConfirmationSide != "receiver" {
		return errf(http.StatusBadRequest, "invalid_confirmation_side",
			"confirmationSide must be sender or receiver")
	}
	confirmedAt, err := parseTimeCode(body.ConfirmedAt, "invalid_time")
	if err != nil {
		return err
	}
	stored, err := s.lookupIdempotent(r.Context(), "confirm-handoff", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	var locked uuid.UUID
	if err := tx.QueryRow(r.Context(),
		`SELECT id FROM handoffs WHERE id = $1 FOR UPDATE`, id).Scan(&locked); err != nil {
		return errNotFound
	}
	h, err := s.handoffByID(r.Context(), tx, id)
	if err != nil {
		return err
	}
	// Each side may only confirm for itself.
	switch body.ConfirmationSide {
	case "sender":
		if h.SenderID != rc.User.ID {
			return errf(http.StatusForbidden, "forbidden",
				"only the sender may confirm the sender side")
		}
	case "receiver":
		if h.ReceiverID != rc.User.ID {
			return errf(http.StatusForbidden, "forbidden",
				"only the receiver may confirm the receiver side")
		}
	}

	if h.Status == "confirmed" {
		// A delayed or repeated confirmation must not transfer custody twice.
		sm, err := s.sampleByID(r.Context(), tx, h.SampleID)
		if err != nil {
			return errInternal
		}
		out := map[string]any{"handoffId": id.String(), "status": "confirmed",
			"senderConfirmed": true, "receiverConfirmed": true,
			"currentHolderId": uuidPtrString(sm.CurrentHolderID)}
		if err := s.saveIdempotent(r.Context(), tx, "confirm-handoff", body.IdempotencyKey,
			rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
			return errInternal
		}
		if err := tx.Commit(r.Context()); err != nil {
			return errInternal
		}
		writeData(w, http.StatusCreated, out)
		return nil
	}
	if h.Status != "pending" {
		return errf(http.StatusConflict, "handoff_inactive",
			"handoff is no longer pending (status %s)", h.Status)
	}
	if confirmedAt.Before(h.InitiatedAt) {
		return errf(http.StatusConflict, "invalid_confirmation_time",
			"confirmedAt precedes the handoff initiation")
	}

	senderConfirmed := h.SenderConfirmed || body.ConfirmationSide == "sender"
	receiverConfirmed := h.ReceiverConfirmed || body.ConfirmationSide == "receiver"
	complete := senderConfirmed && receiverConfirmed
	status := "pending"
	if complete {
		status = "confirmed"
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE handoffs SET sender_confirmed = $2, receiver_confirmed = $3, status = $4,
             completed_at = CASE WHEN $4 = 'confirmed' THEN $5 ELSE completed_at END
         WHERE id = $1`, id, senderConfirmed, receiverConfirmed, status, confirmedAt); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "confirm_handoff", EntityType: "handoff", EntityID: id.String(), Success: true,
		OccurredAt: confirmedAt,
		Details: map[string]any{"confirmationSide": body.ConfirmationSide, "status": status,
			"sampleId": h.SampleID.String(), "senderConfirmed": senderConfirmed,
			"receiverConfirmed": receiverConfirmed}})

	holder := h.SenderID
	if complete {
		holder = h.ReceiverID
		if err := s.transferCustody(r.Context(), tx, h.SampleID, holder, rc, "custody_transferred",
			confirmedAt, map[string]any{"handoffId": id.String(), "senderId": h.SenderID.String(),
				"receiverId": h.ReceiverID.String()}); err != nil {
			return errInternal
		}
		// The sending leg is finished once custody has moved on.
		if h.FromAssignmentID != nil {
			if _, err := tx.Exec(r.Context(),
				`UPDATE assignments SET status = 'completed', completed_at = $2, updated_at = $2
                 WHERE id = $1 AND status NOT IN ('completed', 'cancelled', 'superseded')`,
				*h.FromAssignmentID, confirmedAt); err != nil {
				return errInternal
			}
		}
		if h.ToAssignmentID != nil {
			if _, err := tx.Exec(r.Context(),
				`UPDATE assignments SET status = 'in_progress', picked_up = true, updated_at = $2
                 WHERE id = $1 AND status = 'accepted'`, *h.ToAssignmentID, confirmedAt); err != nil {
				return errInternal
			}
		}
	}

	out := map[string]any{
		"handoffId":         id.String(),
		"status":            status,
		"senderConfirmed":   senderConfirmed,
		"receiverConfirmed": receiverConfirmed,
		"currentHolderId":   holder.String(),
	}
	if err := s.saveIdempotent(r.Context(), tx, "confirm-handoff", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "handoff.confirmed", EntityType: "handoff",
		EntityID: id.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{h.SenderID, h.ReceiverID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleConfirmLaboratoryReceipt completes a sample's journey at the laboratory.
func (s *Server) handleConfirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if err := rc.requireRole(RoleLaboratoryTeam); err != nil {
		return err
	}
	sampleID, okSample := parseUUID(body.SampleID)
	labID, okLab := parseUUID(body.LaboratoryID)
	if !okSample || !okLab {
		return errNotFound
	}
	receivedAt, err := parseTimeCode(body.ReceivedAt, "invalid_time")
	if err != nil {
		return err
	}
	// A laboratory operator may only receive at the laboratory they are assigned to.
	if rc.User.AssignedLocationID == nil || *rc.User.AssignedLocationID != labID {
		return errf(http.StatusForbidden, "wrong_laboratory_operator",
			"operator is not assigned to laboratory %s", labID)
	}
	stored, err := s.lookupIdempotent(r.Context(), "confirm-laboratory-receipt", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	var locked uuid.UUID
	if err := tx.QueryRow(r.Context(),
		`SELECT id FROM samples WHERE id = $1 FOR UPDATE`, sampleID).Scan(&locked); err != nil {
		return errNotFound
	}
	sm, err := s.sampleByID(r.Context(), tx, sampleID)
	if err != nil {
		return err
	}
	if sm.Status == statusReceived {
		out := map[string]any{"sampleId": sampleID.String(), "laboratoryId": labID.String(),
			"status": statusReceived, "receivedAt": timePtrString(sm.ReceivedAt)}
		if err := s.saveIdempotent(r.Context(), tx, "confirm-laboratory-receipt",
			body.IdempotencyKey, rc.User.ID, hash, http.StatusCreated,
			map[string]any{"data": out}); err != nil {
			return errInternal
		}
		if err := tx.Commit(r.Context()); err != nil {
			return errInternal
		}
		writeData(w, http.StatusCreated, out)
		return nil
	}
	if !sm.Sealed {
		return errf(http.StatusConflict, "receipt_not_ready", "the sample has not been sealed")
	}
	if sampleTerminal(sm.Status) {
		return errf(http.StatusConflict, "receipt_not_ready",
			"sample is in terminal state %s", sm.Status)
	}
	if pending, err := s.pendingHandoff(r.Context(), tx, sampleID); err != nil {
		return errInternal
	} else if pending != nil {
		return errf(http.StatusConflict, "pending_handoff_exists",
			"a handoff is still awaiting confirmation")
	}
	// Custody must have reached this operator through a confirmed handoff.
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != rc.User.ID {
		return errf(http.StatusConflict, "custody_conflict",
			"the sample is not in this operator's custody")
	}
	lab, err := s.locationByID(r.Context(), tx, labID)
	if err != nil {
		return err
	}
	if !lab.Active || !lab.Functions.Laboratory {
		return errf(http.StatusConflict, "laboratory_unavailable",
			"laboratory %s is not currently available", lab.Name)
	}
	accepts, err := s.laboratoryAccepts(r.Context(), tx, labID, sm.SampleTypeID)
	if err != nil {
		return errInternal
	}
	if !accepts {
		return errf(http.StatusConflict, "laboratory_unavailable",
			"laboratory %s does not accept this sample type", lab.Name)
	}
	req, err := s.requestByID(r.Context(), tx, sm.RequestID)
	if err != nil {
		return errInternal
	}
	if receivedAt.After(req.DeliveryDeadline) {
		if err := s.markSampleException(r.Context(), tx, sampleID, exceptionDeadlineMissed,
			"the sample arrived after its delivery deadline", receivedAt, &labID); err != nil {
			return errInternal
		}
		if err := tx.Commit(r.Context()); err != nil {
			return errInternal
		}
		return errf(http.StatusConflict, "delivery_deadline_exceeded",
			"the delivery deadline %s has passed", rfc3339(req.DeliveryDeadline))
	}

	if _, err := tx.Exec(r.Context(),
		`UPDATE samples SET status = $2, received_laboratory_id = $3, received_at = $4,
             latest_latitude = $5, latest_longitude = $6, location_recorded_at = $4, updated_at = $4
         WHERE id = $1`,
		sampleID, statusReceived, labID, receivedAt, lab.Coordinate.Latitude,
		lab.Coordinate.Longitude); err != nil {
		return errInternal
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE assignments SET status = 'completed', completed_at = $2, updated_at = $2
         WHERE sample_id = $1 AND status NOT IN ('completed', 'cancelled', 'superseded')`,
		sampleID, receivedAt); err != nil {
		return errInternal
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE journey_stops SET completed_at = $2
         WHERE journey_id = (SELECT active_journey_id FROM samples WHERE id = $1)
           AND completed_at IS NULL`, sampleID, receivedAt); err != nil {
		return errInternal
	}
	if sm.ActiveJourneyID != nil {
		if _, err := tx.Exec(r.Context(),
			`UPDATE journeys SET status = 'completed', updated_at = $2 WHERE id = $1`,
			*sm.ActiveJourneyID, receivedAt); err != nil {
			return errInternal
		}
		if err := s.releaseJourneyCapacity(r.Context(), tx, *sm.ActiveJourneyID); err != nil {
			return errInternal
		}
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "confirm_laboratory_receipt", EntityType: "sample", EntityID: sampleID.String(),
		Success: true, OccurredAt: receivedAt,
		Details: map[string]any{"status": statusReceived, "laboratoryId": labID.String(),
			"receivedAt": rfc3339(receivedAt)}})

	out := map[string]any{
		"sampleId":     sampleID.String(),
		"laboratoryId": labID.String(),
		"status":       statusReceived,
		"receivedAt":   rfc3339(receivedAt),
	}
	if err := s.saveIdempotent(r.Context(), tx, "confirm-laboratory-receipt", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "sample.received", EntityType: "sample",
		EntityID: sampleID.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{sm.RequesterID, rc.User.ID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleRecordLaboratoryException records that a sample could not be accepted normally.
func (s *Server) handleRecordLaboratoryException(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		Reason         string `json:"reason"`
		ObservedAt     string `json:"observedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if err := rc.requireRole(RoleLaboratoryTeam); err != nil {
		return err
	}
	sampleID, okSample := parseUUID(body.SampleID)
	labID, okLab := parseUUID(body.LaboratoryID)
	if !okSample || !okLab {
		return errNotFound
	}
	if body.Reason == "" {
		return errf(http.StatusBadRequest, "invalid_json", "reason is required")
	}
	observedAt, err := parseTimeCode(body.ObservedAt, "invalid_time")
	if err != nil {
		return err
	}
	if rc.User.AssignedLocationID == nil || *rc.User.AssignedLocationID != labID {
		return errf(http.StatusForbidden, "wrong_laboratory_operator",
			"operator is not assigned to laboratory %s", labID)
	}
	stored, err := s.lookupIdempotent(r.Context(), "record-laboratory-exception", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	sm, err := s.sampleByID(r.Context(), s.pool, sampleID)
	if err != nil {
		return err
	}
	if sm.Status == statusReceived {
		return errf(http.StatusConflict, "laboratory_not_ready",
			"the sample has already been received")
	}
	if sm.TargetLaboratoryID != nil && *sm.TargetLaboratoryID != labID {
		return errf(http.StatusConflict, "wrong_laboratory",
			"the sample is routed to a different laboratory")
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	exceptionID := uuid.New()
	if _, err := tx.Exec(r.Context(),
		`INSERT INTO sample_exceptions (id, sample_id, kind, reason, laboratory_id, observed_at)
         VALUES ($1, $2, $3, $4, $5, $6)`,
		exceptionID, sampleID, exceptionLaboratory, body.Reason, labID, observedAt); err != nil {
		return errInternal
	}
	exc := map[string]any{"kind": exceptionLaboratory, "reason": body.Reason,
		"laboratoryId": labID.String(), "observedAt": rfc3339(observedAt),
		"exceptionId": exceptionID.String()}
	if _, err := tx.Exec(r.Context(),
		`UPDATE samples SET status = $2, exception = $3, updated_at = $4 WHERE id = $1`,
		sampleID, statusException, mustJSON(exc), observedAt); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "record_laboratory_exception", EntityType: "sample", EntityID: sampleID.String(),
		Success: true, OccurredAt: observedAt, Details: exc})

	out := map[string]any{
		"exceptionId": exceptionID.String(),
		"sampleId":    sampleID.String(),
		"status":      statusException,
		"reason":      body.Reason,
	}
	if err := s.saveIdempotent(r.Context(), tx, "record-laboratory-exception", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "sample.exception", EntityType: "sample",
		EntityID: sampleID.String(), Payload: exc,
		audience: []string{RoleDispatcher, RoleAdministrator},
		userIDs:  []uuid.UUID{sm.RequesterID}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}
