// handleListRoleWork returns the current and past work for the selected role.
func (s *Server) handleListRoleWork(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		Role   *string `json:"role"`
		Status *string `json:"status"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	role := rc.Role
	if body.Role != nil && *body.Role != "" {
		if !allRoles[*body.Role] {
			return errf(http.StatusBadRequest, "invalid_role", "unknown role %q", *body.Role)
		}
		// Work views must use the role the session has selected.
		if *body.Role != rc.Role {
			return errForbidden
		}
		role = *body.Role
	}

	now := s.now()
	work, err := s.roleWork(r.Context(), rc, role, now)
	if err != nil {
		return errInternal
	}
	if body.Status != nil && *body.Status != "" {
		work = filterWorkByStatus(work, *body.Status)
	}
	s.audit(r.Context(), auditRecord{ActorID: rc.actorID(), Role: rc.Role, Action: "list_role_work",
		EntityType: "role", EntityID: role, Success: true,
		Details: map[string]any{"pending": len(work["pending"]), "inProgress": len(work["inProgress"]),
			"completed": len(work["completed"])}})
	writeData(w, http.StatusOK, work)
	return nil
}

type workBuckets map[string][]map[string]any

func filterWorkByStatus(work workBuckets, status string) workBuckets {
	out := workBuckets{"pending": {}, "inProgress": {}, "completed": {}}
	for bucket, items := range work {
		for _, item := range items {
			if itemStatus, ok := item["status"].(string); ok && itemStatus == status {
				out[bucket] = append(out[bucket], item)
			}
		}
	}
	return out
}

// roleWork assembles the work buckets visible to the given role.
func (s *Server) roleWork(ctx context.Context, rc *requestContext, role string, now time.Time) (workBuckets, error) {
	out := workBuckets{"pending": {}, "inProgress": {}, "completed": {}}
	switch role {
	case RoleRequester:
		samples, err := s.requesterSamples(ctx, rc.User.ID, now)
		if err != nil {
			return nil, err
		}
		for _, item := range samples {
			out[bucketForSampleStatus(item["status"].(string))] = append(
				out[bucketForSampleStatus(item["status"].(string))], item)
		}
	case RoleDispatcher, RoleAdministrator:
		journeys, err := s.dispatcherJourneys(ctx)
		if err != nil {
			return nil, err
		}
		for _, item := range journeys {
			out[bucketForJourneyStatus(item["status"].(string))] = append(
				out[bucketForJourneyStatus(item["status"].(string))], item)
		}
	case RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		items, err := s.workerAssignments(ctx, rc.User.ID, role, now)
		if err != nil {
			return nil, err
		}
		for _, item := range items {
			out[bucketForAssignmentStatus(item["status"].(string))] = append(
				out[bucketForAssignmentStatus(item["status"].(string))], item)
		}
	}
	return out, nil
}

func bucketForSampleStatus(status string) string {
	switch status {
	case statusRequested, statusScheduled, statusUnservicabl:
		return "pending"
	case statusReceived, statusCancelled, statusExpired:
		return "completed"
	}
	return "inProgress"
}

func bucketForJourneyStatus(status string) string {
	switch status {
	case "planned":
		return "pending"
	case "completed", "cancelled", "superseded", "expired":
		return "completed"
	}
	return "inProgress"
}

func bucketForAssignmentStatus(status string) string {
	switch status {
	case "pending", "offered":
		return "pending"
	case "completed", "cancelled", "superseded", "exception":
		return "completed"
	}
	return "inProgress"
}

// requesterSamples lists only the samples belonging to one requester.
func (s *Server) requesterSamples(ctx context.Context, requesterID uuid.UUID, now time.Time) ([]map[string]any, error) {
	rows, err := s.pool.Query(ctx, `SELECT `+prefixColumns(sampleColumns, "s")+`,
            r.requested_at, r.delivery_deadline, r.earliest_collection_at, r.latest_collection_at
         FROM samples s JOIN requests r ON r.id = s.request_id
         WHERE s.requester_id = $1 ORDER BY s.created_at DESC`, requesterID)
	if err != nil {
		return nil, err
	}
	type row struct {
		sample                       *Sample
		requestedAt, deadline        time.Time
		earliest, latest             time.Time
	}
	var collected []row
	for rows.Next() {
		var sm Sample
		var exc []byte
		var rec row
		if err := rows.Scan(&sm.ID, &sm.RequestID, &sm.RequesterID, &sm.SampleTypeID, &sm.Status,
			&sm.Sealed, &sm.Presealed, &sm.CurrentHolderID, &sm.ActiveJourneyID,
			&sm.TargetLaboratoryID, &sm.ReceivedLaboratoryID, &sm.SealedAt, &sm.ReceivedAt, &exc,
			&sm.LatestLatitude, &sm.LatestLongitude, &sm.LocationRecordedAt,
			&rec.requestedAt, &rec.deadline, &rec.earliest, &rec.latest); err != nil {
			rows.Close()
			return nil, err
		}
		if len(exc) > 0 {
			sm.Exception = map[string]any{}
			_ = jsonUnmarshal(exc, &sm.Exception)
		}
		rec.sample = &sm
		collected = append(collected, rec)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, err
	}

	out := []map[string]any{}
	for _, rec := range collected {
		sm := rec.sample
		assignments, err := s.assignmentsForSample(ctx, s.pool, sm.ID)
		if err != nil {
			return nil, err
		}
		history, err := s.sampleTimeline(ctx, s.pool, sm, assignments)
		if err != nil {
			return nil, err
		}
		item := map[string]any{
			"kind":                 "sample",
			"sampleId":             sm.ID.String(),
			"requestId":            sm.RequestID.String(),
			"status":               sm.Status,
			"requesterId":          sm.RequesterID.String(),
			"requestedAt":          rfc3339(rec.requestedAt),
			"deliveryDeadline":     rfc3339(rec.deadline),
			"earliestCollectionAt": rfc3339(rec.earliest),
			"latestCollectionAt":   rfc3339(rec.latest),
			"history":              history,
			"locationStale":        isStale(sm.LocationRecordedAt, now),
		}
		if sm.ActiveJourneyID != nil {
			item["journeyId"] = sm.ActiveJourneyID.String()
			item["activeJourneyId"] = sm.ActiveJourneyID.String()
		}
		if sm.TargetLaboratoryID != nil {
			item["laboratoryId"] = sm.TargetLaboratoryID.String()
		}
		if sm.CurrentHolderID != nil {
			item["currentHolderId"] = sm.CurrentHolderID.String()
		}
		if sm.LocationRecordedAt != nil {
			item["locationRecordedAt"] = rfc3339(*sm.LocationRecordedAt)
		}
		out = append(out, item)
	}
	return out, nil
}

func prefixColumns(columns, prefix string) string {
	parts := strings.Split(columns, ",")
	for i, p := range parts {
		parts[i] = prefix + "." + strings.TrimSpace(p)
	}
	return strings.Join(parts, ", ")
}

func (s *Server) dispatcherJourneys(ctx context.Context) ([]map[string]any, error) {
	rows, err := s.pool.Query(ctx, `SELECT `+journeyColumns+` FROM journeys ORDER BY created_at DESC`)
	if err != nil {
		return nil, err
	}
	var journeys []*Journey
	for rows.Next() {
		j, err := scanJourney(rows)
		if err != nil {
			rows.Close()
			return nil, err
		}
		journeys = append(journeys, j)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, err
	}

	out := []map[string]any{}
	for _, j := range journeys {
		sampleIDs, err := s.journeySampleIDs(ctx, s.pool, j.ID)
		if err != nil {
			return nil, err
		}
		var assignmentCount int
		if err := s.pool.QueryRow(ctx,
			`SELECT count(*) FROM assignments WHERE journey_id = $1`, j.ID).Scan(&assignmentCount); err != nil {
			return nil, err
		}
		history, err := s.timelineFor(ctx, s.pool, "journey", j.ID.String())
		if err != nil {
			return nil, err
		}
		estimated := ""
		if j.EstimatedDeliveryAt != nil {
			estimated = rfc3339(*j.EstimatedDeliveryAt)
		}
		out = append(out, map[string]any{
			"kind":                "journey",
			"journeyId":           j.ID.String(),
			"status":              j.Status,
			"routeMode":           j.RouteMode,
			"planVersion":         j.PlanVersion,
			"sampleIds":           uuidStrings(sampleIDs),
			"estimatedDeliveryAt": estimated,
			"assignmentCount":     assignmentCount,
			"history":             history,
		})
	}
	return out, nil
}

// workerAssignments lists the work offered to or held by a worker in one role.
func (s *Server) workerAssignments(ctx context.Context, workerID uuid.UUID, role string, now time.Time) ([]map[string]any, error) {
	kind := map[string]string{
		RoleCollectionPro:   "collection",
		RoleDeliveryPartner: "transport",
		RoleNodeHandler:     "node",
		RoleLaboratoryTeam:  "laboratory",
	}[role]
	rows, err := s.pool.Query(ctx, `SELECT `+assignmentColumns+` FROM assignments
        WHERE kind = $1 AND (worker_id = $2 OR offered_to = $2)
        ORDER BY created_at DESC`, kind, workerID)
	if err != nil {
		return nil, err
	}
	var assignments []*Assignment
	for rows.Next() {
		a, err := scanAssignment(rows)
		if err != nil {
			rows.Close()
			return nil, err
		}
		assignments = append(assignments, a)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, err
	}

	out := []map[string]any{}
	for _, a := range assignments {
		history, err := s.timelineFor(ctx, s.pool, "assignment", a.ID.String())
		if err != nil {
			return nil, err
		}
		item := map[string]any{
			"kind":         a.Kind,
			"assignmentId": a.ID.String(),
			"sampleId":     uuidPtrString(a.SampleID),
			"status":       a.Status,
			"sequence":     a.Sequence,
			"history":      history,
		}
		if a.JourneyID != nil {
			item["journeyId"] = a.JourneyID.String()
		}
		// A relay courier sees only the details needed for their own leg.
		if a.FromLocationID != nil {
			item["fromLocationId"] = a.FromLocationID.String()
		}
		if a.ToLocationID != nil {
			item["toLocationId"] = a.ToLocationID.String()
		}
		if a.OfferExpiresAt != nil {
			item["offerExpiresAt"] = rfc3339(*a.OfferExpiresAt)
		}
		if a.NodeID != nil {
			item["nodeId"] = a.NodeID.String()
			item["incomingFromLocationId"] = uuidPtrString(a.FromLocationID)
			outgoing, err := s.nextLegDestination(ctx, a)
			if err == nil && outgoing != nil {
				item["outgoingToLocationId"] = outgoing.String()
			}
		}
		if a.LaboratoryID != nil {
			item["laboratoryId"] = a.LaboratoryID.String()
			if a.SampleID != nil {
				if sm, err := s.sampleByID(ctx, s.pool, *a.SampleID); err == nil {
					item["expectedSampleTypeId"] = sm.SampleTypeID.String()
				}
			}
		}
		// Node handlers and laboratory operators need the capacity at their own destination.
		if destination := destinationForCapacity(a); destination != nil {
			if loc, err := s.locationByID(ctx, s.pool, *destination); err == nil {
				item["destinationCapacity"] = locationCapacityAPI(loc)
			}
		}
		out = append(out, item)
	}
	return out, nil
}

func destinationForCapacity(a *Assignment) *uuid.UUID {
	switch a.Kind {
	case "node":
		return a.NodeID
	case "laboratory":
		return a.LaboratoryID
	case "transport", "collection":
		return a.ToLocationID
	}
	return nil
}

func locationCapacityAPI(l *Location) map[string]any {
	return map[string]any{
		"capacityUnits":        l.CapacityUnits,
		"reservedUnits":        l.ReservedUnits,
		"availableUnits":       maxInt(l.CapacityUnits-l.ReservedUnits, 0),
		"cooledCapacityUnits":  l.CooledCapacityUnits,
		"cooledReservedUnits":  l.CooledReservedUnits,
		"cooledAvailableUnits": maxInt(l.CooledCapacityUnits-l.CooledReservedUnits, 0),
	}
}

func connectionCapacityAPI(c *Connection) map[string]any {
	return map[string]any{
		"capacityUnits":        c.CapacityUnits,
		"reservedUnits":        c.ReservedUnits,
		"availableUnits":       maxInt(c.CapacityUnits-c.ReservedUnits, 0),
		"cooledCapacityUnits":  c.CooledCapacityUnits,
		"cooledReservedUnits":  c.CooledReservedUnits,
		"cooledAvailableUnits": maxInt(c.CooledCapacityUnits-c.CooledReservedUnits, 0),
	}
}

func maxInt(a, b int) int {
	if a > b {
		return a
	}
	return b
}

func (s *Server) nextLegDestination(ctx context.Context, a *Assignment) (*uuid.UUID, error) {
	if a.JourneyID == nil {
		return nil, nil
	}
	var dest *uuid.UUID
	err := s.pool.QueryRow(ctx,
		`SELECT to_location_id FROM assignments
         WHERE journey_id = $1 AND sequence > $2 AND kind = 'transport'
         ORDER BY sequence ASC LIMIT 1`, *a.JourneyID, a.Sequence).Scan(&dest)
	if err != nil {
		return nil, err
	}
	return dest, nil
}

func (s *Server) handleReadSampleState(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	id, ok := parseUUID(pathTail(r))
	if !ok {
		return errNotFound
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	sm, err := s.sampleByID(r.Context(), s.pool, id)
	if err != nil {
		return err
	}
	if err := s.authoriseSampleRead(r.Context(), rc, sm); err != nil {
		return err
	}
	state, err := s.sampleStateAPI(r.Context(), s.pool, sm, s.now())
	if err != nil {
		return errInternal
	}
	writeData(w, http.StatusOK, state)
	return nil
}

func (s *Server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		SampleID string `json:"sampleId"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	id, ok := parseUUID(body.SampleID)
	if !ok {
		return errNotFound
	}
	sm, err := s.sampleByID(r.Context(), s.pool, id)
	if err != nil {
		return err
	}
	if err := s.authoriseSampleRead(r.Context(), rc, sm); err != nil {
		return err
	}
	lifecycle, err := s.sampleLifecycleAPI(r.Context(), s.pool, sm, s.now())
	if err != nil {
		return errInternal
	}
	writeData(w, http.StatusOK, lifecycle)
	return nil
}

// authoriseSampleRead enforces that data is visible only as the selected role permits.
func (s *Server) authoriseSampleRead(ctx context.Context, rc *requestContext, sm *Sample) error {
	if rc.Role == "" {
		return errRoleNotSet
	}
	switch rc.Role {
	case RoleAdministrator, RoleDispatcher:
		return nil
	case RoleRequester:
		// A requester sees only requests that belong to them.
		if sm.RequesterID != rc.User.ID {
			return errForbidden
		}
		return nil
	case RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam:
		if sm.CurrentHolderID != nil && *sm.CurrentHolderID == rc.User.ID {
			return nil
		}
		var involved int
		if err := s.pool.QueryRow(ctx,
			`SELECT count(*) FROM assignments WHERE sample_id = $1 AND (worker_id = $2 OR offered_to = $2)`,
			sm.ID, rc.User.ID).Scan(&involved); err != nil {
			return errInternal
		}
		if involved == 0 {
			return errForbidden
		}
		return nil
	}
	return errForbidden
}

// handleReadJourneyPlan returns the journey view appropriate to the selected role.
func (s *Server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		JourneyID string `json:"journeyId"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	id, ok := parseUUID(body.JourneyID)
	if !ok {
		return errNotFound
	}
	j, err := s.journeyByID(r.Context(), s.pool, id)
	if err != nil {
		return err
	}
	sampleIDs, err := s.journeySampleIDs(r.Context(), s.pool, id)
	if err != nil {
		return errInternal
	}

	switch rc.Role {
	case RoleAdministrator, RoleDispatcher:
		// A dispatcher sees the full journey, including collection and each transport leg.
		plan, err := s.journeyPlanAPI(r.Context(), s.pool, j)
		if err != nil {
			return errInternal
		}
		writeData(w, http.StatusOK, plan)
		return nil
	case RoleRequester:
		owns := false
		for _, sid := range sampleIDs {
			sm, err := s.sampleByID(r.Context(), s.pool, sid)
			if err == nil && sm.RequesterID == rc.User.ID {
				owns = true
				break
			}
		}
		if !owns {
			return errForbidden
		}
		plan, err := s.requesterJourneyAPI(r.Context(), j, sampleIDs)
		if err != nil {
			return errInternal
		}
		writeData(w, http.StatusOK, plan)
		return nil
	default:
		plan, scoped, err := s.workerJourneyAPI(r.Context(), j, rc)
		if err != nil {
			return errInternal
		}
		if !scoped {
			return errForbidden
		}
		writeData(w, http.StatusOK, plan)
		return nil
	}
}

func (s *Server) requesterJourneyAPI(ctx context.Context, j *Journey, sampleIDs []uuid.UUID) (map[string]any, error) {
	stops, err := s.stopsForJourney(ctx, s.pool, j.ID)
	if err != nil {
		return nil, err
	}
	orderedStops := make([]map[string]any, 0, len(stops))
	for _, st := range stops {
		orderedStops = append(orderedStops, st.API())
	}
	assignments, err := s.assignmentsForJourney(ctx, s.pool, j.ID)
	if err != nil {
		return nil, err
	}
	legs := []map[string]any{}
	for _, a := range assignments {
		if a.Kind != "transport" {
			continue
		}
		legs = append(legs, map[string]any{
			"assignmentId":   a.ID.String(),
			"sequence":       a.Sequence,
			"status":         a.Status,
			"fromLocationId": uuidPtrString(a.FromLocationID),
			"toLocationId":   uuidPtrString(a.ToLocationID),
		})
	}
	out := map[string]any{
		"journeyId":      j.ID.String(),
		"planVersion":    j.PlanVersion,
		"routeMode":      j.RouteMode,
		"status":         j.Status,
		"sampleIds":      uuidStrings(sampleIDs),
		"orderedStops":   orderedStops,
		"legs":           legs,
		"totalCostUnits": j.TotalCostUnits,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = rfc3339(*j.EstimatedDeliveryAt)
	}
	return out, nil
}

// workerJourneyAPI scopes the journey to the legs assigned to this worker.
func (s *Server) workerJourneyAPI(ctx context.Context, j *Journey, rc *requestContext) (map[string]any, bool, error) {
	assignments, err := s.assignmentsForJourney(ctx, s.pool, j.ID)
	if err != nil {
		return nil, false, err
	}
	mine := []*Assignment{}
	for _, a := range assignments {
		if a.WorkerID != nil && *a.WorkerID == rc.User.ID {
			mine = append(mine, a)
			continue
		}
		if a.OfferedTo != nil && *a.OfferedTo == rc.User.ID {
			mine = append(mine, a)
		}
	}
	if len(mine) == 0 {
		return nil, false, nil
	}

	assignmentIDs := []string{}
	legs := []map[string]any{}
	sampleIDs := []string{}
	seenSample := map[uuid.UUID]bool{}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	locationSet := map[uuid.UUID]bool{}
	for _, a := range mine {
		assignmentIDs = append(assignmentIDs, a.ID.String())
		if a.Kind == "transport" {
			legs = append(legs, a.legAPI())
		}
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.ID.String())
		case "node":
			nodeIDs = append(nodeIDs, a.ID.String())
		case "laboratory":
			labIDs = append(labIDs, a.ID.String())
		}
		if a.SampleID != nil && !seenSample[*a.SampleID] {
			seenSample[*a.SampleID] = true
			sampleIDs = append(sampleIDs, a.SampleID.String())
		}
		if a.FromLocationID != nil {
			locationSet[*a.FromLocationID] = true
		}
		if a.ToLocationID != nil {
			locationSet[*a.ToLocationID] = true
		}
	}

	allStops, err := s.stopsForJourney(ctx, s.pool, j.ID)
	if err != nil {
		return nil, false, err
	}
	orderedStops := []map[string]any{}
	for _, st := range allStops {
		if st.LocationID != nil && !locationSet[*st.LocationID] {
			continue
		}
		orderedStops = append(orderedStops, st.API())
	}

	out := map[string]any{
		"journeyId":     j.ID.String(),
		"planVersion":   j.PlanVersion,
		"routeMode":     j.RouteMode,
		"status":        j.Status,
		"scope":         "assigned_legs",
		"assignmentIds": assignmentIDs,
		"legs":          legs,
		"orderedStops":  orderedStops,
		"sampleIds":     sampleIDs,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = j.ParentJourneyID.String()
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = rfc3339(*j.EstimatedDeliveryAt)
	}
	if len(collectionIDs) > 0 {
		out["collectionAssignmentIds"] = collectionIDs
	}
	if len(nodeIDs) > 0 {
		out["nodeAssignmentIds"] = nodeIDs
	}
	if len(labIDs) > 0 {
		out["laboratoryAssignmentIds"] = labIDs
	}
	return out, true, nil
}
