// handleReadOperationsState returns the monitoring view for dispatchers and administrators.
func (s *Server) handleReadOperationsState(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		Filters *struct {
			SampleTypeID    *string `json:"sampleTypeId"`
			SampleTypeSnake *string `json:"sample_type_id"`
		} `json:"filters"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}
	var sampleTypeFilter *uuid.UUID
	if body.Filters != nil {
		raw := ""
		if body.Filters.SampleTypeID != nil {
			raw = *body.Filters.SampleTypeID
		} else if body.Filters.SampleTypeSnake != nil {
			raw = *body.Filters.SampleTypeSnake
		}
		if raw != "" {
			id, ok := parseUUID(raw)
			if !ok {
				return errf(http.StatusBadRequest, "invalid_json", "sampleTypeId is not a valid id")
			}
			sampleTypeFilter = &id
		}
	}
	state, err := s.operationsState(r.Context(), sampleTypeFilter)
	if err != nil {
		return errInternal
	}
	writeData(w, http.StatusOK, state)
	return nil
}

// operationsState assembles samples, workers, network, handoffs, delays and exceptions.
func (s *Server) operationsState(ctx context.Context, sampleTypeFilter *uuid.UUID) (map[string]any, error) {
	now := s.now()
	samples, err := s.operationsSamples(ctx, sampleTypeFilter, now)
	if err != nil {
		return nil, err
	}
	workers, spread, err := s.operationsWorkers(ctx, now)
	if err != nil {
		return nil, err
	}
	locations, err := s.operationsLocations(ctx)
	if err != nil {
		return nil, err
	}
	connections, err := s.operationsConnections(ctx)
	if err != nil {
		return nil, err
	}
	routes, err := s.operationsRoutes(ctx)
	if err != nil {
		return nil, err
	}
	handoffs, err := s.operationsHandoffs(ctx)
	if err != nil {
		return nil, err
	}
	exceptions, err := s.operationsExceptions(ctx)
	if err != nil {
		return nil, err
	}
	delays, err := s.operationsDelays(ctx, now)
	if err != nil {
		return nil, err
	}
	ineligible, err := s.ineligibleAssignmentCount(ctx)
	if err != nil {
		return nil, err
	}
	return map[string]any{
		"samples":                  samples,
		"workers":                  workers,
		"locations":                locations,
		"connections":              connections,
		"routes":                   routes,
		"handoffs":                 handoffs,
		"delays":                   delays,
		"exceptions":               exceptions,
		"assignmentCountSpread":    spread,
		"ineligibleAssignmentCount": ineligible,
	}, nil
}

func (s *Server) operationsSamples(ctx context.Context, sampleTypeFilter *uuid.UUID, now time.Time) ([]map[string]any, error) {
	query := `SELECT s.id, s.status, s.request_id, s.current_holder_id, s.active_journey_id,
            s.latest_latitude, s.latest_longitude, s.location_recorded_at,
            r.origin_latitude, r.origin_longitude, r.delivery_deadline
        FROM samples s JOIN requests r ON r.id = s.request_id`
	args := []any{}
	if sampleTypeFilter != nil {
		query += ` WHERE s.sample_type_id = $1`
		args = append(args, *sampleTypeFilter)
	}
	query += ` ORDER BY s.created_at DESC`
	rows, err := s.pool.Query(ctx, query, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var (
			id, requestID        uuid.UUID
			status               string
			holder, journey      *uuid.UUID
			lat, lon             *float64
			recordedAt           *time.Time
			originLat, originLon float64
			deadline             time.Time
		)
		if err := rows.Scan(&id, &status, &requestID, &holder, &journey, &lat, &lon, &recordedAt,
			&originLat, &originLon, &deadline); err != nil {
			return nil, err
		}
		item := map[string]any{
			"sampleId":         id.String(),
			"status":           status,
			"requestId":        requestID.String(),
			"origin":           Coordinate{Latitude: originLat, Longitude: originLon},
			"deliveryDeadline": rfc3339(deadline),
			"locationStale":    isStale(recordedAt, now),
		}
		if holder != nil {
			item["currentHolderId"] = holder.String()
		}
		if journey != nil {
			item["activeJourneyId"] = journey.String()
		}
		if lat != nil && lon != nil {
			item["latestLocation"] = Coordinate{Latitude: *lat, Longitude: *lon}
		}
		if recordedAt != nil {
			item["locationRecordedAt"] = rfc3339(*recordedAt)
		}
		out = append(out, item)
	}
	return out, rows.Err()
}

// operationsWorkers lists workers with their workload; the spread shows how fairly work is shared.
func (s *Server) operationsWorkers(ctx context.Context, now time.Time) ([]map[string]any, int, error) {
	rows, err := s.pool.Query(ctx,
		`SELECT u.id, u.full_name, u.roles, u.available, u.capacity_units,
                (SELECT count(*) FROM assignments a
                 WHERE a.worker_id = u.id
                   AND a.status NOT IN ('completed', 'cancelled', 'superseded')) AS active_count,
                (SELECT count(*) FROM assignments a WHERE a.worker_id = u.id) AS total_count
         FROM users u
         WHERE u.active AND u.roles && $1
         ORDER BY u.full_name NULLS LAST, u.username`, workerRoles)
	if err != nil {
		return nil, 0, err
	}
	type record struct {
		id          uuid.UUID
		fullName    *string
		roles       []string
		available   bool
		capacity    int
		activeCount int
		totalCount  int
	}
	var records []record
	for rows.Next() {
		var rec record
		if err := rows.Scan(&rec.id, &rec.fullName, &rec.roles, &rec.available, &rec.capacity,
			&rec.activeCount, &rec.totalCount); err != nil {
			rows.Close()
			return nil, 0, err
		}
		records = append(records, rec)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, 0, err
	}

	out := []map[string]any{}
	minCount, maxCount := -1, -1
	for _, rec := range records {
		status := "unavailable"
		if rec.available {
			status = "available"
		}
		item := map[string]any{
			"workerId":        rec.id.String(),
			"roles":           rec.roles,
			"available":       rec.available,
			"status":          status,
			"capacityUnits":   rec.capacity,
			"assignmentCount": rec.activeCount,
		}
		if rec.fullName != nil {
			item["fullName"] = *rec.fullName
		}
		coord, recordedAt, err := s.latestWorkerLocation(ctx, rec.id)
		if err != nil {
			return nil, 0, err
		}
		if coord != nil {
			item["latestLocation"] = *coord
			item["locationRecordedAt"] = rfc3339(*recordedAt)
		}
		item["locationStale"] = isStale(recordedAt, now)
		out = append(out, item)
		if minCount < 0 || rec.activeCount < minCount {
			minCount = rec.activeCount
		}
		if rec.activeCount > maxCount {
			maxCount = rec.activeCount
		}
	}
	spread := 0
	if minCount >= 0 && maxCount >= minCount {
		spread = maxCount - minCount
	}
	return out, spread, nil
}

var workerRoles = []string{RoleCollectionPro, RoleDeliveryPartner, RoleNodeHandler, RoleLaboratoryTeam}

func (s *Server) latestWorkerLocation(ctx context.Context, workerID uuid.UUID) (*Coordinate, *time.Time, error) {
	var (
		lat, lon   float64
		recordedAt time.Time
	)
	err := s.pool.QueryRow(ctx,
		`SELECT latitude, longitude, recorded_at FROM worker_locations
         WHERE worker_id = $1 ORDER BY recorded_at DESC, sequence DESC LIMIT 1`, workerID).
		Scan(&lat, &lon, &recordedAt)
	if err != nil {
		return nil, nil, nil
	}
	return &Coordinate{Latitude: lat, Longitude: lon}, &recordedAt, nil
}

func (s *Server) operationsLocations(ctx context.Context) ([]map[string]any, error) {
	locs, err := s.allLocations(ctx, s.pool)
	if err != nil {
		return nil, err
	}
	accepted, err := s.acceptedTypesByLab(ctx, s.pool)
	if err != nil {
		return nil, err
	}
	out := []map[string]any{}
	for _, l := range locs {
		item := map[string]any{
			"id":               l.ID.String(),
			"locationId":       l.ID.String(),
			"name":             l.Name,
			"coordinate":       l.Coordinate,
			"active":           l.Active,
			"coverageKm":       l.CoverageKm,
			"handlingMinutes":  l.HandlingMinutes,
			"functions":        l.Functions,
			"capacity":         locationCapacityAPI(l),
		}
		if types, ok := accepted[l.ID]; ok {
			item["acceptedSampleTypeIds"] = uuidStrings(types)
		} else {
			item["acceptedSampleTypeIds"] = []string{}
		}
		out = append(out, item)
	}
	return out, nil
}

func (s *Server) operationsConnections(ctx context.Context) ([]map[string]any, error) {
	conns, err := s.allConnections(ctx, s.pool)
	if err != nil {
		return nil, err
	}
	out := []map[string]any{}
	for _, c := range conns {
		out = append(out, map[string]any{
			"id":             c.ID.String(),
			"connectionId":   c.ID.String(),
			"fromLocationId": c.FromLocationID.String(),
			"toLocationId":   c.ToLocationID.String(),
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
			"capacity":       connectionCapacityAPI(c),
		})
	}
	return out, nil
}

// operationsRoutes summarises each unfinished journey as a route with its ordered stops.
func (s *Server) operationsRoutes(ctx context.Context) ([]map[string]any, error) {
	rows, err := s.pool.Query(ctx, `SELECT `+journeyColumns+` FROM journeys
        WHERE status NOT IN ('cancelled', 'superseded') ORDER BY created_at DESC`)
	if err != nil {
		return nil, err
	}
	var journeys []*Journey
	for rows.Next() {
		j, err := scanJourney(rows)
		if err != nil {
			rows.Close()
			return nil, err
		}
		journeys = append(journeys, j)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, err
	}

	out := []map[string]any{}
	for _, j := range journeys {
		stops, err := s.stopsForJourney(ctx, s.pool, j.ID)
		if err != nil {
			return nil, err
		}
		sampleIDs, err := s.journeySampleIDs(ctx, s.pool, j.ID)
		if err != nil {
			return nil, err
		}
		ordered := make([]map[string]any, 0, len(stops))
		for _, st := range stops {
			ordered = append(ordered, st.API())
		}
		item := map[string]any{
			"journeyId":    j.ID.String(),
			"routeMode":    j.RouteMode,
			"status":       j.Status,
			"planVersion":  j.PlanVersion,
			"sampleIds":    uuidStrings(sampleIDs),
			"orderedStops": ordered,
		}
		if j.EstimatedDeliveryAt != nil {
			item["estimatedDeliveryAt"] = rfc3339(*j.EstimatedDeliveryAt)
		}
		out = append(out, item)
	}
	return out, nil
}

func (s *Server) operationsHandoffs(ctx context.Context) ([]map[string]any, error) {
	rows, err := s.pool.Query(ctx, `SELECT `+handoffColumns+` FROM handoffs ORDER BY initiated_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		h, err := scanHandoff(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, h.API())
	}
	return out, rows.Err()
}

func (s *Server) operationsExceptions(ctx context.Context) ([]map[string]any, error) {
	rows, err := s.pool.Query(ctx,
		`SELECT e.id, e.sample_id, e.kind, e.reason, e.laboratory_id, e.observed_at, s.status
         FROM sample_exceptions e JOIN samples s ON s.id = e.sample_id
         ORDER BY e.observed_at DESC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var (
			id, sampleID  uuid.UUID
			kind, reason  string
			labID         *uuid.UUID
			observedAt    time.Time
			sampleStatus  string
		)
		if err := rows.Scan(&id, &sampleID, &kind, &reason, &labID, &observedAt, &sampleStatus); err != nil {
			return nil, err
		}
		item := map[string]any{
			"exceptionId":  id.String(),
			"sampleId":     sampleID.String(),
			"kind":         kind,
			"reason":       reason,
			"observedAt":   rfc3339(observedAt),
			"sampleStatus": sampleStatus,
		}
		if labID != nil {
			item["laboratoryId"] = labID.String()
		}
		out = append(out, item)
	}
	return out, rows.Err()
}

// operationsDelays lists unfinished samples whose deadline has passed or whose position is stale.
func (s *Server) operationsDelays(ctx context.Context, now time.Time) ([]map[string]any, error) {
	rows, err := s.pool.Query(ctx,
		`SELECT s.id, s.status, s.location_recorded_at, r.delivery_deadline, s.active_journey_id
         FROM samples s JOIN requests r ON r.id = s.request_id
         WHERE s.status NOT IN ('received', 'cancelled', 'unserviceable')
         ORDER BY r.delivery_deadline ASC`)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var (
			id         uuid.UUID
			status     string
			recordedAt *time.Time
			deadline   time.Time
			journeyID  *uuid.UUID
		)
		if err := rows.Scan(&id, &status, &recordedAt, &deadline, &journeyID); err != nil {
			return nil, err
		}
		overdue := now.After(deadline)
		stale := isStale(recordedAt, now)
		if !overdue && !stale {
			continue
		}
		item := map[string]any{
			"sampleId":         id.String(),
			"status":           status,
			"deliveryDeadline": rfc3339(deadline),
			"overdue":          overdue,
			"locationStale":    stale,
		}
		if journeyID != nil {
			item["journeyId"] = journeyID.String()
		}
		out = append(out, item)
	}
	return out, rows.Err()
}

// ineligibleAssignmentCount counts work that currently has no eligible worker to offer it to.
func (s *Server) ineligibleAssignmentCount(ctx context.Context) (int, error) {
	var count int
	err := s.pool.QueryRow(ctx,
		`SELECT count(*) FROM assignments a
         WHERE a.status = 'pending' AND NOT EXISTS (
             SELECT 1 FROM users u
             WHERE u.active AND u.available AND a.required_role = ANY (u.roles)
               AND (a.required_qualification = '' OR a.required_qualification = ANY (u.qualifications))
               AND (a.node_id IS NULL OR u.assigned_location_id = a.node_id)
               AND (a.laboratory_id IS NULL OR u.assigned_location_id = a.laboratory_id)
         )`).Scan(&count)
	return count, err
}

// handleSearchAuditTrail searches the complete audit history.
func (s *Server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		Query      *string `json:"query"`
		ActorID    *string `json:"actorId"`
		EntityType *string `json:"entityType"`
		EntityID   *string `json:"entityId"`
		Action     *string `json:"action"`
		Role       *string `json:"role"`
		Success    *bool   `json:"success"`
		FromTime   *string `json:"fromTime"`
		ToTime     *string `json:"toTime"`
		Limit      *int    `json:"limit"`
		Offset     *int    `json:"offset"`
		Order      *string `json:"order"`
	}
	if err := decodeBody(r, &body); err != nil {
		return err
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}

	limit := 50
	if body.Limit != nil {
		if *body.Limit < 1 || *body.Limit > 500 {
			return errf(http.StatusBadRequest, "invalid_limit", "limit must be between 1 and 500")
		}
		limit = *body.Limit
	}
	offset := 0
	if body.Offset != nil {
		if *body.Offset < 0 {
			return errf(http.StatusBadRequest, "invalid_offset", "offset must not be negative")
		}
		offset = *body.Offset
	}
	order := "newest_first"
	if body.Order != nil && *body.Order != "" {
		if *body.Order != "newest_first" && *body.Order != "oldest_first" {
			return errf(http.StatusBadRequest, "invalid_order",
				"order must be newest_first or oldest_first")
		}
		order = *body.Order
	}

	where := []string{"1 = 1"}
	args := []any{}
	add := func(clause string, value any) {
		args = append(args, value)
		where = append(where, strings.Replace(clause, "?", "$"+itoa(len(args)), 1))
	}
	if body.Query != nil && *body.Query != "" {
		add("search_text LIKE ?", "%"+strings.ToLower(*body.Query)+"%")
	}
	if body.ActorID != nil && *body.ActorID != "" {
		add("actor_id = ?", *body.ActorID)
	}
	if body.EntityType != nil && *body.EntityType != "" {
		add("entity_type = ?", *body.EntityType)
	}
	if body.EntityID != nil && *body.EntityID != "" {
		add("entity_id = ?", *body.EntityID)
	}
	if body.Action != nil && *body.Action != "" {
		add("action = ?", *body.Action)
	}
	if body.Role != nil && *body.Role != "" {
		add("role = ?", *body.Role)
	}
	if body.Success != nil {
		add("success = ?", *body.Success)
	}
	if body.FromTime != nil && *body.FromTime != "" {
		from, err := parseTimeCode(*body.FromTime, "invalid_time")
		if err != nil {
			return err
		}
		add("occurred_at >= ?", from)
	}
	if body.ToTime != nil && *body.ToTime != "" {
		to, err := parseTimeCode(*body.ToTime, "invalid_time")
		if err != nil {
			return err
		}
		add("occurred_at <= ?", to)
	}
	clause := strings.Join(where, " AND ")

	var total int
	if err := s.pool.QueryRow(r.Context(),
		`SELECT count(*) FROM audit_log WHERE `+clause, args...).Scan(&total); err != nil {
		return errInternal
	}
	direction := "DESC"
	if order == "oldest_first" {
		direction = "ASC"
	}
	args = append(args, limit, offset)
	rows, err := s.pool.Query(r.Context(),
		`SELECT event_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
         FROM audit_log WHERE `+clause+`
         ORDER BY occurred_at `+direction+`, event_id `+direction+`
         LIMIT $`+itoa(len(args)-1)+` OFFSET $`+itoa(len(args)), args...)
	if err != nil {
		return errInternal
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var (
			eventID     int64
			actorID     string
			role        string
			action      string
			entityType  string
			entityID    string
			success     bool
			occurredAt  time.Time
			detailsJSON []byte
		)
		if err := rows.Scan(&eventID, &actorID, &role, &action, &entityType, &entityID, &success,
			&occurredAt, &detailsJSON); err != nil {
			return errInternal
		}
		details := map[string]any{}
		_ = jsonUnmarshal(detailsJSON, &details)
		id := itoa64(eventID)
		occurred := rfc3339(occurredAt)
		entries = append(entries, map[string]any{
			"auditId": id, "audit_id": id,
			"actorId": actorID, "actor_id": actorID,
			"role": role, "actorRole": role,
			"action":     action,
			"entityType": entityType, "entity_type": entityType,
			"entityId": entityID, "entity_id": entityID,
			"success":  success,
			"occurredAt": occurred, "occurred_at": occurred,
			"details": details,
		})
	}
	if err := rows.Err(); err != nil {
		return errInternal
	}

	out := map[string]any{
		"entries":  entries,
		"total":    total,
		"returned": len(entries),
		"offset":   offset,
		"limit":    limit,
		"order":    order,
		"hasMore":  offset+len(entries) < total,
	}
	if offset+len(entries) < total {
		out["nextOffset"] = offset + len(entries)
	}
	writeData(w, http.StatusOK, out)
	return nil
}
