import (
	"context"
	"net/http"
	"time"

	"github.com/google/uuid"
)

// lockJourney takes a row lock and enforces the plan-version check so that an outdated update
// cannot overwrite a newer one.
func (s *Server) lockJourney(ctx context.Context, q querier, id uuid.UUID, expectedVersion int) (*Journey, error) {
	var locked uuid.UUID
	if err := q.QueryRow(ctx, `SELECT id FROM journeys WHERE id = $1 FOR UPDATE`, id).Scan(&locked); err != nil {
		return nil, errNotFound
	}
	j, err := s.journeyByID(ctx, q, id)
	if err != nil {
		return nil, err
	}
	if journeyInactive(j.Status) {
		return nil, errf(http.StatusConflict, "inactive_plan",
			"journey is no longer active (status %s)", j.Status)
	}
	if expectedVersion != j.PlanVersion {
		return nil, errf(http.StatusConflict, "stale_plan",
			"expectedPlanVersion %d does not match the current plan version %d",
			expectedVersion, j.PlanVersion)
	}
	return j, nil
}

func journeyInactive(status string) bool {
	switch status {
	case "cancelled", "completed", "superseded", "expired":
		return true
	}
	return false
}

// unfinishedAssignments returns the legs that may still be replanned. Completed work and
// confirmed custody are never rewritten.
func (s *Server) unfinishedAssignments(ctx context.Context, q querier, journeyID uuid.UUID) ([]*Assignment, error) {
	all, err := s.assignmentsForJourney(ctx, q, journeyID)
	if err != nil {
		return nil, err
	}
	out := []*Assignment{}
	for _, a := range all {
		if assignmentTerminal(a.Status) {
			continue
		}
		out = append(out, a)
	}
	return out, nil
}

// hasWorkInProgress reports whether any leg has already started moving the sample.
func (s *Server) hasWorkInProgress(ctx context.Context, q querier, journeyID uuid.UUID) (bool, error) {
	var count int
	err := q.QueryRow(ctx,
		`SELECT count(*) FROM assignments
         WHERE journey_id = $1 AND picked_up AND status NOT IN ('completed', 'cancelled', 'superseded')`,
		journeyID).Scan(&count)
	return count > 0, err
}

// bumpPlanVersion advances the journey's plan version after an accepted change.
func (s *Server) bumpPlanVersion(ctx context.Context, q querier, journeyID uuid.UUID, now time.Time) (int, error) {
	var version int
	err := q.QueryRow(ctx,
		`UPDATE journeys SET plan_version = plan_version + 1, updated_at = $2 WHERE id = $1
         RETURNING plan_version`, journeyID, now).Scan(&version)
	return version, err
}

// handleEditActivePlan applies a dispatcher change to an unfinished plan. Every affected leg and
// reservation is revalidated; if validation fails the change is rejected and the plan is kept.
func (s *Server) handleEditActivePlan(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		JourneyID           string         `json:"journeyId"`
		ExpectedPlanVersion int            `json:"expectedPlanVersion"`
		ChangeType          string         `json:"changeType"`
		Changes             map[string]any `json:"changes"`
		IdempotencyKey      string         `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}
	journeyID, ok := parseUUID(body.JourneyID)
	if !ok {
		return errNotFound
	}
	if body.ExpectedPlanVersion < 1 {
		return errf(http.StatusBadRequest, "invalid_plan_version",
			"expectedPlanVersion must be at least 1")
	}
	if !validChangeTypes[body.ChangeType] {
		return errf(http.StatusBadRequest, "invalid_change_type",
			"unknown changeType %q", body.ChangeType)
	}
	stored, err := s.lookupIdempotent(r.Context(), "edit-active-plan", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	now := s.now()
	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	j, err := s.lockJourney(r.Context(), tx, journeyID, body.ExpectedPlanVersion)
	if err != nil {
		return err
	}

	switch body.ChangeType {
	case "replace_worker", "reassign_worker":
		if err := s.applyWorkerReplacement(r.Context(), tx, j, body.Changes, rc, now); err != nil {
			return err
		}
	case "cancel_work":
		if err := s.applyCancelWork(r.Context(), tx, j, body.Changes, rc, now); err != nil {
			return err
		}
	case "reorder_stops":
		if err := s.applyStopReorder(r.Context(), tx, j, body.Changes, rc, now); err != nil {
			return err
		}
	case "add_stop", "remove_stop", "reroute", "replace_route":
		if err := s.applyRouteChange(r.Context(), tx, j, body.ChangeType, body.Changes, rc, now); err != nil {
			return err
		}
	case "merge_samples":
		return errf(http.StatusConflict, "invalid_change_type",
			"use merge-journeys to combine samples")
	case "split_samples", "split_batch":
		return errf(http.StatusConflict, "invalid_change_type",
			"use split-journey to separate samples")
	}

	version, err := s.bumpPlanVersion(r.Context(), tx, journeyID, now)
	if err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "edit_active_plan", EntityType: "journey", EntityID: journeyID.String(),
		Success: true, OccurredAt: now,
		Details: map[string]any{"changeType": body.ChangeType, "planVersion": version,
			"previousPlanVersion": body.ExpectedPlanVersion}})

	updated, err := s.journeyByID(r.Context(), tx, journeyID)
	if err != nil {
		return errInternal
	}
	if err := s.validateJourney(r.Context(), tx, updated, now); err != nil {
		return err
	}
	out, err := s.journeyPlanAPI(r.Context(), tx, updated)
	if err != nil {
		return errInternal
	}
	if err := s.saveIdempotent(r.Context(), tx, "edit-active-plan", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "journey.updated", EntityType: "journey",
		EntityID: journeyID.String(),
		Payload: map[string]any{"journeyId": journeyID.String(), "planVersion": version,
			"changeType": body.ChangeType},
		audience: []string{RoleDispatcher, RoleAdministrator}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

var validChangeTypes = map[string]bool{
	"add_stop": true, "remove_stop": true, "reorder_stops": true, "replace_worker": true,
	"reassign_worker": true, "merge_samples": true, "split_samples": true, "split_batch": true,
	"cancel_work": true, "reroute": true, "replace_route": true,
}

// applyWorkerReplacement moves one unfinished leg to a different eligible worker.
func (s *Server) applyWorkerReplacement(ctx context.Context, q querier, j *Journey,
	changes map[string]any, rc *requestContext, now time.Time) error {
	assignmentID, ok := parseUUID(stringField(changes, "assignmentId"))
	if !ok {
		return errf(http.StatusConflict, "invalid_assignment",
			"changes.assignmentId is required for a worker replacement")
	}
	a, err := s.assignmentByID(ctx, q, assignmentID)
	if err != nil {
		return err
	}
	if a.JourneyID == nil || *a.JourneyID != j.ID {
		return errf(http.StatusConflict, "invalid_assignment",
			"the assignment does not belong to this journey")
	}
	// Completed work must not be rewritten.
	if assignmentTerminal(a.Status) {
		return errf(http.StatusConflict, "completed_work_immutable",
			"a completed assignment cannot be reassigned")
	}
	if a.PickedUp {
		return errf(http.StatusConflict, "work_in_progress",
			"the sample has already been picked up on this leg")
	}

	raw := stringField(changes, "workerId")
	if raw == "" {
		// Release the leg and let fair assignment offer it to the next eligible worker.
		if _, err := q.Exec(ctx,
			`UPDATE assignments SET status = 'pending', worker_id = NULL, offered_to = NULL,
                 offer_expires_at = NULL, updated_at = $2 WHERE id = $1`, assignmentID, now); err != nil {
			return errInternal
		}
		refreshed, err := s.assignmentByID(ctx, q, assignmentID)
		if err != nil {
			return errInternal
		}
		if _, err := s.offerAssignment(ctx, q, refreshed, now); err != nil {
			return err
		}
		return nil
	}

	workerID, ok := parseUUID(raw)
	if !ok {
		return errf(http.StatusBadRequest, "invalid_worker", "changes.workerId is not a valid id")
	}
	worker, err := s.userByID(ctx, q, workerID)
	if err != nil {
		return errf(http.StatusBadRequest, "invalid_worker", "worker %s does not exist", workerID)
	}
	if err := s.checkWorkerEligible(ctx, q, a, worker, now); err != nil {
		return err
	}
	if _, err := q.Exec(ctx,
		`UPDATE assignments SET worker_id = $2, status = 'accepted', offered_to = NULL,
             offer_expires_at = NULL, accepted_at = $3, updated_at = $3 WHERE id = $1`,
		assignmentID, workerID, now); err != nil {
		return errInternal
	}
	s.auditTx(ctx, q, auditRecord{ActorID: rc.actorID(), Role: rc.Role, Action: "replace_worker",
		EntityType: "assignment", EntityID: assignmentID.String(), Success: true, OccurredAt: now,
		Details: map[string]any{"workerId": workerID.String(),
			"previousWorkerId": uuidPtrString(a.WorkerID)}})
	return nil
}

// checkWorkerEligible rechecks role, qualification, availability and node assignment.
func (s *Server) checkWorkerEligible(ctx context.Context, q querier, a *Assignment, worker *User, now time.Time) error {
	if !worker.Active {
		return errf(http.StatusConflict, "worker_unavailable", "worker is not active")
	}
	if !worker.Available {
		return errf(http.StatusConflict, "worker_unavailable", "worker is marked unavailable")
	}
	if !worker.HasRole(a.RequiredRole) {
		return errf(http.StatusConflict, "ineligible_worker",
			"worker does not hold the %s role", a.RequiredRole)
	}
	if a.RequiredQualification != "" && !worker.HasQualification(a.RequiredQualification, now) {
		return errf(http.StatusConflict, "ineligible_worker",
			"worker does not hold qualification %q", a.RequiredQualification)
	}
	// A node or laboratory assignment may only go to a worker assigned to that location.
	if required := assignmentLocation(a); required != nil {
		if worker.AssignedLocationID == nil || *worker.AssignedLocationID != *required {
			return errf(http.StatusConflict, "ineligible_worker",
				"worker is not assigned to the required node or laboratory")
		}
	}
	return nil
}

// applyCancelWork cancels one unfinished leg of a journey.
func (s *Server) applyCancelWork(ctx context.Context, q querier, j *Journey,
	changes map[string]any, rc *requestContext, now time.Time) error {
	assignmentID, ok := parseUUID(stringField(changes, "assignmentId"))
	if !ok {
		return errf(http.StatusConflict, "invalid_assignment",
			"changes.assignmentId is required to cancel work")
	}
	a, err := s.assignmentByID(ctx, q, assignmentID)
	if err != nil {
		return err
	}
	if a.JourneyID == nil || *a.JourneyID != j.ID {
		return errf(http.StatusConflict, "invalid_assignment",
			"the assignment does not belong to this journey")
	}
	if a.Status == "completed" {
		return errf(http.StatusConflict, "completed_work_immutable",
			"a completed assignment cannot be cancelled")
	}
	if a.PickedUp {
		return errf(http.StatusConflict, "work_in_progress",
			"the sample has already been picked up on this leg")
	}
	if _, err := q.Exec(ctx,
		`UPDATE assignments SET status = 'cancelled', updated_at = $2 WHERE id = $1`,
		assignmentID, now); err != nil {
		return errInternal
	}
	s.auditTx(ctx, q, auditRecord{ActorID: rc.actorID(), Role: rc.Role, Action: "cancel_work",
		EntityType: "assignment", EntityID: assignmentID.String(), Success: true, OccurredAt: now,
		Details: map[string]any{"journeyId": j.ID.String()}})
	return nil
}

// applyStopReorder rewrites the order of stops that have not been completed.
func (s *Server) applyStopReorder(ctx context.Context, q querier, j *Journey,
	changes map[string]any, rc *requestContext, now time.Time) error {
	rawOrder, ok := changes["stopIds"].([]any)
	if !ok || len(rawOrder) == 0 {
		return errf(http.StatusConflict, "invalid_stop_order",
			"changes.stopIds must list the new stop order")
	}
	stops, err := s.stopsForJourney(ctx, q, j.ID)
	if err != nil {
		return errInternal
	}
	byID := map[uuid.UUID]*JourneyStop{}
	for _, st := range stops {
		byID[st.ID] = st
	}
	seen := map[uuid.UUID]bool{}
	ordered := make([]*JourneyStop, 0, len(rawOrder))
	for _, raw := range rawOrder {
		text, ok := raw.(string)
		if !ok {
			return errf(http.StatusConflict, "invalid_stop", "stopIds must contain stop ids")
		}
		id, ok := parseUUID(text)
		if !ok {
			return errf(http.StatusConflict, "invalid_stop", "%q is not a valid stop id", text)
		}
		st, ok := byID[id]
		if !ok {
			return errf(http.StatusConflict, "invalid_stop",
				"stop %s does not belong to this journey", id)
		}
		if seen[id] {
			return errf(http.StatusConflict, "ambiguous_stop_order",
				"stop %s appears more than once", id)
		}
		seen[id] = true
		// Completed stops must keep their place in the history.
		if st.CompletedAt != nil {
			return errf(http.StatusConflict, "completed_work_immutable",
				"stop %s has already been completed", id)
		}
		ordered = append(ordered, st)
	}
	pendingCount := 0
	for _, st := range stops {
		if st.CompletedAt == nil {
			pendingCount++
		}
	}
	if len(ordered) != pendingCount {
		return errf(http.StatusConflict, "invalid_stop_order",
			"stopIds must list every unfinished stop exactly once")
	}

	// Unfinished stops keep the sequence numbers and estimated times they had, in the new order.
	sequences := []int{}
	estimates := []time.Time{}
	for _, st := range stops {
		if st.CompletedAt == nil {
			sequences = append(sequences, st.Sequence)
			estimates = append(estimates, st.EstimatedAt)
		}
	}
	for i, st := range ordered {
		if _, err := q.Exec(ctx,
			`UPDATE journey_stops SET sequence = $2, estimated_at = $3 WHERE id = $1`,
			st.ID, sequences[i], estimates[i]); err != nil {
			return errInternal
		}
	}
	s.auditTx(ctx, q, auditRecord{ActorID: rc.actorID(), Role: rc.Role, Action: "reorder_stops",
		EntityType: "journey", EntityID: j.ID.String(), Success: true, OccurredAt: now,
		Details: map[string]any{"stopCount": len(ordered)}})
	return nil
}

// applyRouteChange replans the unfinished remainder of the journey onto a new route.
func (s *Server) applyRouteChange(ctx context.Context, q querier, j *Journey, changeType string,
	changes map[string]any, rc *requestContext, now time.Time) error {
	sampleIDs, err := s.journeySampleIDs(ctx, q, j.ID)
	if err != nil {
		return errInternal
	}
	if len(sampleIDs) != 1 {
		return errf(http.StatusConflict, "invalid_route",
			"a route change is supported for a single-sample journey")
	}
	result, err := s.replanJourney(ctx, q, j, rc, now, "route_change")
	if err != nil {
		return err
	}
	switch result.Status {
	case "expired":
		return errf(http.StatusConflict, "no_valid_route",
			"no route can still meet the delivery deadline")
	case "exception":
		return errf(http.StatusConflict, "no_valid_route", "no valid route is available")
	}
	s.auditTx(ctx, q, auditRecord{ActorID: rc.actorID(), Role: rc.Role, Action: changeType,
		EntityType: "journey", EntityID: j.ID.String(), Success: true, OccurredAt: now,
		Details: map[string]any{"replacementJourneyId": result.ReplacementID}})
	return nil
}

func stringField(m map[string]any, key string) string {
	if m == nil {
		return ""
	}
	if v, ok := m[key].(string); ok {
		return v
	}
	return ""
}

// validateJourney rechecks eligibility, compatibility, capacity and deadlines for every
// affected leg and reservation.
func (s *Server) validateJourney(ctx context.Context, q querier, j *Journey, now time.Time) error {
	sampleIDs, err := s.journeySampleIDs(ctx, q, j.ID)
	if err != nil {
		return errInternal
	}
	assignments, err := s.assignmentsForJourney(ctx, q, j.ID)
	if err != nil {
		return errInternal
	}

	// Stops must be in the correct order.
	stops, err := s.stopsForJourney(ctx, q, j.ID)
	if err != nil {
		return errInternal
	}
	previous := -1
	for _, st := range stops {
		if st.Sequence <= previous {
			return errf(http.StatusConflict, "invalid_stop_order",
				"journey stops are not in increasing order")
		}
		previous = st.Sequence
	}

	// Transport legs must form an increasing chain.
	lastSeq := -1
	for _, a := range assignments {
		if a.Kind != "transport" || assignmentTerminal(a.Status) {
			continue
		}
		if a.Sequence <= lastSeq {
			return errf(http.StatusConflict, "invalid_assignment_sequence",
				"transport legs are not in increasing order")
		}
		lastSeq = a.Sequence
	}

	// Every assigned worker must still be eligible.
	for _, a := range assignments {
		if a.WorkerID == nil || assignmentTerminal(a.Status) {
			continue
		}
		worker, err := s.userByID(ctx, q, *a.WorkerID)
		if err != nil {
			return errf(http.StatusConflict, "ineligible_worker", "assigned worker no longer exists")
		}
		if err := s.checkWorkerEligible(ctx, q, a, worker, now); err != nil {
			return err
		}
	}

	// Samples travelling together must be allowed to share a container and temperature range.
	if err := s.validateBatchCompatibility(ctx, q, sampleIDs); err != nil {
		return err
	}

	// Capacity must never be overbooked.
	if err := s.validateReservations(ctx, q, j.ID); err != nil {
		return err
	}

	// Every sample must still be able to meet its deadline.
	for _, sid := range sampleIDs {
		sm, err := s.sampleByID(ctx, q, sid)
		if err != nil {
			return errInternal
		}
		if sampleTerminal(sm.Status) {
			continue
		}
		req, err := s.requestByID(ctx, q, sm.RequestID)
		if err != nil {
			return errInternal
		}
		if j.EstimatedDeliveryAt != nil && j.EstimatedDeliveryAt.After(req.DeliveryDeadline) {
			return errf(http.StatusConflict, "deadline_exceeded",
				"the plan no longer meets the delivery deadline for sample %s", sid)
		}
	}
	return nil
}

// validateBatchCompatibility enforces the sample-type handling rules for a shared journey.
func (s *Server) validateBatchCompatibility(ctx context.Context, q querier, sampleIDs []uuid.UUID) error {
	if len(sampleIDs) < 2 {
		return nil
	}
	types := make([]*SampleType, 0, len(sampleIDs))
	for _, sid := range sampleIDs {
		sm, err := s.sampleByID(ctx, q, sid)
		if err != nil {
			return errInternal
		}
		st, err := s.sampleTypeByID(ctx, q, sm.SampleTypeID)
		if err != nil {
			return errInternal
		}
		// A time-critical sample must not be combined into a consolidation batch.
		if !st.BatchingAllowed {
			return errf(http.StatusConflict, "pulse_no_batch",
				"sample type %s is time-critical and must not be batched", st.Name)
		}
		types = append(types, st)
	}
	for i, a := range types {
		for jdx, b := range types {
			if i >= jdx {
				continue
			}
			if containsUUID(a.IncompatibleSampleTypes, b.ID) ||
				containsUUID(b.IncompatibleSampleTypes, a.ID) {
				return errf(http.StatusConflict, "incompatible_batch",
					"%s and %s must not share a container", a.Name, b.Name)
			}
			if a.ContainerType != b.ContainerType {
				return errf(http.StatusConflict, "incompatible_batch",
					"%s and %s require different containers", a.Name, b.Name)
			}
			// The shared temperature range must not be empty.
			low, high := a.TemperatureMinC, a.TemperatureMaxC
			if b.TemperatureMinC > low {
				low = b.TemperatureMinC
			}
			if b.TemperatureMaxC < high {
				high = b.TemperatureMaxC
			}
			if low > high {
				return errf(http.StatusConflict, "incompatible_batch",
					"%s and %s have incompatible temperature ranges", a.Name, b.Name)
			}
			if a.RequiresCooledRoute != b.RequiresCooledRoute {
				return errf(http.StatusConflict, "incompatible_batch",
					"%s and %s differ in cooled transport requirements", a.Name, b.Name)
			}
		}
	}
	return nil
}

// validateReservations confirms no capacity pool has been overbooked.
func (s *Server) validateReservations(ctx context.Context, q querier, journeyID uuid.UUID) error {
	rows, err := q.Query(ctx,
		`SELECT DISTINCT resource_type, resource_id FROM capacity_reservations
         WHERE journey_id = $1 AND NOT released`, journeyID)
	if err != nil {
		return errInternal
	}
	type resource struct {
		kind string
		id   uuid.UUID
	}
	var resources []resource
	for rows.Next() {
		var res resource
		if err := rows.Scan(&res.kind, &res.id); err != nil {
			rows.Close()
			return errInternal
		}
		resources = append(resources, res)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return errInternal
	}

	for _, res := range resources {
		var (
			capacityUnits, reservedUnits             int
			cooledCapacityUnits, cooledReservedUnits int
		)
		table := "locations"
		if res.kind == "connection" {
			table = "connections"
		}
		if err := q.QueryRow(ctx,
			`SELECT capacity_units, reserved_units, cooled_capacity_units, cooled_reserved_units
             FROM `+table+` WHERE id = $1`, res.id).
			Scan(&capacityUnits, &reservedUnits, &cooledCapacityUnits, &cooledReservedUnits); err != nil {
			return errf(http.StatusConflict, "invalid_reservation",
				"reserved resource %s no longer exists", res.id)
		}
		if reservedUnits > capacityUnits {
			return errf(http.StatusConflict, "capacity_exceeded",
				"regular capacity for resource %s is overbooked", res.id)
		}
		if cooledReservedUnits > cooledCapacityUnits {
			return errf(http.StatusConflict, "cooled_capacity_exhausted",
				"cooled capacity for resource %s is overbooked", res.id)
		}
	}
	return nil
}
