// replanResult reports the outcome of replanning the unfinished part of a journey.
type replanResult struct {
	Status        string
	ReplacementID string
	Replacement   *Journey
}

// replanJourney builds one replacement plan for the unfinished remainder of a journey. It keeps
// the current holder, preserves completed work and allows only one active replacement plan.
func (s *Server) replanJourney(ctx context.Context, q querier, j *Journey, rc *requestContext,
	now time.Time, reason string) (*replanResult, error) {
	sampleIDs, err := s.journeySampleIDs(ctx, q, j.ID)
	if err != nil {
		return nil, errInternal
	}
	if len(sampleIDs) == 0 {
		return &replanResult{Status: "not_required"}, nil
	}
	// Only one active replacement plan may exist for a journey.
	if j.ReplacedByJourneyID != nil {
		replacement, err := s.journeyByID(ctx, q, *j.ReplacedByJourneyID)
		if err == nil && !journeyInactive(replacement.Status) {
			return &replanResult{Status: "replaced",
				ReplacementID: replacement.ID.String(), Replacement: replacement}, nil
		}
	}

	sm, err := s.sampleByID(ctx, q, sampleIDs[0])
	if err != nil {
		return nil, errInternal
	}
	if sampleTerminal(sm.Status) {
		return &replanResult{Status: "not_required"}, nil
	}
	req, err := s.requestByID(ctx, q, sm.RequestID)
	if err != nil {
		return nil, errInternal
	}
	st, err := s.sampleTypeByID(ctx, q, sm.SampleTypeID)
	if err != nil {
		return nil, errInternal
	}

	unfinished, err := s.unfinishedAssignments(ctx, q, j.ID)
	if err != nil {
		return nil, errInternal
	}
	if len(unfinished) == 0 {
		return &replanResult{Status: "not_required"}, nil
	}

	// Replanning restarts from where the sample actually is, so completed movement is preserved.
	startNode, err := s.currentSampleNode(ctx, q, j, sm)
	if err != nil {
		return nil, errInternal
	}
	collectionAt := now
	if !sm.Sealed && collectionAt.Before(req.EarliestCollectionAt) {
		collectionAt = req.EarliestCollectionAt
	}

	g, err := s.loadGraph(ctx, q)
	if err != nil {
		return nil, errInternal
	}
	planReq := planRequest{
		Origin: Coordinate{Latitude: req.OriginLatitude, Longitude: req.OriginLongitude},
		OriginType: req.OriginType, OriginNodeID: req.OriginNodeID, SampleType: st,
		CollectionAt: collectionAt, Deadline: req.DeliveryDeadline,
		Presealed: sm.Sealed, SkipEntryLegs: sm.Sealed,
	}
	if startNode != nil {
		planReq.FixedStartNode = startNode
	}
	p, err := s.buildPlan(ctx, g, planReq)
	if err != nil {
		return nil, err
	}
	if !p.Serviceable {
		// A sample that can no longer meet its deadline expires; other failures are exceptions.
		if p.Reason == reasonDeadlineUnreachable {
			if _, err := q.Exec(ctx,
				`UPDATE samples SET status = $2, updated_at = $3 WHERE id = $1`,
				sm.ID, statusExpired, now); err != nil {
				return nil, errInternal
			}
			if err := s.cancelUnfinishedWork(ctx, q, j, now, "expired"); err != nil {
				return nil, errInternal
			}
			if _, err := q.Exec(ctx,
				`UPDATE journeys SET status = 'expired', updated_at = $2 WHERE id = $1`,
				j.ID, now); err != nil {
				return nil, errInternal
			}
			s.auditTx(ctx, q, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
				Action: "sample_expired", EntityType: "sample", EntityID: sm.ID.String(),
				Success: false, OccurredAt: now,
				Details: map[string]any{"reason": "no route can meet the delivery deadline",
					"journeyId": j.ID.String(), "trigger": reason}})
			return &replanResult{Status: "expired"}, nil
		}
		if err := s.markSampleException(ctx, q, sm.ID, exceptionNoRoute,
			"no valid route is available after the disruption", now, nil); err != nil {
			return nil, errInternal
		}
		return &replanResult{Status: "exception"}, nil
	}

	// Release the reservations of the work being replaced before reserving the new plan.
	if err := s.releaseUnfinishedReservations(ctx, q, j.ID); err != nil {
		return nil, errInternal
	}
	if err := s.cancelUnfinishedWork(ctx, q, j, now, "superseded"); err != nil {
		return nil, errInternal
	}

	replacement, assignments, err := s.persistPlan(ctx, q, p, sampleIDs, &j.ID)
	if err != nil {
		return nil, errInternal
	}
	if _, err := q.Exec(ctx,
		`UPDATE journeys SET status = 'superseded', replaced_by_journey_id = $2, updated_at = $3
         WHERE id = $1`, j.ID, replacement.ID, now); err != nil {
		return nil, errInternal
	}
	for _, sid := range sampleIDs {
		if _, err := q.Exec(ctx,
			`UPDATE samples SET active_journey_id = $2, target_laboratory_id = $3, updated_at = $4
             WHERE id = $1`, sid, replacement.ID, p.LaboratoryID, now); err != nil {
			return nil, errInternal
		}
	}
	s.auditTx(ctx, q, auditRecord{ActorID: rc.actorID(), Role: rc.Role, Action: "journey_replanned",
		EntityType: "journey", EntityID: j.ID.String(), Success: true, OccurredAt: now,
		Details: map[string]any{"replacementJourneyId": replacement.ID.String(),
			"trigger": reason, "currentHolderId": uuidPtrString(sm.CurrentHolderID),
			"estimatedDeliveryAt": rfc3339(p.ArrivalAt)}})
	if err := s.offerJourneyWork(ctx, q, assignments, now); err != nil {
		return nil, err
	}
	s.publishEvent(ctx, q, RealtimeEvent{Type: "journey.replanned", EntityType: "journey",
		EntityID: j.ID.String(),
		Payload: map[string]any{"journeyId": j.ID.String(),
			"replacementJourneyId": replacement.ID.String(), "reason": reason},
		audience: []string{RoleDispatcher, RoleAdministrator}})
	return &replanResult{Status: "replaced", ReplacementID: replacement.ID.String(),
		Replacement: replacement}, nil
}

// currentSampleNode resolves the node the sample has actually reached, so replanning continues
// from there rather than from the origin.
func (s *Server) currentSampleNode(ctx context.Context, q querier, j *Journey, sm *Sample) (*uuid.UUID, error) {
	var locationID *uuid.UUID
	err := q.QueryRow(ctx,
		`SELECT location_id FROM journey_stops
         WHERE journey_id = $1 AND completed_at IS NOT NULL AND location_id IS NOT NULL
         ORDER BY sequence DESC LIMIT 1`, j.ID).Scan(&locationID)
	if err == nil && locationID != nil {
		return locationID, nil
	}
	// Fall back to the entry node of the current plan when nothing has completed yet.
	err = q.QueryRow(ctx,
		`SELECT location_id FROM journey_stops
         WHERE journey_id = $1 AND location_id IS NOT NULL ORDER BY sequence ASC LIMIT 1`,
		j.ID).Scan(&locationID)
	if err != nil {
		return nil, nil
	}
	return locationID, nil
}

// cancelUnfinishedWork ends the legs that are being replaced while leaving completed work intact.
func (s *Server) cancelUnfinishedWork(ctx context.Context, q querier, j *Journey, now time.Time, status string) error {
	_, err := q.Exec(ctx,
		`UPDATE assignments SET status = $2, offered_to = NULL, offer_expires_at = NULL, updated_at = $3
         WHERE journey_id = $1 AND status NOT IN ('completed', 'cancelled', 'superseded')`,
		j.ID, status, now)
	return err
}

// releaseUnfinishedReservations frees capacity that the replaced legs no longer need.
func (s *Server) releaseUnfinishedReservations(ctx context.Context, q querier, journeyID uuid.UUID) error {
	return s.releaseJourneyCapacity(ctx, q, journeyID)
}

// handleRerouteJourney replans the unfinished work of a journey on request.
func (s *Server) handleRerouteJourney(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		JourneyID           string  `json:"journeyId"`
		ExpectedPlanVersion int     `json:"expectedPlanVersion"`
		Reason              *string `json:"reason"`
		IdempotencyKey      string  `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}
	journeyID, ok := parseUUID(body.JourneyID)
	if !ok {
		return errNotFound
	}
	if body.ExpectedPlanVersion < 1 {
		return errf(http.StatusBadRequest, "invalid_plan_version",
			"expectedPlanVersion must be at least 1")
	}
	stored, err := s.lookupIdempotent(r.Context(), "reroute-journey", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	now := s.now()
	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	j, err := s.lockJourney(r.Context(), tx, journeyID, body.ExpectedPlanVersion)
	if err != nil {
		return err
	}
	reason := "dispatcher_reroute"
	if body.Reason != nil && *body.Reason != "" {
		reason = *body.Reason
	}
	result, err := s.replanJourney(r.Context(), tx, j, rc, now, reason)
	if err != nil {
		return err
	}
	out := map[string]any{
		"journeyId":    journeyID.String(),
		"replanStatus": result.Status,
	}
	if result.Replacement != nil {
		out["replacementPlanId"] = result.ReplacementID
		plan, err := s.journeyPlanAPI(r.Context(), tx, result.Replacement)
		if err != nil {
			return errInternal
		}
		out["replacementJourney"] = plan
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "reroute_journey", EntityType: "journey", EntityID: journeyID.String(),
		Success: result.Status != "exception", OccurredAt: now,
		Details: map[string]any{"replanStatus": result.Status, "reason": reason,
			"replacementPlanId": result.ReplacementID}})
	if err := s.saveIdempotent(r.Context(), tx, "reroute-journey", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleCancelJourney cancels a journey and releases its capacity.
func (s *Server) handleCancelJourney(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		JourneyID           string  `json:"journeyId"`
		ExpectedPlanVersion int     `json:"expectedPlanVersion"`
