	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	j, err := s.lockJourney(r.Context(), tx, journeyID, body.ExpectedPlanVersion)
	if err != nil {
		return err
	}
	sampleIDs, err := s.journeySampleIDs(r.Context(), tx, journeyID)
	if err != nil {
		return errInternal
	}
	if err := s.cancelUnfinishedWork(r.Context(), tx, j, now, "cancelled"); err != nil {
		return errInternal
	}
	if err := s.releaseJourneyCapacity(r.Context(), tx, journeyID); err != nil {
		return errInternal
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE journeys SET status = 'cancelled', plan_version = plan_version + 1, updated_at = $2
         WHERE id = $1`, journeyID, now); err != nil {
		return errInternal
	}
	for _, sid := range sampleIDs {
		sm, err := s.sampleByID(r.Context(), tx, sid)
		if err != nil {
			return errInternal
		}
		if sampleTerminal(sm.Status) {
			continue
		}
		if _, err := tx.Exec(r.Context(),
			`UPDATE samples SET status = $2, active_journey_id = NULL, updated_at = $3 WHERE id = $1`,
			sid, statusCancelled, now); err != nil {
			return errInternal
		}
	}
	reason := ""
	if body.Reason != nil {
		reason = *body.Reason
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "cancel_journey", EntityType: "journey", EntityID: journeyID.String(),
		Success: true, OccurredAt: now,
		Details: map[string]any{"reason": reason, "sampleIds": uuidStrings(sampleIDs),
			"status": "cancelled"}})

	out := map[string]any{
		"journeyId": journeyID.String(),
		"status":    "cancelled",
		"sampleIds": uuidStrings(sampleIDs),
	}
	if err := s.saveIdempotent(r.Context(), tx, "cancel-journey", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "journey.cancelled", EntityType: "journey",
		EntityID: journeyID.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// handleSplitJourney moves some samples of a batched journey onto their own journey.
func (s *Server) handleSplitJourney(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}
	journeyID, ok := parseUUID(body.JourneyID)
	if !ok {
		return errNotFound
	}
	if body.ExpectedPlanVersion < 1 {
		return errf(http.StatusBadRequest, "invalid_plan_version",
			"expectedPlanVersion must be at least 1")
	}
	if len(body.SampleIDs) == 0 {
		return errf(http.StatusConflict, "invalid_split", "sampleIds must not be empty")
	}
	wanted := make([]uuid.UUID, 0, len(body.SampleIDs))
	for _, raw := range body.SampleIDs {
		id, ok := parseUUID(raw)
		if !ok {
			return errf(http.StatusConflict, "invalid_split", "%q is not a valid sample id", raw)
		}
		if containsUUID(wanted, id) {
			return errf(http.StatusConflict, "invalid_split", "sample %s is listed twice", id)
		}
		wanted = append(wanted, id)
	}
	stored, err := s.lookupIdempotent(r.Context(), "split-journey", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	now := s.now()
	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	j, err := s.lockJourney(r.Context(), tx, journeyID, body.ExpectedPlanVersion)
	if err != nil {
		return err
	}
	current, err := s.journeySampleIDs(r.Context(), tx, journeyID)
	if err != nil {
		return errInternal
	}
	for _, id := range wanted {
		if !containsUUID(current, id) {
			return errf(http.StatusConflict, "invalid_split",
				"sample %s is not part of this journey", id)
		}
	}
	if len(wanted) >= len(current) {
		return errf(http.StatusConflict, "invalid_split",
			"a split must leave at least one sample on the original journey")
	}
	inProgress, err := s.hasWorkInProgress(r.Context(), tx, journeyID)
	if err != nil {
		return errInternal
	}
	if inProgress {
		return errf(http.StatusConflict, "split_in_progress",
			"the journey has work already in progress and cannot be split")
	}

	// Plan a fresh journey for the samples being split out.
	firstSample, err := s.sampleByID(r.Context(), tx, wanted[0])
	if err != nil {
		return errInternal
	}
	req, err := s.requestByID(r.Context(), tx, firstSample.RequestID)
	if err != nil {
		return errInternal
	}
	st, err := s.sampleTypeByID(r.Context(), tx, firstSample.SampleTypeID)
	if err != nil {
		return errInternal
	}
	g, err := s.loadGraph(r.Context(), tx)
	if err != nil {
		return errInternal
	}
	collectionAt := req.EarliestCollectionAt
	if collectionAt.Before(now) {
		collectionAt = now
	}
	p, err := s.buildPlan(r.Context(), g, planRequest{
		Origin:     Coordinate{Latitude: req.OriginLatitude, Longitude: req.OriginLongitude},
		OriginType: req.OriginType, OriginNodeID: req.OriginNodeID, SampleType: st,
		CollectionAt: collectionAt, Deadline: req.DeliveryDeadline,
		Presealed: firstSample.Sealed, SkipEntryLegs: firstSample.Sealed,
	})
	if err != nil {
		return err
	}
	if !p.Serviceable {
		return errf(http.StatusConflict, "no_valid_route",
			"no valid route is available for the split samples")
	}

	// The split samples leave the original journey, releasing their reservations there.
	for _, id := range wanted {
		if _, err := tx.Exec(r.Context(),
			`DELETE FROM journey_samples WHERE journey_id = $1 AND sample_id = $2`,
			journeyID, id); err != nil {
			return errInternal
		}
		if _, err := tx.Exec(r.Context(),
			`UPDATE capacity_reservations SET released = true
             WHERE journey_id = $1 AND sample_id = $2 AND NOT released`, journeyID, id); err != nil {
			return errInternal
		}
		if _, err := tx.Exec(r.Context(),
			`UPDATE assignments SET status = 'superseded', offered_to = NULL, offer_expires_at = NULL,
                 updated_at = $2
             WHERE journey_id = $1 AND sample_id = $3
               AND status NOT IN ('completed', 'cancelled', 'superseded')`,
			journeyID, now, id); err != nil {
			return errInternal
		}
	}
	if err := s.releaseUnreservedResources(r.Context(), tx, journeyID); err != nil {
		return errInternal
	}

	splitJourney, assignments, err := s.persistPlan(r.Context(), tx, p, wanted, &journeyID)
	if err != nil {
		return errInternal
	}
	for _, id := range wanted {
		if _, err := tx.Exec(r.Context(),
			`UPDATE samples SET active_journey_id = $2, target_laboratory_id = $3, updated_at = $4
             WHERE id = $1`, id, splitJourney.ID, p.LaboratoryID, now); err != nil {
			return errInternal
		}
	}
	remaining, err := s.journeySampleIDs(r.Context(), tx, journeyID)
	if err != nil {
		return errInternal
	}
	routeMode := "direct"
	if len(remaining) > 1 {
		routeMode = "batched"
	} else {
		var transportCount int
		if err := tx.QueryRow(r.Context(),
			`SELECT count(*) FROM assignments WHERE journey_id = $1 AND kind = 'transport'
               AND status NOT IN ('cancelled', 'superseded')`, journeyID).Scan(&transportCount); err != nil {
			return errInternal
		}
		if transportCount > 1 {
			routeMode = "multi_stop"
		}
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE journeys SET route_mode = $2, plan_version = plan_version + 1, updated_at = $3
         WHERE id = $1`, journeyID, routeMode, now); err != nil {
		return errInternal
	}
	if err := s.offerJourneyWork(r.Context(), tx, assignments, now); err != nil {
		return err
	}

	updated, err := s.journeyByID(r.Context(), tx, journeyID)
	if err != nil {
		return errInternal
	}
	if err := s.validateJourney(r.Context(), tx, updated, now); err != nil {
		return err
	}
	if err := s.validateJourney(r.Context(), tx, splitJourney, now); err != nil {
		return err
	}
	originalPlan, err := s.journeyPlanAPI(r.Context(), tx, updated)
	if err != nil {
		return errInternal
	}
	splitPlan, err := s.journeyPlanAPI(r.Context(), tx, splitJourney)
	if err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "split_journey", EntityType: "journey", EntityID: journeyID.String(),
		Success: true, OccurredAt: now,
		Details: map[string]any{"splitJourneyId": splitJourney.ID.String(),
			"sampleIds": uuidStrings(wanted), "planVersion": updated.PlanVersion}})

	out := map[string]any{"journey": originalPlan, "splitJourney": splitPlan}
	if err := s.saveIdempotent(r.Context(), tx, "split-journey", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// releaseUnreservedResources drops reservations left behind with no sample on the journey.
func (s *Server) releaseUnreservedResources(ctx context.Context, q querier, journeyID uuid.UUID) error {
	rows, err := q.Query(ctx,
		`SELECT id, resource_type, resource_id, units, cooled FROM capacity_reservations
         WHERE journey_id = $1 AND NOT released
           AND (sample_id IS NULL OR sample_id NOT IN
                (SELECT sample_id FROM journey_samples WHERE journey_id = $1))`, journeyID)
	if err != nil {
		return err
	}
	type reservation struct {
		id       uuid.UUID
		kind     string
		resource uuid.UUID
		units    int
		cooled   bool
	}
	var stale []reservation
	for rows.Next() {
		var res reservation
		if err := rows.Scan(&res.id, &res.kind, &res.resource, &res.units, &res.cooled); err != nil {
			rows.Close()
			return err
		}
		stale = append(stale, res)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}
	for _, res := range stale {
		table := "locations"
		if res.kind == "connection" {
			table = "connections"
		}
		column := "reserved_units"
		if res.cooled {
			column = "cooled_reserved_units"
		}
		if _, err := q.Exec(ctx,
			`UPDATE `+table+` SET `+column+` = greatest(`+column+` - $2, 0) WHERE id = $1`,
			res.resource, res.units); err != nil {
			return err
		}
		if _, err := q.Exec(ctx,
			`UPDATE capacity_reservations SET released = true WHERE id = $1`, res.id); err != nil {
			return err
		}
	}
	return nil
}

// handleMergeJourneys combines compatible journeys into one batched journey.
func (s *Server) handleMergeJourneys(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}
	targetID, ok := parseUUID(body.TargetJourneyID)
	if !ok {
		return errNotFound
	}
	if body.ExpectedPlanVersion < 1 {
		return errf(http.StatusBadRequest, "invalid_plan_version",
			"expectedPlanVersion must be at least 1")
	}
	if len(body.SourceJourneyIDs) == 0 {
		return errf(http.StatusConflict, "invalid_merge", "sourceJourneyIds must not be empty")
	}
	sources := make([]uuid.UUID, 0, len(body.SourceJourneyIDs))
	for _, raw := range body.SourceJourneyIDs {
		id, ok := parseUUID(raw)
		if !ok {
			return errf(http.StatusConflict, "invalid_merge", "%q is not a valid journey id", raw)
		}
		if id == targetID {
			return errf(http.StatusConflict, "invalid_merge",
				"a journey cannot be merged into itself")
		}
		if containsUUID(sources, id) {
			return errf(http.StatusConflict, "invalid_merge", "journey %s is listed twice", id)
		}
		sources = append(sources, id)
	}
	stored, err := s.lookupIdempotent(r.Context(), "merge-journeys", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	now := s.now()
	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	target, err := s.lockJourney(r.Context(), tx, targetID, body.ExpectedPlanVersion)
	if err != nil {
		return err
	}
	if inProgress, err := s.hasWorkInProgress(r.Context(), tx, targetID); err != nil {
		return errInternal
	} else if inProgress {
		return errf(http.StatusConflict, "work_in_progress",
			"the target journey already has work in progress")
	}

	movedSamples := []uuid.UUID{}
	for _, sourceID := range sources {
		var locked uuid.UUID
		if err := tx.QueryRow(r.Context(),
			`SELECT id FROM journeys WHERE id = $1 FOR UPDATE`, sourceID).Scan(&locked); err != nil {
			return errNotFound
		}
		source, err := s.journeyByID(r.Context(), tx, sourceID)
		if err != nil {
			return err
		}
		if journeyInactive(source.Status) {
			return errf(http.StatusConflict, "inactive_plan",
				"source journey %s is no longer active", sourceID)
		}
		if inProgress, err := s.hasWorkInProgress(r.Context(), tx, sourceID); err != nil {
			return errInternal
		} else if inProgress {
			return errf(http.StatusConflict, "partial_journey_merge",
				"source journey %s already has work in progress", sourceID)
		}
		sourceSamples, err := s.journeySampleIDs(r.Context(), tx, sourceID)
		if err != nil {
			return errInternal
		}
		for _, sid := range sourceSamples {
			if _, err := tx.Exec(r.Context(),
				`INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1, $2)
                 ON CONFLICT DO NOTHING`, targetID, sid); err != nil {
				return errInternal
			}
			movedSamples = append(movedSamples, sid)
		}
		if err := s.cancelUnfinishedWork(r.Context(), tx, source, now, "superseded"); err != nil {
			return errInternal
		}
		if err := s.releaseJourneyCapacity(r.Context(), tx, sourceID); err != nil {
			return errInternal
		}
		if _, err := tx.Exec(r.Context(),
			`UPDATE journeys SET status = 'superseded', replaced_by_journey_id = $2, updated_at = $3
             WHERE id = $1`, sourceID, targetID, now); err != nil {
			return errInternal
		}
	}

	allSamples, err := s.journeySampleIDs(r.Context(), tx, targetID)
	if err != nil {
		return errInternal
	}
	// Reject the merge unless the combined samples may legally travel together.
	if err := s.validateBatchCompatibility(r.Context(), tx, allSamples); err != nil {
		return err
	}

	// The merged samples must be covered by reservations on the target journey's resources.
	resources, connResources, cooled, err := s.journeyResources(r.Context(), tx, targetID)
	if err != nil {
		return errInternal
	}
	for _, sid := range movedSamples {
		if err := s.reserveCapacity(r.Context(), tx, targetID, sid, resources, connResources, cooled); err != nil {
			return err
		}
		if _, err := tx.Exec(r.Context(),
			`UPDATE samples SET active_journey_id = $2, updated_at = $3 WHERE id = $1`,
			sid, targetID, now); err != nil {
			return errInternal
		}
	}
	routeMode := "direct"
	if len(allSamples) > 1 {
		routeMode = "batched"
	}
	if _, err := tx.Exec(r.Context(),
		`UPDATE journeys SET route_mode = $2, plan_version = plan_version + 1, updated_at = $3
         WHERE id = $1`, targetID, routeMode, now); err != nil {
		return errInternal
	}

	updated, err := s.journeyByID(r.Context(), tx, targetID)
	if err != nil {
		return errInternal
	}
	if err := s.validateJourney(r.Context(), tx, updated, now); err != nil {
		return err
	}
	out, err := s.journeyPlanAPI(r.Context(), tx, updated)
	if err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "merge_journeys", EntityType: "journey", EntityID: targetID.String(),
		Success: true, OccurredAt: now,
		Details: map[string]any{"sourceJourneyIds": uuidStrings(sources),
			"sampleIds": uuidStrings(allSamples), "planVersion": updated.PlanVersion}})
	if err := s.saveIdempotent(r.Context(), tx, "merge-journeys", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	writeData(w, http.StatusCreated, out)
	return nil
}

// journeyResources lists the nodes and connections a journey already reserves.
func (s *Server) journeyResources(ctx context.Context, q querier, journeyID uuid.UUID) ([]uuid.UUID, []uuid.UUID, bool, error) {
	rows, err := q.Query(ctx,
		`SELECT DISTINCT resource_type, resource_id, cooled FROM capacity_reservations
         WHERE journey_id = $1 AND NOT released`, journeyID)
	if err != nil {
		return nil, nil, false, err
	}
	defer rows.Close()
	nodes := []uuid.UUID{}
	conns := []uuid.UUID{}
	cooled := false
	for rows.Next() {
		var (
			kind     string
			id       uuid.UUID
			isCooled bool
		)
		if err := rows.Scan(&kind, &id, &isCooled); err != nil {
			return nil, nil, false, err
		}
		if isCooled {
			cooled = true
		}
		if kind == "connection" {
			conns = append(conns, id)
		} else {
			nodes = append(nodes, id)
		}
	}
	return nodes, conns, cooled, rows.Err()
}

// handleReportDisruption replans every unfinished journey affected by an unavailable resource.
func (s *Server) handleReportDisruption(w http.ResponseWriter, r *http.Request, rc *requestContext) error {
	var body struct {
		ResourceType   string  `json:"resourceType"`
		ResourceID     string  `json:"resourceId"`
		Reason         *string `json:"reason"`
		OccurredAt     string  `json:"occurredAt"`
		IdempotencyKey string  `json:"idempotencyKey"`
	}
	hash, err := decodeBodyRaw(r, &body)
	if err != nil {
		return err
	}
	if body.IdempotencyKey == "" {
		return errIdemRequired
	}
	if rc.Role == "" {
		return errRoleNotSet
	}
	if err := rc.requireRole(RoleDispatcher, RoleAdministrator); err != nil {
		return err
	}
	if !validResourceTypes[body.ResourceType] {
		return errf(http.StatusBadRequest, "invalid_resource_type",
			"unknown resourceType %q", body.ResourceType)
	}
	occurredAt, err := parseTimeCode(body.OccurredAt, "invalid_time")
	if err != nil {
		return err
	}
	stored, err := s.lookupIdempotent(r.Context(), "report-disruption", body.IdempotencyKey, rc.User.ID, hash)
	if err != nil {
		return err
	}
	if stored != nil {
		writeStored(w, stored)
		return nil
	}

	tx, err := s.pool.Begin(r.Context())
	if err != nil {
		return errInternal
	}
	defer func() { _ = tx.Rollback(r.Context()) }()

	affectedJourneys, err := s.journeysAffectedBy(r.Context(), tx, body.ResourceType, body.ResourceID)
	if err != nil {
		return err
	}
	// Take the resource out of service so replanning avoids it.
	if err := s.deactivateResource(r.Context(), tx, body.ResourceType, body.ResourceID, occurredAt); err != nil {
		return err
	}

	disruptionID := uuid.New()
	reason := ""
	if body.Reason != nil {
		reason = *body.Reason
	}
	affectedSamples := []string{}
	replacementIDs := []string{}
	overall := "not_required"
	for _, j := range affectedJourneys {
		sampleIDs, err := s.journeySampleIDs(r.Context(), tx, j.ID)
		if err != nil {
			return errInternal
		}
		result, err := s.replanJourney(r.Context(), tx, j, rc, occurredAt, "disruption:"+body.ResourceType)
		if err != nil {
			return err
		}
		for _, sid := range sampleIDs {
			affectedSamples = append(affectedSamples, sid.String())
		}
		if result.ReplacementID != "" {
			replacementIDs = append(replacementIDs, result.ReplacementID)
		}
		overall = mergeReplanStatus(overall, result.Status)
	}

	if _, err := tx.Exec(r.Context(),
		`INSERT INTO disruptions (id, resource_type, resource_id, reason, occurred_at, reported_by,
             replan_status) VALUES ($1, $2, $3, $4, $5, $6, $7)`,
		disruptionID, body.ResourceType, body.ResourceID, reason, occurredAt, rc.User.ID,
		overall); err != nil {
		return errInternal
	}
	s.auditTx(r.Context(), tx, auditRecord{ActorID: rc.actorID(), Role: rc.Role,
		Action: "report_disruption", EntityType: "disruption", EntityID: disruptionID.String(),
		Success: true, OccurredAt: occurredAt,
		Details: map[string]any{"resourceType": body.ResourceType, "resourceId": body.ResourceID,
			"reason": reason, "replanStatus": overall, "affectedSampleIds": affectedSamples,
			"replacementPlanIds": replacementIDs}})

	out := map[string]any{
		"disruptionId":       disruptionID.String(),
		"affectedSampleIds":  affectedSamples,
		"replacementPlanIds": replacementIDs,
		"replanStatus":       overall,
	}
	if err := s.saveIdempotent(r.Context(), tx, "report-disruption", body.IdempotencyKey,
		rc.User.ID, hash, http.StatusCreated, map[string]any{"data": out}); err != nil {
		return errInternal
	}
	s.publishEvent(r.Context(), tx, RealtimeEvent{Type: "disruption.reported",
		EntityType: "disruption", EntityID: disruptionID.String(), Payload: out,
		audience: []string{RoleDispatcher, RoleAdministrator}})
	if err := tx.Commit(r.Context()); err != nil {
		return errInternal
	}
	s.bumpNetworkRevision(r.Context())
	go s.rebuildServiceabilityAsync()
	writeData(w, http.StatusCreated, out)
	return nil
}

var validResourceTypes = map[string]bool{
	"location": true, "node": true, "laboratory": true, "connection": true, "route": true,
	"worker": true, "capacity": true,
}

// mergeReplanStatus combines per-journey outcomes into one overall status.
func mergeReplanStatus(current, next string) string {
	rank := map[string]int{"not_required": 0, "replaced": 1, "exception": 2, "expired": 3}
	if rank[next] > rank[current] {
		return next
	}
	return current
}

// journeysAffectedBy finds unfinished journeys that depend on the disrupted resource.
func (s *Server) journeysAffectedBy(ctx context.Context, q querier, resourceType, resourceID string) ([]*Journey, error) {
	var (
		rows interface{ Next() bool }
		err  error
	)
	_ = rows
	_ = err

	switch resourceType {
	case "worker":
		workerID, ok := parseUUID(resourceID)
		if !ok {
			return nil, errNotFound
		}
		if _, err := s.userByID(ctx, q, workerID); err != nil {
			return nil, errNotFound
		}
		return s.queryJourneys(ctx, q,
			`SELECT `+journeyColumns+` FROM journeys j
             WHERE j.status NOT IN ('cancelled', 'completed', 'superseded', 'expired')
               AND EXISTS (SELECT 1 FROM assignments a WHERE a.journey_id = j.id
                   AND (a.worker_id = $1 OR a.offered_to = $1)
                   AND a.status NOT IN ('completed', 'cancelled', 'superseded'))`, workerID)
	case "connection", "route":
		connID, ok := parseUUID(resourceID)
		if !ok {
			return nil, errNotFound
		}
		if _, err := s.connectionByID(ctx, q, connID); err != nil {
			return nil, errNotFound
		}
		return s.queryJourneys(ctx, q,
			`SELECT `+journeyColumns+` FROM journeys j
             WHERE j.status NOT IN ('cancelled', 'completed', 'superseded', 'expired')
               AND EXISTS (SELECT 1 FROM assignments a WHERE a.journey_id = j.id
                   AND a.connection_id = $1
                   AND a.status NOT IN ('completed', 'cancelled', 'superseded'))`, connID)
	default:
		locationID, ok := parseUUID(resourceID)
		if !ok {
			return nil, errNotFound
		}
		if _, err := s.locationByID(ctx, q, locationID); err != nil {
			return nil, errNotFound
		}
		return s.queryJourneys(ctx, q,
			`SELECT `+journeyColumns+` FROM journeys j
             WHERE j.status NOT IN ('cancelled', 'completed', 'superseded', 'expired')
               AND (EXISTS (SELECT 1 FROM journey_stops st WHERE st.journey_id = j.id
                       AND st.location_id = $1 AND st.completed_at IS NULL)
                 OR EXISTS (SELECT 1 FROM assignments a WHERE a.journey_id = j.id
                       AND (a.from_location_id = $1 OR a.to_location_id = $1
                            OR a.node_id = $1 OR a.laboratory_id = $1)
                       AND a.status NOT IN ('completed', 'cancelled', 'superseded')))`, locationID)
	}
}

func (s *Server) queryJourneys(ctx context.Context, q querier, sql string, args ...any) ([]*Journey, error) {
	rows, err := q.Query(ctx, sql, args...)
	if err != nil {
		return nil, errInternal
	}
	defer rows.Close()
	out := []*Journey{}
	for rows.Next() {
		j, err := scanJourney(rows)
		if err != nil {
			return nil, errInternal
		}
		out = append(out, j)
	}
	if err := rows.Err(); err != nil {
		return nil, errInternal
	}
	return out, nil
}

// deactivateResource marks the disrupted resource unavailable.
func (s *Server) deactivateResource(ctx context.Context, q querier, resourceType, resourceID string, now time.Time) error {
	switch resourceType {
	case "worker":
		id, ok := parseUUID(resourceID)
		if !ok {
			return errNotFound
		}
		_, err := q.Exec(ctx, `UPDATE users SET available = false WHERE id = $1`, id)
		if err != nil {
			return errInternal
		}
	case "connection", "route":
		id, ok := parseUUID(resourceID)
		if !ok {
			return errNotFound
		}
		if _, err := q.Exec(ctx, `UPDATE connections SET active = false WHERE id = $1`, id); err != nil {
			return errInternal
		}
	case "location", "node", "laboratory":
		id, ok := parseUUID(resourceID)
		if !ok {
			return errNotFound
		}
		if _, err := q.Exec(ctx, `UPDATE locations SET active = false WHERE id = $1`, id); err != nil {
			return errInternal
		}
	case "capacity":
		// A capacity pool becoming unavailable leaves the location itself in service.
		return nil
	}
	return nil
}

func (s *Server) rebuildServiceabilityAsync() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	_ = s.rebuildServiceability(ctx)
}
