{"command":"create","path":"/workspace/backend/cmd/server/main.go","file_text":"// Command server runs the lab sample pickup and delivery application.
package main

import (
	"context"
	"flag"
	"log"
	"os/signal"
	"syscall"

	"labsample/internal/app"
)

func main() {
	migrateOnly := flag.Bool("migrate", false,
		"apply migrations and materialize the datastore structure, then exit")
	flag.Parse()

	log.SetFlags(log.LstdFlags | log.Lmsgprefix)
	log.SetPrefix("labsample ")

	ctx, stop := signal.NotifyContext(context.Background(), syscall.SIGINT, syscall.SIGTERM)
	defer stop()

	cfg := app.LoadConfig()
	server, err := app.New(ctx, cfg)
	if err != nil {
		log.Fatalf("startup failed: %v", err)
	}
	defer server.Close()

	if *migrateOnly {
		if err := server.Migrate(ctx); err != nil {
			log.Fatalf("migration failed: %v", err)
		}
		log.Print("migrations applied")
		return
	}

	if err := server.Bootstrap(ctx); err != nil {
		log.Fatalf("bootstrap failed: %v", err)
	}
	if err := server.Run(ctx); err != nil {
		log.Fatalf("server stopped: %v", err)
	}
}
