const TOKEN_KEY = 'lsl.sessionToken';

export class ApiError extends Error {
  code: string;
  status: number;
  constructor(status: number, code: string, message: string) {
    super(message);
    this.code = code;
    this.status = status;
  }
}

export function getToken(): string | null {
  return localStorage.getItem(TOKEN_KEY);
}
export function setToken(token: string | null) {
  if (token) localStorage.setItem(TOKEN_KEY, token);
  else localStorage.removeItem(TOKEN_KEY);
}

export function newIdempotencyKey(): string {
  if (crypto.randomUUID) return crypto.randomUUID();
  return `k-${Date.now()}-${Math.random().toString(16).slice(2)}`;
}

async function call<T>(path: string, body?: unknown, method = 'POST'): Promise<T> {
  const headers: Record<string, string> = {};
  const token = getToken();
  if (token) headers.Authorization = `Bearer ${token}`;
  if (body !== undefined) headers['Content-Type'] = 'application/json';

  const res = await fetch(`/api${path}`, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
  });

  const text = await res.text();
  let parsed: unknown = null;
  if (text) {
    try {
      parsed = JSON.parse(text);
    } catch {
      throw new ApiError(res.status, 'invalid_response', 'server returned a non-JSON response');
    }
  }
  if (!res.ok) {
    const envelope = (parsed ?? {}) as { error?: string; code?: string };
    throw new ApiError(res.status, envelope.code ?? 'unknown', envelope.error ?? res.statusText);
  }
  return ((parsed as { data?: T })?.data ?? (parsed as T)) as T;
}

