{"command":"create","path":"/workspace/frontend/src/state/session.tsx","file_text":"import { createContext, useCallback, useContext, useEffect, useMemo, useState } from 'react';
import type { ReactNode } from 'react';
import { api, ApiError, getToken, setToken } from '../api/client';
import type { BootstrapUser } from '../api/types';

interface SessionValue {
  user: BootstrapUser | null;
  loading: boolean;
  signIn: (username: string, password: string) => Promise<void>;
  signOut: () => void;
  selectRole: (role: string) => Promise<void>;
  refresh: () => Promise<void>;
  serverTime: string | null;
}

const SessionContext = createContext<SessionValue | null>(null);

export function SessionProvider({ children }: { children: ReactNode }) {
  const [user, setUser] = useState<BootstrapUser | null>(null);
  const [serverTime, setServerTime] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  const refresh = useCallback(async () => {
    if (!getToken()) {
      setUser(null);
      setLoading(false);
      return;
    }
    try {
      const data = await api.bootstrap();
      setUser(data.user);
      setServerTime(data.serverTime);
    } catch (err) {
      // An expired or rejected token must not leave a half-signed-in shell on screen.
      if (err instanceof ApiError && err.status === 401) {
        setToken(null);
        setUser(null);
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const signIn = useCallback(
    async (username: string, password: string) => {
      const res = await api.authenticateUser(username, password);
      setToken(res.sessionToken);
      await refresh();
    },
    [refresh],
  );

  const signOut = useCallback(() => {
    setToken(null);
    setUser(null);
  }, []);

  const selectRole = useCallback(
    async (role: string) => {
      const res = await api.selectActiveRole(role);
      // Selecting a role must never change which roles the account holds.
      setUser((prev) => (prev ? { ...prev, activeRole: res.activeRole, roles: res.roles } : prev));
    },
    [],
  );

  const value = useMemo<SessionValue>(
    () => ({ user, loading, signIn, signOut, selectRole, refresh, serverTime }),
    [user, loading, signIn, signOut, selectRole, refresh, serverTime],
  );

  return <SessionContext.Provider value={value}>{children}</SessionContext.Provider>;
}

export function useSession(): SessionValue {
  const ctx = useContext(SessionContext);
  if (!ctx) throw new Error('useSession must be used inside SessionProvider');
  return ctx;
}
