{"command":"create","path":"/workspace/frontend/src/components/common.tsx","file_text":"import type { ReactNode } from 'react';
import type { TimelineEntry } from '../api/types';

export function Panel({
  title,
  children,
  actions,
}: {
  title: string;
  children: ReactNode;
  actions?: ReactNode;
}) {
  return (
    <section className="panel" aria-label={title}>
      <div className="row" style={{ justifyContent: 'space-between' }}>
        <h2>{title}</h2>
        {actions}
      </div>
      {children}
    </section>
  );
}

export function Notice({ kind, children }: { kind: 'error' | 'success' | 'info'; children: ReactNode }) {
  return (
    <div className={`notice ${kind}`} role={kind === 'error' ? 'alert' : 'status'}>
      {children}
    </div>
  );
}

export function Field({
  label,
  children,
}: {
  label: string;
  children: ReactNode;
}) {
  return (
    <div>
      <label>{label}</label>
      {children}
    </div>
  );
}

export function StatusBadge({ status }: { status: string }) {
  const bad = /exception|expired|cancelled|declined|unserviceable|failed/i.test(status);
  const ok = /received|completed|confirmed|accepted|serviceable|sealed|available/i.test(status);
  return <span className={`badge ${bad ? 'bad' : ok ? 'ok' : ''}`}>{status.replace(/_/g, ' ')}</span>;
}

export function FreshnessBadge({
  stale,
  recordedAt,
}: {
  stale: boolean | undefined;
  recordedAt?: string;
}) {
  if (stale === undefined) return null;
  return (
    <span className={`badge ${stale ? 'warn' : 'ok'}`} title={recordedAt ?? 'never recorded'}>
      {stale ? 'Location stale' : 'Location fresh'}
    </span>
  );
}

export function fmt(ts?: string | null): string {
  if (!ts) return '—';
  const d = new Date(ts);
  if (Number.isNaN(d.getTime())) return ts;
  return d.toLocaleString();
}

export function shortId(id?: string): string {
  return id ? id.slice(0, 8) : '—';
}

/** Renders a status history in the order the server returned it (durable event order). */
export function Timeline({ entries, label }: { entries: TimelineEntry[]; label?: string }) {
  if (!entries?.length) return <p className="muted">No status history yet.</p>;
  return (
    <ol className="timeline" aria-label={label ?? 'Status timeline'}>
      {entries.map((e) => (
        <li key={`${e.eventId}-${e.action}`}>
          <div className="row" style={{ justifyContent: 'space-between' }}>
            <strong>{e.action.replace(/_/g, ' ')}</strong>
            <span className="muted mono">{fmt(e.occurredAt)}</span>
          </div>
          <div className="muted" style={{ fontSize: 12 }}>
            {e.role ? `${e.role.replace(/_/g, ' ')} · ` : ''}
            {e.entityType} {shortId(e.entityId)}
            {e.success ? '' : ' · failed'}
          </div>
        </li>
      ))}
    </ol>
  );
}

export function CapacityBar({
  label,
  configured,
  reserved,
  available,
}: {
  label: string;
  configured: number;
  reserved: number;
  available: number;
}) {
  const pct = configured > 0 ? Math.min(100, (reserved / configured) * 100) : 0;
  return (
    <div>
      <div className="row" style={{ justifyContent: 'space-between' }}>
        <span className="muted" style={{ fontSize: 12, fontWeight: 600 }}>
          {label}
        </span>
        <span className="mono">
          {reserved}/{configured} reserved · {available} available
        </span>
      </div>
      <div style={{ height: 7, background: '#e8edf2', borderRadius: 4, marginTop: 4 }}>
        <div
          style={{
            width: `${pct}%`,
            height: '100%',
            background: pct > 90 ? 'var(--danger)' : 'var(--accent)',
            borderRadius: 4,
          }}
        />
      </div>
    </div>
  );
}
