import maplibregl from 'maplibre-gl';
import { Protocol } from 'pmtiles';
import 'maplibre-gl/dist/maplibre-gl.css';
import type { OperationsConnection, OperationsLocation, OperationsWorker } from '../api/types';

// Registered once per page: MapLibre keeps protocol handlers in a global registry.
let protocolRegistered = false;
function registerPmtiles() {
  if (protocolRegistered) return;
  const protocol = new Protocol();
  maplibregl.addProtocol('pmtiles', protocol.tile);
  protocolRegistered = true;
}

export interface MapMarker {
  id: string;
  latitude: number;
  longitude: number;
  label: string;
  kind: 'location' | 'worker' | 'sample';
  detail?: string;
}

export function NetworkMap({
  locations = [],
  connections = [],
  workers = [],
  extraMarkers = [],
}: {
  locations?: OperationsLocation[];
  connections?: OperationsConnection[];
  workers?: OperationsWorker[];
  extraMarkers?: MapMarker[];
}) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);
  const readyRef = useRef(false);

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;
    registerPmtiles();
    const map = new maplibregl.Map({
      container: containerRef.current,
      // Style, glyphs, sprites and tiles are all served from our own origin.
      style: '/map-assets/style.json',
      center: [77.5946, 12.9716],
      zoom: 10.5,
      attributionControl: { compact: true },
    });
    map.addControl(new maplibregl.NavigationControl({ showCompass: false }), 'top-right');
    map.on('load', () => {
      readyRef.current = true;
      map.addSource('routes', {
        type: 'geojson',
        data: { type: 'FeatureCollection', features: [] },
      });
      map.addLayer({
        id: 'routes-line',
        type: 'line',
        source: 'routes',
        paint: {
          'line-color': ['case', ['get', 'active'], '#1d6fa5', '#b3261e'],
          'line-width': 3,
          'line-dasharray': ['case', ['get', 'active'], ['literal', [1]], ['literal', [2, 2]]],
          'line-opacity': 0.8,
        },
      });
    });
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
      readyRef.current = false;
    };
  }, []);

  // Connections -> line features.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const apply = () => {
      const src = map.getSource('routes') as maplibregl.GeoJSONSource | undefined;
      if (!src) return;
      const byId = new Map(locations.map((l) => [l.locationId, l]));
      const features = connections
        .map((c) => {
          const a = byId.get(c.fromLocationId);
          const b = byId.get(c.toLocationId);
          if (!a || !b) return null;
          return {
            type: 'Feature' as const,
            properties: { active: c.active && a.active && b.active },
            geometry: {
              type: 'LineString' as const,
              coordinates: [
                [a.coordinate.longitude, a.coordinate.latitude],
                [b.coordinate.longitude, b.coordinate.latitude],
              ],
            },
          };
        })
        .filter((f): f is NonNullable<typeof f> => f !== null);
      src.setData({ type: 'FeatureCollection', features });
    };
    if (readyRef.current) apply();
    else map.once('load', apply);
  }, [connections, locations]);

  // Markers for nodes, workers and any caller-supplied points.
  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = [];

    const points: MapMarker[] = [
      ...locations.map((l) => ({
        id: l.locationId,
        latitude: l.coordinate.latitude,
        longitude: l.coordinate.longitude,
        label: l.name,
        kind: 'location' as const,
        detail: [
          Object.entries(l.functions)
            .filter(([, on]) => on)
            .map(([k]) => k.replace(/_/g, ' '))
            .join(', '),
          l.active ? 'active' : 'inactive',
        ]
          .filter(Boolean)
          .join(' · '),
      })),
      ...workers
        .filter((w) => w.latestLocation)
        .map((w) => ({
          id: w.workerId,
          latitude: w.latestLocation!.latitude,
          longitude: w.latestLocation!.longitude,
          label: w.fullName || `Worker ${w.workerId.slice(0, 8)}`,
          kind: 'worker' as const,
          detail: `${(w.roles ?? []).join(', ')} · ${w.locationStale ? 'stale' : 'fresh'}`,
        })),
      ...extraMarkers,
    ];

    for (const p of points) {
      const el = document.createElement('div');
      const color =
        p.kind === 'worker' ? '#9a6400' : p.kind === 'sample' ? '#1d7a45' : '#1d6fa5';
      el.style.cssText = `width:13px;height:13px;border-radius:${
        p.kind === 'location' ? '3px' : '50%'
      };background:${color};border:2px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.3)`;
      el.title = p.label;
      const marker = new maplibregl.Marker({ element: el })
        .setLngLat([p.longitude, p.latitude])
        .setPopup(
          new maplibregl.Popup({ offset: 12 }).setHTML(
            `<strong>${escapeHtml(p.label)}</strong>${
              p.detail ? `<br/><span style="color:#5d6b7a">${escapeHtml(p.detail)}</span>` : ''
            }`,
          ),
        )
        .addTo(map);
      markersRef.current.push(marker);
    }
  }, [locations, workers, extraMarkers]);

  return <div className="map" ref={containerRef} role="region" aria-label="Network map" />;
}

function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) =>
    ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c] as string),
  );
}
