{"command":"create","path":"/workspace/frontend/src/components/RoleSwitcher.tsx","file_text":"import { useState } from 'react';
import { useSession } from '../state/session';
import { ROLE_LABELS } from '../api/types';

/**
 * Lets a multi-role account choose which role it is acting under. Selecting a role
 * only changes the session's active role; the account keeps every role it holds.
 */
export function RoleSwitcher() {
  const { user, selectRole } = useSession();
  const [busy, setBusy] = useState<string | null>(null);
  if (!user) return null;

  async function pick(role: string) {
    if (role === user!.activeRole) return;
    setBusy(role);
    try {
      await selectRole(role);
    } finally {
      setBusy(null);
    }
  }

  return (
    <div className="row" role="group" aria-label="Active role">
      <span className="muted" style={{ fontSize: 12, fontWeight: 600 }}>
        Acting as
      </span>
      {user.roles.map((role) => (
        <button
          key={role}
          type="button"
          aria-pressed={role === user.activeRole}
          aria-label={`Act as ${ROLE_LABELS[role] ?? role}`}
          disabled={busy !== null}
          onClick={() => void pick(role)}
        >
          {ROLE_LABELS[role] ?? role}
        </button>
      ))}
    </div>
  );
}
