{"command":"create","path":"/workspace/frontend/src/views/MyWork.tsx","file_text":"import { useCallback, useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api, ApiError } from '../api/client';
import type { RoleWork, WorkItem } from '../api/types';
import { useSession } from '../state/session';
import { Notice, Panel, StatusBadge, Timeline, fmt, shortId } from '../components/common';
import { AssignmentActions } from '../components/AssignmentActions';

const ROLE_WORK_TITLE: Record<string, string> = {
  requester: 'My requests',
  collection_professional: 'My collection work',
  delivery_partner: 'My delivery work',
  node_handler: 'My node work',
  laboratory_team: 'My laboratory work',
  dispatcher: 'Dispatch work queue',
  administrator: 'Administration work queue',
};

export function MyWork() {
  const { user } = useSession();
  const role = user?.activeRole ?? '';
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [expanded, setExpanded] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      setWork(await api.listRoleWork(role));
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Could not load work.');
      setWork(null);
    }
  }, [role]);

  useEffect(() => {
    void load();
  }, [load]);

  const groups: Array<[string, WorkItem[]]> = work
    ? [
        ['Pending', work.pending],
        ['In progress', work.inProgress],
        ['Completed', work.completed],
      ]
    : [];

  return (
    <>
      <Panel
        title={ROLE_WORK_TITLE[role] ?? 'My work'}
        actions={
          <button type="button" onClick={() => void load()}>
            Refresh
          </button>
        }
      >
        {error && <Notice kind="error">{error}</Notice>}
        {!work && !error && <p className="muted">Loading…</p>}
        {work && (
          <p className="muted">
            {work.pending.length} pending · {work.inProgress.length} in progress ·{' '}
            {work.completed.length} completed
          </p>
        )}
      </Panel>

      {groups.map(([label, items]) => (
        <Panel key={label} title={`${label} (${items.length})`}>
          {items.length === 0 ? (
            <p className="muted">Nothing {label.toLowerCase()}.</p>
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Kind</th>
                  <th>Reference</th>
                  <th>Status</th>
                  <th>Deadline / ETA</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {items.map((item) => {
                  const key = item.assignmentId ?? item.journeyId ?? item.sampleId ?? '';
                  const isOpen = expanded === key;
                  return (
                    <>
                      <tr key={key}>
                        <td>{item.kind.replace(/_/g, ' ')}</td>
                        <td className="mono">
                          {item.sampleId ? (
                            <Link to={`/samples/${item.sampleId}`}>
                              sample {shortId(item.sampleId)}
                            </Link>
                          ) : item.journeyId ? (
                            <Link to={`/journeys/${item.journeyId}`}>
                              journey {shortId(item.journeyId)}
                            </Link>
                          ) : (
                            shortId(key)
                          )}
                          {item.assignmentId && (
                            <div className="muted">assignment {shortId(item.assignmentId)}</div>
                          )}
                        </td>
                        <td>
                          <StatusBadge status={item.status} />
                        </td>
                        <td className="mono">
                          {fmt(item.deliveryDeadline ?? item.estimatedDeliveryAt)}
                          {item.offerExpiresAt && (
                            <div className="muted">offer expires {fmt(item.offerExpiresAt)}</div>
                          )}
                        </td>
                        <td>
                          <div className="row">
                            <button
                              type="button"
                              className="subtle"
                              aria-expanded={isOpen}
                              onClick={() => setExpanded(isOpen ? null : key)}
                            >
                              {isOpen ? 'Hide history' : 'History'}
                            </button>
                          </div>
                        </td>
                      </tr>
                      {isOpen && (
                        <tr key={`${key}-detail`}>
                          <td colSpan={5}>
                            {item.assignmentId && (
                              <AssignmentActions item={item} onDone={() => void load()} />
                            )}
                            <h3>Status timeline</h3>
                            <Timeline
                              entries={item.history}
                              label={`Status timeline for ${item.kind} ${shortId(key)}`}
                            />
                          </td>
                        </tr>
                      )}
                    </>
                  );
                })}
              </tbody>
            </table>
          )}
        </Panel>
      ))}
    </>
  );
}
