{"command":"create","path":"/workspace/frontend/src/components/AssignmentActions.tsx","file_text":"import { useState } from 'react';
import { api, ApiError } from '../api/client';
import type { WorkItem } from '../api/types';
import { useSession } from '../state/session';
import { CapacityBar, Field, Notice } from './common';

const TRANSPORT_PROGRESS = ['at_pickup', 'picked_up', 'in_transit', 'arrived', 'delivered'];
const NODE_PROGRESS = ['in_progress', 'completed'];

function nowIso() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}

/**
 * Action surface for one offered/active assignment. Which controls appear depends on
 * the assignment kind and its current status, mirroring the backend's own gating.
 */
export function AssignmentActions({ item, onDone }: { item: WorkItem; onDone: () => void }) {
  const { user } = useSession();
  const [error, setError] = useState<string | null>(null);
  const [ok, setOk] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  // collect & seal inputs
  const [containerType, setContainerType] = useState('standard');
  const [temperature, setTemperature] = useState('20');
  const [lat, setLat] = useState('12.9716');
  const [lon, setLon] = useState('77.5946');

  const assignmentId = item.assignmentId!;
  const offered = item.status === 'offered';
  const active = ['accepted', 'in_progress', 'at_pickup', 'picked_up', 'in_transit', 'arrived'].includes(
    item.status,
  );

  async function run(label: string, fn: () => Promise<unknown>) {
    setBusy(true);
    setError(null);
    setOk(null);
    try {
      await fn();
      setOk(`${label} recorded.`);
      onDone();
    } catch (err) {
      setError(err instanceof ApiError ? `${label} failed: ${err.message} (${err.code})` : `${label} failed.`);
    } finally {
      setBusy(false);
    }
  }

  const progressOptions = item.kind === 'transport' ? TRANSPORT_PROGRESS : NODE_PROGRESS;

  return (
    <div className="stack" style={{ marginBottom: 12 }}>
      {error && <Notice kind="error">{error}</Notice>}
      {ok && <Notice kind="success">{ok}</Notice>}

      {item.destinationCapacity && (
        <div className="grid two">
          <CapacityBar
            label="Destination regular capacity"
            configured={item.destinationCapacity.capacityUnits}
            reserved={item.destinationCapacity.reservedUnits}
            available={item.destinationCapacity.availableUnits}
          />
          <CapacityBar
            label="Destination cooled capacity"
            configured={item.destinationCapacity.cooledCapacityUnits}
            reserved={item.destinationCapacity.cooledReservedUnits}
            available={item.destinationCapacity.cooledAvailableUnits}
          />
        </div>
      )}

      {offered && (
        <div className="row">
          <button
            type="button"
            className="primary"
            disabled={busy}
            aria-label="Accept assignment"
            onClick={() => void run('Accept', () => api.acceptAssignment(assignmentId))}
          >
            Accept assignment
          </button>
          <button
            type="button"
            className="danger"
            disabled={busy}
            aria-label="Decline assignment"
            onClick={() => void run('Decline', () => api.declineAssignment(assignmentId, 'unavailable'))}
          >
            Decline assignment
          </button>
        </div>
      )}

      {active && (
        <>
          <div className="row">
            {progressOptions.map((status) => (
              <button
                key={status}
                type="button"
                disabled={busy}
                aria-label={`Mark ${status.replace(/_/g, ' ')}`}
                onClick={() =>
                  void run(`Progress ${status}`, () =>
                    api.updateAssignmentProgress(assignmentId, status, nowIso()),
                  )
                }
              >
                {status.replace(/_/g, ' ')}
              </button>
            ))}
          </div>

          <div className="grid three">
            <Field label="Container type">
              <input
                aria-label="Container type"
                value={containerType}
                onChange={(e) => setContainerType(e.target.value)}
              />
            </Field>
            <Field label="Observed temperature (°C)">
              <input
                aria-label="Observed temperature"
                type="number"
                step="0.1"
                value={temperature}
                onChange={(e) => setTemperature(e.target.value)}
              />
            </Field>
            <div style={{ alignSelf: 'end' }}>
              {item.kind === 'collection' && item.status === 'accepted' && (
                <button
                  type="button"
                  className="primary"
                  disabled={busy}
                  aria-label="Collect and seal sample"
                  onClick={() =>
                    void run('Collect and seal', () =>
                      api.collectAndSealSample({
                        sampleId: item.sampleId,
                        assignmentId,
                        collectedAt: nowIso(),
                        containerType,
                        observedTemperatureC: Number(temperature),
                      }),
                    )
                  }
                >
                  Collect &amp; seal sample
                </button>
              )}
              <button
                type="button"
                disabled={busy}
                style={{ marginTop: 6 }}
                aria-label="Record handling checkpoint"
                onClick={() =>
                  void run('Handling checkpoint', () =>
                    api.recordHandlingCheckpoint({
                      sampleId: item.sampleId,
                      assignmentId,
                      containerType,
                      observedTemperatureC: Number(temperature),
                      recordedAt: nowIso(),
                    }),
                  )
                }
              >
                Record handling checkpoint
              </button>
            </div>
          </div>

          {(item.kind === 'collection' || item.kind === 'transport') && (
            <div className="grid three">
              <Field label="Latitude">
                <input
                  aria-label="Latitude"
                  value={lat}
                  onChange={(e) => setLat(e.target.value)}
                />
              </Field>
              <Field label="Longitude">
                <input
                  aria-label="Longitude"
                  value={lon}
                  onChange={(e) => setLon(e.target.value)}
                />
              </Field>
              <div style={{ alignSelf: 'end' }}>
                <button
                  type="button"
                  disabled={busy}
                  aria-label="Record my location"
                  onClick={() =>
                    void run('Location', () =>
                      api.recordWorkerLocation(
                        assignmentId,
                        { latitude: Number(lat), longitude: Number(lon) },
                        Date.now() % 100000,
                        nowIso(),
                      ),
                    )
                  }
                >
                  Record my location
                </button>
              </div>
            </div>
          )}

          {item.kind === 'laboratory' && (
            <div className="row">
              <button
                type="button"
                className="primary"
                disabled={busy}
                aria-label="Confirm laboratory receipt"
                onClick={() =>
                  void run('Laboratory receipt', () =>
                    api.confirmLaboratoryReceipt(
                      item.sampleId!,
                      item.laboratoryId ?? item.nodeId!,
                      nowIso(),
                    ),
                  )
                }
              >
                Confirm receipt
              </button>
              <button
                type="button"
                className="danger"
                disabled={busy}
                aria-label="Record laboratory exception"
                onClick={() =>
                  void run('Laboratory exception', () =>
                    api.recordLaboratoryException({
                      sampleId: item.sampleId,
                      laboratoryId: item.laboratoryId ?? item.nodeId,
                      reason: 'cannot accept sample normally',
                      observedAt: nowIso(),
                    }),
                  )
                }
              >
                Record exception
              </button>
            </div>
          )}
        </>
      )}

      {user && item.currentHolderId === user.userId && (
        <p className="muted" style={{ margin: 0 }}>
          You are the current custodian of this sample.
        </p>
      )}
    </div>
  );
}
","security_risk":"LOW","summary":"Create assignment actions component"}

{"command":"create","path":"/workspace/frontend/src/views/SampleDetail.tsx","file_text":"import { useCallback, useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { api, ApiError } from '../api/client';
import type { JourneyPlan, SampleLifecycle, SampleState } from '../api/types';
import {
  FreshnessBadge,
  Notice,
  Panel,
  StatusBadge,
  Timeline,
  fmt,
  shortId,
} from '../components/common';
import { NetworkMap } from '../components/NetworkMap';

export function SampleDetail() {
  const { sampleId = '' } = useParams();
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<SampleLifecycle | null>(null);
  const [journey, setJourney] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setError(null);
    try {
      const s = await api.readSampleState(sampleId);
      setState(s);
      // Lifecycle and journey are permission-dependent: a requester may see less than
      // a dispatcher, so a failure here must not blank out the sample view.
      try {
        setLifecycle(await api.readSampleLifecycle(sampleId));
      } catch {
        setLifecycle(null);
      }
      const jid = s.activeJourneyId;
      if (jid) {
        try {
          setJourney(await api.readJourneyPlan(jid));
        } catch {
          setJourney(null);
        }
      }
    } catch (err) {
      setError(err instanceof ApiError ? err.message : 'Could not load this sample.');
    }
  }, [sampleId]);

  useEffect(() => {
    void load();
  }, [load]);

  if (error) return <Notice kind="error">{error}</Notice>;
  if (!state) return <p className="muted">Loading sample…</p>;

  const loc = lifecycle?.latestLocation ?? state.latestLocation;
  const recordedAt = lifecycle?.locationRecordedAt ?? state.locationRecordedAt;
  const stale = lifecycle?.locationStale ?? state.locationStale;
  const completed = journey?.orderedStops.filter((s) => s.completedAt).length ?? 0;
  const totalStops = journey?.orderedStops.length ?? 0;
  const exception = lifecycle?.exception;

  return (
    <>
      <Panel
        title={`Sample ${shortId(sampleId)}`}
        actions={
          <button type="button" onClick={() => void load()}>
            Refresh
          </button>
        }
      >
        {exception && (
          <Notice kind="error">
            Exception: {String(exception.kind ?? 'unknown')} —{' '}
            {String(exception.reason ?? 'no reason recorded')}
          </Notice>
        )}
        <div className="row" style={{ marginBottom: 10 }}>
          <StatusBadge status={lifecycle?.status ?? state.state.status} />
          <StatusBadge status={state.serviceability} />
          <FreshnessBadge stale={stale} recordedAt={recordedAt} />
          {lifecycle?.sealed && <span className="badge ok">Sealed</span>}
        </div>
        <dl className="kv">
          <dt>Current status</dt>
          <dd>{(lifecycle?.status ?? state.state.status).replace(/_/g, ' ')}</dd>
          <dt>Current custodian</dt>
          <dd className="mono">
            {lifecycle?.currentHolderId ? shortId(lifecycle.currentHolderId) : 'not yet in custody'}
          </dd>
          <dt>Current or last known location</dt>
          <dd className="mono">
            {loc ? `${loc.latitude.toFixed(5)}, ${loc.longitude.toFixed(5)}` : 'no location recorded'}
          </dd>
          <dt>Last update</dt>
          <dd>{fmt(recordedAt)}</dd>
          <dt>Location freshness</dt>
          <dd>{stale ? 'Stale' : 'Fresh'}</dd>
          <dt>Route progress</dt>
          <dd>
            {totalStops > 0 ? `${completed} of ${totalStops} stops completed` : 'no journey stops yet'}
          </dd>
          <dt>Origin</dt>
          <dd className="mono">
            {state.originType} · {state.origin.latitude.toFixed(5)}, {state.origin.longitude.toFixed(5)}
          </dd>
          <dt>Collection window</dt>
          <dd>{fmt(state.requestedAt)}</dd>
          <dt>Delivery deadline</dt>
          <dd>{fmt(state.deliveryDeadline)}</dd>
          <dt>Handling</dt>
          <dd>
            {state.containerType} · {state.temperatureMinC}°C to {state.temperatureMaxC}°C
          </dd>
          <dt>Target laboratory</dt>
          <dd className="mono">{shortId(state.targetLaboratoryId)}</dd>
          <dt>Active journey</dt>
          <dd className="mono">
            {state.activeJourneyId ? (
              <Link to={`/journeys/${state.activeJourneyId}`}>{shortId(state.activeJourneyId)}</Link>
            ) : (
              '—'
            )}
          </dd>
        </dl>
      </Panel>

      {loc && (
        <Panel title="Sample location">
          <NetworkMap
            extraMarkers={[
              {
                id: sampleId,
                latitude: loc.latitude,
                longitude: loc.longitude,
                label: `Sample ${shortId(sampleId)}`,
                kind: 'sample',
                detail: stale ? 'location stale' : 'location fresh',
              },
            ]}
          />
        </Panel>
