{"command":"create","path":"/workspace/frontend/src/views/RequestSample.tsx","file_text":"import { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { api, ApiError, newIdempotencyKey } from '../api/client';
import type { OperationsLocation, ServiceabilityResult } from '../api/types';
import { Field, Notice, Panel, fmt, shortId } from '../components/common';

const REASON_TEXT: Record<string, string> = {
  serviceable: 'This location and sample can be serviced.',
  outside_service_coverage: 'The origin is not within 5 km of an active collection node.',
  no_accepting_laboratory: 'No active laboratory accepts this sample type.',
  no_route: 'No valid route is available.',
  insufficient_capacity: 'Required regular or cooled capacity is not available.',
  deadline_unreachable: 'The sample cannot reach a laboratory before the deadline.',
  handling_rules_unsatisfiable: 'The handling and container rules cannot be satisfied.',
};

function isoLocal(offsetMinutes: number) {
  const d = new Date(Date.now() + offsetMinutes * 60000);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(
    d.getMinutes(),
  )}`;
}

function toIso(local: string): string {
  return new Date(local).toISOString().replace(/\.\d{3}Z$/, 'Z');
}

export function RequestSample() {
  const navigate = useNavigate();
  const [sampleTypes, setSampleTypes] = useState<Array<Record<string, unknown>>>([]);
  const [nodes, setNodes] = useState<OperationsLocation[]>([]);

  const [originType, setOriginType] = useState<'home' | 'clinic' | 'node'>('home');
  const [latitude, setLatitude] = useState('12.9352');
  const [longitude, setLongitude] = useState('77.6245');
  const [originNodeId, setOriginNodeId] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState('');
  const [containerType, setContainerType] = useState('standard');
  const [tempMin, setTempMin] = useState('15');
  const [tempMax, setTempMax] = useState('30');
  const [earliest, setEarliest] = useState(isoLocal(15));
  const [latest, setLatest] = useState(isoLocal(180));
  const [deadline, setDeadline] = useState(isoLocal(600));

  const [check, setCheck] = useState<ServiceabilityResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [created, setCreated] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    // The serviceability snapshot carries the sample types and the published node set,
    // so a requester can fill the form without any administrator-only endpoint.
    void (async () => {
      try {
        const snap = await api.readServiceabilitySnapshot();
        const types = (snap.sampleTypes ?? []) as Array<Record<string, unknown>>;
        setSampleTypes(types);
        if (types.length && !sampleTypeId) {
          const first = types[0];
          setSampleTypeId(String(first.sampleTypeId ?? first.id ?? ''));
          applyType(first);
        }
        const regions = (snap.regions ?? []) as Array<Record<string, unknown>>;
        setNodes(
          regions.map((r) => ({
            locationId: String(r.locationId),
            id: String(r.locationId),
            name: String(r.name),
            coordinate: { latitude: Number(r.latitude), longitude: Number(r.longitude) },
            active: true,
            coverageKm: Number(r.coverageKm ?? 0),
            handlingMinutes: 0,
            functions: {},
          })),
        );
      } catch {
        setSampleTypes([]);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function applyType(t: Record<string, unknown>) {
    if (t.containerType) setContainerType(String(t.containerType));
    if (t.temperatureMinC !== undefined) setTempMin(String(t.temperatureMinC));
    if (t.temperatureMaxC !== undefined) setTempMax(String(t.temperatureMaxC));
  }

  function payload() {
    const body: Record<string, unknown> = {
      origin: { latitude: Number(latitude), longitude: Number(longitude) },
      originType,
      requestedAt: toIso(earliest),
      earliestCollectionAt: toIso(earliest),
      latestCollectionAt: toIso(latest),
      deliveryDeadline: toIso(deadline),
      sampleTypeId,
      containerType,
      temperatureMinC: Number(tempMin),
      temperatureMaxC: Number(tempMax),
    };
    if (originType === 'node' && originNodeId) body.originNodeId = originNodeId;
    return body;
  }

  async function runCheck() {
    setBusy(true);
    setError(null);
    setCreated(null);
    try {
      // Dry run only: this call must not create a request, sample, journey or reservation.
      setCheck(await api.checkServiceability(payload()));
    } catch (err) {
      setCheck(null);
      setError(err instanceof ApiError ? `${err.message} (${err.code})` : 'Check failed.');
    } finally {
      setBusy(false);
    }
  }

  async function submit(e: React.FormEvent) {
    e.preventDefault();
    setBusy(true);
    setError(null);
    try {
      const res = await api.createCollectionRequest({ ...payload(), idempotencyKey: newIdempotencyKey() });
      const id = String(res.sampleId ?? '');
      setCreated(id);
      if (id) navigate(`/samples/${id}`);
    } catch (err) {
      setError(err instanceof ApiError ? `${err.message} (${err.code})` : 'Could not create the request.');
    } finally {
      setBusy(false);
    }
  }

  return (
    <form onSubmit={submit}>
      <Panel title="Check serviceability and create a collection request">
        {error && <Notice kind="error">{error}</Notice>}
        {created && <Notice kind="success">Request created for sample {shortId(created)}.</Notice>}
        {check && (
          <Notice kind={check.serviceable ? 'success' : 'error'}>
            <strong>{check.serviceable ? 'Serviceable' : 'Not serviceable'}</strong> —{' '}
            {REASON_TEXT[check.reason] ?? check.reason}
            <div className="muted mono" style={{ marginTop: 4 }}>
              serviceability version {check.serviceabilityVersion}
              {check.targetLaboratoryId ? ` · laboratory ${shortId(check.targetLaboratoryId)}` : ''}
              {check.estimatedArrivalAt ? ` · arrives ${fmt(check.estimatedArrivalAt)}` : ''}
            </div>
            <div className="muted" style={{ marginTop: 4, fontSize: 12 }}>
              This was a dry run. Nothing has been created.
            </div>
          </Notice>
        )}

        <div className="grid two">
          <Field label="Origin type">
            <select
              aria-label="Origin type"
              value={originType}
              onChange={(e) => setOriginType(e.target.value as 'home' | 'clinic' | 'node')}
            >
              <option value="home">Patient home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </Field>
          <Field label="Sample type">
            <select
              aria-label="Sample type"
              value={sampleTypeId}
              onChange={(e) => {
                setSampleTypeId(e.target.value);
                const t = sampleTypes.find(
                  (x) => String(x.sampleTypeId ?? x.id) === e.target.value,
                );
                if (t) applyType(t);
              }}
              required
            >
              <option value="">Select a sample type…</option>
              {sampleTypes.map((t) => (
                <option key={String(t.sampleTypeId ?? t.id)} value={String(t.sampleTypeId ?? t.id)}>
                  {String(t.name)}
                </option>
              ))}
            </select>
          </Field>
          {originType === 'node' && (
            <Field label="Origin node">
              <select
                aria-label="Origin node"
                value={originNodeId}
                onChange={(e) => {
                  setOriginNodeId(e.target.value);
                  const n = nodes.find((x) => x.locationId === e.target.value);
                  if (n) {
                    setLatitude(String(n.coordinate.latitude));
                    setLongitude(String(n.coordinate.longitude));
                  }
                }}
              >
                <option value="">Select a node…</option>
                {nodes.map((n) => (
                  <option key={n.locationId} value={n.locationId}>
                    {n.name}
                  </option>
                ))}
              </select>
            </Field>
          )}
          <Field label="Latitude">
            <input
              aria-label="Latitude"
              value={latitude}
              onChange={(e) => setLatitude(e.target.value)}
              required
            />
          </Field>
          <Field label="Longitude">
            <input
              aria-label="Longitude"
              value={longitude}
              onChange={(e) => setLongitude(e.target.value)}
              required
            />
          </Field>
          <Field label="Container type">
            <input
              aria-label="Container type"
              value={containerType}
              onChange={(e) => setContainerType(e.target.value)}
              required
            />
          </Field>
          <Field label="Temperature minimum (°C)">
            <input
              aria-label="Temperature minimum"
              type="number"
              step="0.1"
              value={tempMin}
              onChange={(e) => setTempMin(e.target.value)}
              required
            />
          </Field>
          <Field label="Temperature maximum (°C)">
            <input
              aria-label="Temperature maximum"
              type="number"
              step="0.1"
              value={tempMax}
              onChange={(e) => setTempMax(e.target.value)}
              required
            />
          </Field>
          <Field label="Earliest collection">
            <input
              aria-label="Earliest collection"
              type="datetime-local"
              value={earliest}
              onChange={(e) => setEarliest(e.target.value)}
              required
            />
          </Field>
          <Field label="Latest collection">
            <input
              aria-label="Latest collection"
              type="datetime-local"
              value={latest}
              onChange={(e) => setLatest(e.target.value)}
              required
            />
          </Field>
          <Field label="Delivery deadline">
            <input
              aria-label="Delivery deadline"
              type="datetime-local"
              value={deadline}
              onChange={(e) => setDeadline(e.target.value)}
              required
            />
          </Field>
        </div>

        <div className="row" style={{ marginTop: 14 }}>
          <button
            type="button"
            disabled={busy || !sampleTypeId}
            aria-label="Check serviceability"
            onClick={() => void runCheck()}
          >
            Check serviceability
          </button>
          <button className="primary" type="submit" disabled={busy || !sampleTypeId}>
            Create collection request
          </button>
        </div>
      </Panel>
    </form>
  );
}
