{"command":"create","path":"/workspace/frontend/src/views/AuditTrail.tsx","file_text":"import { useCallback, useEffect, useState } from 'react';
import { api, ApiError } from '../api/client';
import type { AuditSearchResult } from '../api/types';
import { Field, Notice, Panel, StatusBadge, fmt, shortId } from '../components/common';

const PAGE = 50;

export function AuditTrail() {
  const [action, setAction] = useState('');
  const [entityId, setEntityId] = useState('');
  const [actorId, setActorId] = useState('');
  const [order, setOrder] = useState<'newest_first' | 'oldest_first'>('newest_first');
  const [offset, setOffset] = useState(0);
  const [result, setResult] = useState<AuditSearchResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const search = useCallback(
    async (nextOffset: number) => {
      setBusy(true);
      setError(null);
      try {
        const payload: Record<string, unknown> = { limit: PAGE, offset: nextOffset, order };
        if (action.trim()) payload.action = action.trim();
        if (entityId.trim()) payload.entityId = entityId.trim();
        if (actorId.trim()) payload.actorId = actorId.trim();
        setResult(await api.searchAuditTrail(payload));
        setOffset(nextOffset);
      } catch (err) {
        setError(err instanceof ApiError ? `${err.message} (${err.code})` : 'Search failed.');
      } finally {
        setBusy(false);
      }
    },
    [action, entityId, actorId, order],
  );

  useEffect(() => {
    void search(0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <Panel title="Audit trail">
      <form
        className="grid two"
        onSubmit={(e) => {
          e.preventDefault();
          void search(0);
        }}
      >
        <Field label="Action" hint="For example collect_and_seal_sample or confirm_handoff.">
          <input aria-label="Action" value={action} onChange={(e) => setAction(e.target.value)} />
        </Field>
        <Field label="Request or sample id">
          <input aria-label="Request or sample id" value={entityId} onChange={(e) => setEntityId(e.target.value)} />
        </Field>
        <Field label="Actor id">
          <input aria-label="Actor id" value={actorId} onChange={(e) => setActorId(e.target.value)} />
        </Field>
        <Field label="Order">
          <select
            aria-label="Order"
            value={order}
            onChange={(e) => setOrder(e.target.value as 'newest_first' | 'oldest_first')}
          >
            <option value="newest_first">Newest first</option>
            <option value="oldest_first">Oldest first</option>
          </select>
        </Field>
        <div className="row">
          <button type="submit" disabled={busy}>
            {busy ? 'Searching…' : 'Search audit trail'}
          </button>
          <button
            type="button"
            className="secondary"
            onClick={() => {
              setAction('');
              setEntityId('');
              setActorId('');
            }}
          >
            Clear filters
          </button>
        </div>
      </form>

      {error && <Notice kind="error">{error}</Notice>}

      {result && (
        <>
          <p className="muted">
            Showing {result.returned} of {result.total} audit records (offset {result.offset}).
          </p>
          <table>
            <thead>
              <tr>
                <th>Time</th>
                <th>Actor</th>
                <th>Role</th>
                <th>Action</th>
                <th>Affected item</th>
                <th>Outcome</th>
                <th>Changes</th>
              </tr>
            </thead>
            <tbody>
              {result.entries.map((e) => (
                <tr key={e.auditId}>
                  <td>{fmt(e.occurredAt)}</td>
                  <td className="mono">{shortId(e.actorId)}</td>
                  <td>{(e.actorRole || e.role || '').replace(/_/g, ' ')}</td>
                  <td className="mono">{e.action}</td>
                  <td className="mono">
                    {e.entityType}/{shortId(e.entityId)}
                  </td>
                  <td>
                    <StatusBadge status={e.success ? 'success' : 'failure'} />
                  </td>
                  <td>
                    <details>
                      <summary className="muted">details</summary>
                      <pre>{JSON.stringify(e.details, null, 2)}</pre>
                    </details>
                  </td>
                </tr>
              ))}
              {result.entries.length === 0 && (
                <tr>
                  <td colSpan={7} className="muted">
                    No audit records match this search.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
          <div className="row">
            <button
              type="button"
              className="secondary"
              disabled={busy || offset === 0}
              onClick={() => void search(Math.max(0, offset - PAGE))}
            >
              Previous
            </button>
            <button
              type="button"
              className="secondary"
              disabled={busy || !result.hasMore}
              onClick={() => void search(result.nextOffset ?? offset + PAGE)}
            >
              Next
            </button>
          </div>
        </>
      )}
    </Panel>
  );
}
