{"command":"create","path":"/workspace/frontend/src/views/Admin.tsx","file_text":"import { useCallback, useEffect, useState } from 'react';
import { api, ApiError } from '../api/client';
import { DEFAULT_SAMPLE_TYPES } from '../api/sampleTypes';
import { ROLE_LABELS } from '../api/types';
import type { OperationsState, Role } from '../api/types';
import { Field, Notice, Panel, StatusBadge, shortId } from '../components/common';

const ROLES: Role[] = [
  'administrator',
  'dispatcher',
  'requester',
  'collection_professional',
  'delivery_partner',
  'node_handler',
  'laboratory_team',
];

const FUNCTIONS = ['collection_point', 'transfer_point', 'hub', 'laboratory'] as const;

type Feedback = { kind: 'error' | 'success'; text: string } | null;

export function Admin() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [feedback, setFeedback] = useState<Feedback>(null);

  const load = useCallback(async () => {
    try {
      setOps(await api.readOperationsState());
    } catch (err) {
      setFeedback({
        kind: 'error',
        text: err instanceof ApiError ? `${err.message} (${err.code})` : 'Could not load network.',
      });
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const run = useCallback(
    async (label: string, fn: () => Promise<unknown>) => {
      setFeedback(null);
      try {
        await fn();
        setFeedback({ kind: 'success', text: `${label} succeeded.` });
        await load();
        return true;
      } catch (err) {
        setFeedback({
          kind: 'error',
          text: err instanceof ApiError ? `${label} failed: ${err.message} (${err.code})` : `${label} failed.`,
        });
        return false;
      }
    },
    [load],
  );

  const locations = ops?.locations ?? [];
  const labs = locations.filter((l) => l.functions.laboratory);

  return (
    <>
      {feedback && <Notice kind={feedback.kind}>{feedback.text}</Notice>}

      <CreateUser run={run} locations={locations} />
      <ManageUserAccess run={run} locations={locations} />
      <CreateLocation run={run} />
      <NetworkStatus run={run} ops={ops} />
      <CreateConnection run={run} ops={ops} />
      <SampleTypes run={run} />
      <LaboratoryAcceptance run={run} labs={labs} />
      <CapacityConfig run={run} ops={ops} />
      <WorkerAvailability run={run} ops={ops} />
    </>
  );
}

type Run = (label: string, fn: () => Promise<unknown>) => Promise<boolean>;

function CreateUser({
  run,
  locations,
}: {
  run: Run;
  locations: OperationsState['locations'];
}) {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [fullName, setFullName] = useState('');
  const [roles, setRoles] = useState<Role[]>(['requester']);
  const [qualifications, setQualifications] = useState('');
  const [assignedLocationId, setAssignedLocationId] = useState('');
  const [busy, setBusy] = useState(false);

  const needsLocation = roles.includes('node_handler') || roles.includes('laboratory_team');

  return (
    <Panel title="Create user">
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          setBusy(true);
          const quals = qualifications
            .split(',')
            .map((q) => q.trim())
            .filter(Boolean);
          const ok = await run('Create user', () =>
            api.createUser({
              username,
              initialPassword: password,
              fullName: fullName || undefined,
              roles,
              qualifications: quals,
              certifications: quals.map((code) => ({ code, active: true })),
              active: true,
              ...(needsLocation && assignedLocationId ? { assignedLocationId } : {}),
            }),
          );
          setBusy(false);
          if (ok) {
            setUsername('');
            setPassword('');
            setFullName('');
            setQualifications('');
          }
        }}
      >
        <Field label="Username">
          <input aria-label="Username" value={username} onChange={(e) => setUsername(e.target.value)} required />
        </Field>
        <Field label="Initial password">
          <input
            aria-label="Initial password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </Field>
        <Field label="Full name">
          <input aria-label="Full name" value={fullName} onChange={(e) => setFullName(e.target.value)} />
        </Field>
        <Field
          label="Qualifications"
          hint="Comma separated. A collection professional needs the qualification matching each sample type they collect."
        >
          <input
            aria-label="Qualifications"
            value={qualifications}
            onChange={(e) => setQualifications(e.target.value)}
            placeholder="amber_collector, frost_collector"
          />
        </Field>
        <Field label="Roles">
          <div className="stack">
            {ROLES.map((r) => (
              <label key={r} className="checkbox">
                <input
                  type="checkbox"
                  aria-label={ROLE_LABELS[r]}
                  checked={roles.includes(r)}
                  onChange={(e) =>
                    setRoles((prev) => (e.target.checked ? [...prev, r] : prev.filter((x) => x !== r)))
                  }
                />
                {ROLE_LABELS[r]}
              </label>
            ))}
          </div>
        </Field>
        {needsLocation && (
          <Field label="Assigned node or laboratory" hint="Node and laboratory work is only offered to workers assigned there.">
            <select
              aria-label="Assigned node or laboratory"
              value={assignedLocationId}
              onChange={(e) => setAssignedLocationId(e.target.value)}
            >
              <option value="">Select a location…</option>
              {locations.map((l) => (
                <option key={l.locationId} value={l.locationId}>
                  {l.name}
                </option>
              ))}
            </select>
          </Field>
        )}
        <div>
          <button type="submit" disabled={busy || roles.length === 0}>
            {busy ? 'Creating…' : 'Create user'}
          </button>
        </div>
      </form>
    </Panel>
  );
}

function ManageUserAccess({ run, locations }: { run: Run; locations: OperationsState['locations'] }) {
  const [userId, setUserId] = useState('');
  const [loaded, setLoaded] = useState<Record<string, unknown> | null>(null);
  const [roles, setRoles] = useState<Role[]>([]);
  const [qualifications, setQualifications] = useState('');
  const [active, setActive] = useState(true);
  const [assignedLocationId, setAssignedLocationId] = useState('');
  const [error, setError] = useState<string | null>(null);

  async function lookup() {
    setError(null);
    setLoaded(null);
    try {
      const user = await api.readUser(userId.trim());
      setLoaded(user);
      setRoles(((user.roles as string[]) ?? []) as Role[]);
      setQualifications(((user.qualifications as string[]) ?? []).join(', '));
      setActive(Boolean(user.active));
      setAssignedLocationId(String(user.assignedLocationId ?? ''));
    } catch (err) {
      setError(err instanceof ApiError ? `${err.message} (${err.code})` : 'Could not load user.');
    }
  }

  return (
    <Panel title="Manage roles, certifications and assignment">
      <div className="row">
        <Field label="User id">
          <input aria-label="User id" value={userId} onChange={(e) => setUserId(e.target.value)} />
        </Field>
        <button type="button" className="secondary" onClick={() => void lookup()} disabled={!userId.trim()}>
          Load user
        </button>
      </div>
      {error && <Notice kind="error">{error}</Notice>}
      {loaded && (
        <form
          className="grid two"
          onSubmit={async (e) => {
            e.preventDefault();
            const quals = qualifications
              .split(',')
              .map((q) => q.trim())
              .filter(Boolean);
            await run('Update user access', () =>
              api.updateUserAccess({
                userId: userId.trim(),
                roles,
                qualifications: quals,
                certifications: quals.map((code) => ({ code, active: true })),
                active,
                ...(assignedLocationId ? { assignedLocationId } : {}),
              }),
            );
          }}
        >
          <Field label="Roles">
            <div className="stack">
              {ROLES.map((r) => (
                <label key={r} className="checkbox">
                  <input
                    type="checkbox"
                    aria-label={`${ROLE_LABELS[r]} role`}
                    checked={roles.includes(r)}
                    onChange={(e) =>
                      setRoles((prev) => (e.target.checked ? [...prev, r] : prev.filter((x) => x !== r)))
                    }
                  />
                  {ROLE_LABELS[r]}
                </label>
              ))}
            </div>
          </Field>
          <div className="stack">
            <Field label="Certifications and qualifications" hint="Comma separated codes.">
              <input
                aria-label="Certifications and qualifications"
                value={qualifications}
                onChange={(e) => setQualifications(e.target.value)}
              />
            </Field>
            <Field label="Assigned node or laboratory">
              <select
                aria-label="Assigned node or laboratory for user"
                value={assignedLocationId}
                onChange={(e) => setAssignedLocationId(e.target.value)}
              >
                <option value="">None</option>
                {locations.map((l) => (
                  <option key={l.locationId} value={l.locationId}>
                    {l.name}
                  </option>
                ))}
              </select>
            </Field>
            <label className="checkbox">
              <input
                type="checkbox"
                aria-label="Account active"
                checked={active}
                onChange={(e) => setActive(e.target.checked)}
              />
              Account active
            </label>
            <div>
              <button type="submit">Save access</button>
            </div>
          </div>
        </form>
      )}
    </Panel>
  );
}

function CreateLocation({ run }: { run: Run }) {
  const [name, setName] = useState('');
  const [latitude, setLatitude] = useState('12.97');
  const [longitude, setLongitude] = useState('77.59');
  const [coverageKm, setCoverageKm] = useState('5');
  const [handlingMinutes, setHandlingMinutes] = useState('10');
  const [functions, setFunctions] = useState<string[]>(['collection_point']);

  return (
    <Panel title="Create collection node or laboratory">
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          const ok = await run('Create location', () =>
            api.createLocation({
              name,
              coordinate: { latitude: Number(latitude), longitude: Number(longitude) },
              coverageKm: Number(coverageKm),
              handlingMinutes: Number(handlingMinutes),
              active: true,
              functions,
            }),
          );
          if (ok) setName('');
        }}
      >
        <Field label="Location name">
          <input aria-label="Location name" value={name} onChange={(e) => setName(e.target.value)} required />
        </Field>
        <Field label="Functions" hint="A location may provide several functions at once.">
          <div className="stack">
            {FUNCTIONS.map((f) => (
              <label key={f} className="checkbox">
                <input
                  type="checkbox"
                  aria-label={f.replace(/_/g, ' ')}
                  checked={functions.includes(f)}
                  onChange={(e) =>
                    setFunctions((prev) => (e.target.checked ? [...prev, f] : prev.filter((x) => x !== f)))
                  }
                />
                {f.replace(/_/g, ' ')}
              </label>
            ))}
          </div>
        </Field>
        <Field label="Latitude">
          <input aria-label="Latitude" value={latitude} onChange={(e) => setLatitude(e.target.value)} required />
        </Field>
        <Field label="Longitude">
          <input aria-label="Longitude" value={longitude} onChange={(e) => setLongitude(e.target.value)} required />
        </Field>
        <Field label="Coverage km" hint="Serviceability radius, up to 5 km.">
          <input aria-label="Coverage km" value={coverageKm} onChange={(e) => setCoverageKm(e.target.value)} />
        </Field>
        <Field label="Handling minutes">
          <input
            aria-label="Handling minutes"
            value={handlingMinutes}
            onChange={(e) => setHandlingMinutes(e.target.value)}
          />
        </Field>
        <div>
          <button type="submit" disabled={functions.length === 0}>
            Create location
          </button>
        </div>
      </form>
    </Panel>
  );
}

function NetworkStatus({ run, ops }: { run: Run; ops: OperationsState | null }) {
  if (!ops) return null;
  return (
    <Panel title="Activate or deactivate locations, functions and connections">
      <table>
        <thead>
          <tr>
            <th>Location</th>
            <th>Status</th>
            <th>Functions</th>
          </tr>
        </thead>
        <tbody>
          {ops.locations.map((l) => (
            <tr key={l.locationId}>
              <td>{l.name}</td>
              <td>
                <div className="row">
                  <StatusBadge status={l.active ? 'active' : 'inactive'} />
                  <button
                    type="button"
                    className="secondary"
                    aria-label={`${l.active ? 'Deactivate' : 'Activate'} ${l.name}`}
                    onClick={() => void run('Set location status', () => api.setLocationStatus(l.locationId, !l.active))}
                  >
                    {l.active ? 'Deactivate' : 'Activate'}
                  </button>
                </div>
              </td>
              <td>
                <div className="row wrap">
                  {FUNCTIONS.map((f) => {
                    const on = Boolean(l.functions[f]);
                    return (
                      <button
                        key={f}
                        type="button"
                        className={on ? 'chip on' : 'chip'}
                        aria-label={`${on ? 'Disable' : 'Enable'} ${f.replace(/_/g, ' ')} at ${l.name}`}
                        onClick={() =>
                          void run('Set location function status', () =>
                            api.setLocationFunctionStatus(l.locationId, f, !on),
                          )
                        }
                      >
                        {f.replace(/_/g, ' ')}: {on ? 'on' : 'off'}
                      </button>
                    );
                  })}
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      <h4>Connections</h4>
      <table>
        <thead>
          <tr>
            <th>Route</th>
            <th>Travel</th>
            <th>Cooled</th>
            <th>Status</th>
          </tr>
        </thead>
        <tbody>
          {ops.connections.map((c) => {
            const name = (id: string) => ops.locations.find((l) => l.locationId === id)?.name ?? shortId(id);
            return (
              <tr key={c.connectionId}>
                <td>
                  {name(c.fromLocationId)} → {name(c.toLocationId)}
                </td>
                <td>{c.travelMinutes} min</td>
                <td>{c.cooled ? 'yes' : 'no'}</td>
                <td>
                  <div className="row">
                    <StatusBadge status={c.active ? 'active' : 'inactive'} />
                    <button
                      type="button"
                      className="secondary"
                      aria-label={`${c.active ? 'Deactivate' : 'Activate'} connection ${shortId(c.connectionId)}`}
                      onClick={() =>
                        void run('Set connection status', () => api.setConnectionStatus(c.connectionId, !c.active))
                      }
                    >
                      {c.active ? 'Deactivate' : 'Activate'}
                    </button>
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </Panel>
  );
}

function CreateConnection({ run, ops }: { run: Run; ops: OperationsState | null }) {
  const [fromLocationId, setFrom] = useState('');
  const [toLocationId, setTo] = useState('');
  const [travelMinutes, setTravel] = useState('30');
  const [costUnits, setCost] = useState('1');
  const [cooled, setCooled] = useState(false);

  return (
    <Panel title="Create connection">
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          await run('Create connection', () =>
            api.createConnection({
              fromLocationId,
              toLocationId,
              travelMinutes: Number(travelMinutes),
              costUnits: Number(costUnits),
              cooled,
              active: true,
            }),
          );
        }}
      >
        <Field label="From location">
          <select aria-label="From location" value={fromLocationId} onChange={(e) => setFrom(e.target.value)} required>
            <option value="">Select…</option>
            {(ops?.locations ?? []).map((l) => (
              <option key={l.locationId} value={l.locationId}>
                {l.name}
              </option>
            ))}
          </select>
        </Field>
        <Field label="To location">
          <select aria-label="To location" value={toLocationId} onChange={(e) => setTo(e.target.value)} required>
            <option value="">Select…</option>
            {(ops?.locations ?? []).map((l) => (
              <option key={l.locationId} value={l.locationId}>
                {l.name}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Travel minutes">
          <input aria-label="Travel minutes" value={travelMinutes} onChange={(e) => setTravel(e.target.value)} />
        </Field>
        <Field label="Cost units">
          <input aria-label="Cost units" value={costUnits} onChange={(e) => setCost(e.target.value)} />
        </Field>
        <label className="checkbox">
          <input
            type="checkbox"
            aria-label="Cooled connection"
            checked={cooled}
            onChange={(e) => setCooled(e.target.checked)}
          />
          Cooled transport available
        </label>
        <div>
          <button type="submit" disabled={!fromLocationId || !toLocationId}>
            Create connection
          </button>
        </div>
      </form>
    </Panel>
  );
}

function SampleTypes({ run }: { run: Run }) {
  const [sampleTypeId, setSampleTypeId] = useState(DEFAULT_SAMPLE_TYPES[0].sampleTypeId);
  const [containerType, setContainerType] = useState(DEFAULT_SAMPLE_TYPES[0].containerType);
  const [tempMin, setTempMin] = useState(String(DEFAULT_SAMPLE_TYPES[0].temperatureMinC));
  const [tempMax, setTempMax] = useState(String(DEFAULT_SAMPLE_TYPES[0].temperatureMaxC));
  const [name, setName] = useState('');
  const [newContainer, setNewContainer] = useState('standard');
  const [newMin, setNewMin] = useState('15');
  const [newMax, setNewMax] = useState('30');
  const [qualification, setQualification] = useState('');
  const [requiresCooledRoute, setRequiresCooledRoute] = useState(false);
  const [batchingAllowed, setBatchingAllowed] = useState(true);

  return (
    <Panel title="Sample types and handling attributes">
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          await run('Update sample type', () =>
            api.updateSampleType({
              sampleTypeId,
              containerType,
              temperatureMinC: Number(tempMin),
              temperatureMaxC: Number(tempMax),
            }),
          );
        }}
      >
        <Field label="Existing sample type">
          <select
            aria-label="Existing sample type"
            value={sampleTypeId}
            onChange={(e) => {
              setSampleTypeId(e.target.value);
              const t = DEFAULT_SAMPLE_TYPES.find((x) => x.sampleTypeId === e.target.value);
              if (t) {
                setContainerType(t.containerType);
                setTempMin(String(t.temperatureMinC));
                setTempMax(String(t.temperatureMaxC));
              }
            }}
          >
            {DEFAULT_SAMPLE_TYPES.map((t) => (
              <option key={t.sampleTypeId} value={t.sampleTypeId}>
                {t.name}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Container type">
          <input
            aria-label="Container type"
            value={containerType}
            onChange={(e) => setContainerType(e.target.value)}
          />
        </Field>
        <Field label="Minimum temperature C">
          <input aria-label="Minimum temperature C" value={tempMin} onChange={(e) => setTempMin(e.target.value)} />
        </Field>
        <Field label="Maximum temperature C">
          <input aria-label="Maximum temperature C" value={tempMax} onChange={(e) => setTempMax(e.target.value)} />
        </Field>
        <div>
          <button type="submit">Update sample type</button>
        </div>
      </form>

      <h4>Create a new sample type</h4>
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          const ok = await run('Create sample type', () =>
            api.createSampleType({
              name,
              containerType: newContainer,
              temperatureMinC: Number(newMin),
              temperatureMaxC: Number(newMax),
              qualifiedCollectorRequired: Boolean(qualification),
              ...(qualification ? { requiredQualification: qualification } : {}),
              requiresCooledRoute,
              batchingAllowed,
            }),
          );
          if (ok) setName('');
        }}
      >
        <Field label="New sample type name">
          <input aria-label="New sample type name" value={name} onChange={(e) => setName(e.target.value)} required />
        </Field>
        <Field label="New container type">
          <input
            aria-label="New container type"
            value={newContainer}
            onChange={(e) => setNewContainer(e.target.value)}
          />
        </Field>
        <Field label="New minimum temperature C">
          <input
            aria-label="New minimum temperature C"
            value={newMin}
            onChange={(e) => setNewMin(e.target.value)}
          />
        </Field>
        <Field label="New maximum temperature C">
          <input
            aria-label="New maximum temperature C"
            value={newMax}
            onChange={(e) => setNewMax(e.target.value)}
          />
        </Field>
        <Field label="Required qualification" hint="Leave empty if no qualified collector is required.">
          <input
            aria-label="Required qualification"
            value={qualification}
            onChange={(e) => setQualification(e.target.value)}
          />
        </Field>
        <div className="stack">
          <label className="checkbox">
            <input
