              onChange={(e) => setRequiresCooledRoute(e.target.checked)}
            />
            Requires cooled storage and transport
          </label>
          <label className="checkbox">
            <input
              type="checkbox"
              aria-label="Batching allowed"
              checked={batchingAllowed}
              onChange={(e) => setBatchingAllowed(e.target.checked)}
            />
            May wait to be combined into a batch
          </label>
          <div>
            <button type="submit">Create sample type</button>
          </div>
        </div>
      </form>
    </Panel>
  );
}

function LaboratoryAcceptance({ run, labs }: { run: Run; labs: OperationsState['locations'] }) {
  const [laboratoryId, setLaboratoryId] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState(DEFAULT_SAMPLE_TYPES[0].sampleTypeId);
  const [accepts, setAccepts] = useState(true);

  return (
    <Panel title="Laboratory capabilities">
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          await run('Configure laboratory acceptance', () =>
            api.configureLaboratoryAcceptance(laboratoryId, sampleTypeId, accepts),
          );
        }}
      >
        <Field label="Laboratory">
          <select aria-label="Laboratory" value={laboratoryId} onChange={(e) => setLaboratoryId(e.target.value)} required>
            <option value="">Select a laboratory…</option>
            {labs.map((l) => (
              <option key={l.locationId} value={l.locationId}>
                {l.name}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Sample type accepted">
          <select
            aria-label="Sample type accepted"
            value={sampleTypeId}
            onChange={(e) => setSampleTypeId(e.target.value)}
          >
            {DEFAULT_SAMPLE_TYPES.map((t) => (
              <option key={t.sampleTypeId} value={t.sampleTypeId}>
                {t.name}
              </option>
            ))}
          </select>
        </Field>
        <label className="checkbox">
          <input
            type="checkbox"
            aria-label="Accepts this sample type"
            checked={accepts}
            onChange={(e) => setAccepts(e.target.checked)}
          />
          This laboratory accepts the selected sample type
        </label>
        <div>
          <button type="submit" disabled={!laboratoryId}>
            Save capability
          </button>
        </div>
      </form>
    </Panel>
  );
}

function CapacityConfig({ run, ops }: { run: Run; ops: OperationsState | null }) {
  const [resourceId, setResourceId] = useState('');
  const [capacityUnits, setCapacityUnits] = useState('10');
  const [cooledCapacityUnits, setCooled] = useState('5');

  const resources = [
    ...(ops?.locations ?? []).map((l) => ({ id: l.locationId, label: `${l.name} (location)` })),
    ...(ops?.connections ?? []).map((c) => ({
      id: c.connectionId,
      label: `${ops?.locations.find((l) => l.locationId === c.fromLocationId)?.name ?? shortId(c.fromLocationId)} → ${
        ops?.locations.find((l) => l.locationId === c.toLocationId)?.name ?? shortId(c.toLocationId)
      } (connection)`,
    })),
  ];

  return (
    <Panel title="Configure regular and cooled capacity">
      <form
        className="grid two"
        onSubmit={async (e) => {
          e.preventDefault();
          await run('Configure capacity', () =>
            api.configureCapacity(resourceId, Number(capacityUnits), Number(cooledCapacityUnits)),
