      >
        <Field label="Capacity pool" hint="A node, a laboratory, or a transport connection.">
          <select aria-label="Capacity pool" value={resourceId} onChange={(e) => setResourceId(e.target.value)} required>
            <option value="">Select a capacity pool…</option>
            {resources.map((r) => (
              <option key={r.id} value={r.id}>
                {r.label}
              </option>
            ))}
          </select>
        </Field>
        <Field label="Regular capacity units">
          <input
            aria-label="Regular capacity units"
            value={capacityUnits}
            onChange={(e) => setCapacityUnits(e.target.value)}
          />
        </Field>
        <Field label="Cooled capacity units">
          <input
            aria-label="Cooled capacity units"
            value={cooledCapacityUnits}
            onChange={(e) => setCooled(e.target.value)}
          />
        </Field>
        <div>
          <button type="submit" disabled={!resourceId}>
            Save capacity
          </button>
        </div>
      </form>
    </Panel>
  );
}

function WorkerAvailability({ run, ops }: { run: Run; ops: OperationsState | null }) {
  return (
    <Panel title="Worker availability">
      <table>
        <thead>
          <tr>
            <th>Worker</th>
            <th>Status</th>
            <th>Capacity units</th>
            <th>Assignments</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {(ops?.workers ?? []).map((w) => (
            <tr key={w.workerId}>
