{"command":"create","path":"/workspace/frontend/src/views/JourneyDetail.tsx","file_text":"import { useCallback, useEffect, useState } from 'react';
import { Link, useParams } from 'react-router-dom';
import { api, ApiError } from '../api/client';
import type { JourneyPlan } from '../api/types';
import { Field, Notice, Panel, StatusBadge, fmt, shortId } from '../components/common';
import { useSession } from '../state/session';

type Feedback = { kind: 'error' | 'success'; text: string } | null;

export function JourneyDetail() {
  const { journeyId = '' } = useParams();
  const { user } = useSession();
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [feedback, setFeedback] = useState<Feedback>(null);
  const [error, setError] = useState<string | null>(null);

  const canReplan = user?.activeRole === 'dispatcher' || user?.activeRole === 'administrator';

  const load = useCallback(async () => {
    setError(null);
    try {
      setPlan(await api.readJourneyPlan(journeyId));
    } catch (err) {
      setError(err instanceof ApiError ? `${err.message} (${err.code})` : 'Could not load the journey.');
    }
  }, [journeyId]);

  useEffect(() => {
    void load();
  }, [load]);

  const run = useCallback(
    async (label: string, fn: () => Promise<unknown>) => {
      setFeedback(null);
      try {
        await fn();
        setFeedback({ kind: 'success', text: `${label} succeeded.` });
      } catch (err) {
        // A rejected plan change leaves the current plan in place, so we simply re-read it.
        setFeedback({
          kind: 'error',
          text: err instanceof ApiError ? `${label} was rejected: ${err.message} (${err.code})` : `${label} failed.`,
        });
      }
      await load();
    },
    [load],
  );

  if (error) return <Notice kind="error">{error}</Notice>;
  if (!plan) return <p className="muted">Loading journey…</p>;

  return (
    <>
      {feedback && <Notice kind={feedback.kind}>{feedback.text}</Notice>}

      <Panel
        title={`Journey ${shortId(plan.journeyId)}`}
        actions={
          <button type="button" onClick={() => void load()}>
            Refresh
          </button>
        }
      >
        <dl className="kv">
          <dt>Status</dt>
          <dd>
            <StatusBadge status={plan.status} />
          </dd>
          <dt>Plan version</dt>
          <dd>{plan.planVersion}</dd>
          <dt>Route mode</dt>
          <dd>{plan.routeMode}</dd>
          <dt>Estimated delivery</dt>
          <dd>{fmt(plan.estimatedDeliveryAt)}</dd>
          <dt>Samples</dt>
          <dd>
            {plan.sampleIds.map((id) => (
              <Link key={id} to={`/samples/${id}`} className="mono" style={{ marginRight: 8 }}>
                {shortId(id)}
              </Link>
            ))}
          </dd>
          {plan.parentJourneyId && (
            <>
              <dt>Parent journey</dt>
              <dd className="mono">
                <Link to={`/journeys/${plan.parentJourneyId}`}>{shortId(plan.parentJourneyId)}</Link>
              </dd>
            </>
          )}
          {plan.replanStatus && (
            <>
              <dt>Replan status</dt>
              <dd>
                <StatusBadge status={plan.replanStatus} />
              </dd>
            </>
          )}
        </dl>
      </Panel>

      <Panel title="Ordered stops">
        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Type</th>
              <th>Location</th>
              <th>Estimated</th>
              <th>Completed</th>
            </tr>
          </thead>
          <tbody>
            {plan.orderedStops.map((s) => (
              <tr key={s.stopId}>
                <td>{s.sequence}</td>
                <td>
                  <StatusBadge status={s.stopType} />
                </td>
                <td className="mono">{shortId(s.locationId)}</td>
                <td>{fmt(s.estimatedAt)}</td>
                <td>{s.completedAt ? fmt(s.completedAt) : <span className="muted">not yet</span>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Panel>

      <Panel title="Legs, including collection and each transport leg">
        <table>
          <thead>
            <tr>
              <th>#</th>
              <th>Assignment</th>
              <th>Status</th>
              <th>From</th>
              <th>To</th>
              <th>Worker</th>
            </tr>
          </thead>
          <tbody>
            {plan.legs.map((l) => (
              <tr key={l.assignmentId}>
                <td>{l.sequence}</td>
                <td className="mono">{shortId(l.assignmentId)}</td>
                <td>
                  <StatusBadge status={l.status} />
                </td>
                <td className="mono">{shortId(l.fromLocationId)}</td>
                <td className="mono">{shortId(l.toLocationId)}</td>
                <td className="mono">{shortId(l.workerId)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </Panel>

      {canReplan && <ReplanControls plan={plan} run={run} />}
    </>
  );
}

function ReplanControls({
  plan,
  run,
}: {
  plan: JourneyPlan;
  run: (label: string, fn: () => Promise<unknown>) => Promise<void>;
}) {
  const [reason, setReason] = useState('');
  const [splitSamples, setSplitSamples] = useState<string[]>([]);
  const [mergeSources, setMergeSources] = useState('');

  return (
    <Panel title="Change unfinished work">
      <p className="muted">
        Every change is checked against plan version {plan.planVersion}. Completed assignments, stops and confirmed
        custody are never rewritten, and a change that fails validation is rejected so the current plan stays in place.
      </p>

      <Field label="Reason">
        <input aria-label="Reason" value={reason} onChange={(e) => setReason(e.target.value)} />
      </Field>

      <div className="row wrap">
        <button
          type="button"
          onClick={() =>
            void run('Reroute journey', () =>
              api.rerouteJourney({
                journeyId: plan.journeyId,
                expectedPlanVersion: plan.planVersion,
                ...(reason ? { reason } : {}),
              }),
            )
          }
        >
          Reroute journey
        </button>
        <button
          type="button"
          className="danger"
          onClick={() =>
            void run('Cancel journey', () =>
              api.cancelJourney(plan.journeyId, plan.planVersion, reason || undefined),
            )
          }
        >
          Cancel journey
        </button>
      </div>

      <h4>Split samples into a new journey</h4>
      <div className="stack">
        {plan.sampleIds.map((id) => (
          <label key={id} className="checkbox">
            <input
              type="checkbox"
              aria-label={`Split sample ${shortId(id)}`}
              checked={splitSamples.includes(id)}
              onChange={(e) =>
                setSplitSamples((prev) => (e.target.checked ? [...prev, id] : prev.filter((x) => x !== id)))
              }
            />
            <span className="mono">{shortId(id)}</span>
          </label>
        ))}
        <div>
          <button
            type="button"
            disabled={splitSamples.length === 0}
            onClick={() =>
              void run('Split journey', () =>
                api.splitJourney({
                  journeyId: plan.journeyId,
                  expectedPlanVersion: plan.planVersion,
                  sampleIds: splitSamples,
                }),
              )
            }
          >
            Split journey
          </button>
        </div>
      </div>

      <h4>Merge other journeys into this one</h4>
      <Field label="Source journey ids" hint="Comma separated journey ids to merge into this journey.">
        <input
          aria-label="Source journey ids"
          value={mergeSources}
          onChange={(e) => setMergeSources(e.target.value)}
        />
      </Field>
      <div>
        <button
          type="button"
          disabled={!mergeSources.trim()}
          onClick={() =>
            void run('Merge journeys', () =>
              api.mergeJourneys({
                targetJourneyId: plan.journeyId,
                expectedPlanVersion: plan.planVersion,
                sourceJourneyIds: mergeSources
                  .split(',')
                  .map((s) => s.trim())
                  .filter(Boolean),
              }),
            )
          }
        >
          Merge journeys
        </button>
      </div>
    </Panel>
  );
}
