{"command":"create","path":"/workspace/frontend/src/views/Disruptions.tsx","file_text":"import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { api, ApiError } from '../api/client';
import type { OperationsState } from '../api/types';
import { Field, Notice, Panel, StatusBadge, shortId } from '../components/common';

const RESOURCE_TYPES = ['location', 'node', 'laboratory', 'connection', 'route', 'worker', 'capacity'] as const;

interface DisruptionResult {
  disruptionId: string;
  affectedSampleIds: string[];
  replacementPlanIds: string[];
  replanStatus: string;
}

const REPLAN_TEXT: Record<string, string> = {
  not_required: 'No unfinished work needed replanning.',
  replaced: 'Unfinished work was replanned onto a replacement plan.',
  expired: 'No valid route could meet the deadline, so affected samples were marked expired.',
  exception: 'Replanning raised an exception that needs dispatcher attention.',
};

export function Disruptions() {
  const [ops, setOps] = useState<OperationsState | null>(null);
  const [resourceType, setResourceType] = useState<(typeof RESOURCE_TYPES)[number]>('connection');
  const [resourceId, setResourceId] = useState('');
  const [reason, setReason] = useState('');
  const [result, setResult] = useState<DisruptionResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    void (async () => {
      try {
        setOps(await api.readOperationsState());
      } catch {
        setOps(null);
      }
    })();
  }, []);

  const options =
    resourceType === 'worker'
      ? (ops?.workers ?? []).map((w) => ({ id: w.workerId, label: w.fullName || shortId(w.workerId) }))
      : resourceType === 'connection' || resourceType === 'route'
        ? (ops?.connections ?? []).map((c) => ({
            id: c.connectionId,
            label: `${ops?.locations.find((l) => l.locationId === c.fromLocationId)?.name ?? shortId(c.fromLocationId)} → ${
              ops?.locations.find((l) => l.locationId === c.toLocationId)?.name ?? shortId(c.toLocationId)
            }`,
          }))
        : (ops?.locations ?? []).map((l) => ({ id: l.locationId, label: l.name }));

  return (
    <>
      <Panel title="Report a disruption and replan">
        <p className="muted">
          Reporting a disruption keeps the current holder of each sample unchanged, preserves completed assignments,
          stops and handoffs, and replans only unfinished work.
        </p>
        <form
          className="grid two"
          onSubmit={async (e) => {
            e.preventDefault();
            setBusy(true);
            setError(null);
            setResult(null);
            try {
              const data = (await api.reportDisruption({
                resourceType,
                resourceId,
                ...(reason ? { reason } : {}),
                occurredAt: new Date().toISOString(),
              })) as unknown as DisruptionResult;
              setResult(data);
            } catch (err) {
              setError(err instanceof ApiError ? `${err.message} (${err.code})` : 'Could not report the disruption.');
            } finally {
              setBusy(false);
            }
          }}
        >
          <Field label="Resource type">
            <select
              aria-label="Resource type"
              value={resourceType}
              onChange={(e) => {
                setResourceType(e.target.value as (typeof RESOURCE_TYPES)[number]);
                setResourceId('');
              }}
            >
              {RESOURCE_TYPES.map((t) => (
                <option key={t} value={t}>
                  {t}
                </option>
              ))}
            </select>
          </Field>
          <Field label="Unavailable resource">
            <select
              aria-label="Unavailable resource"
              value={resourceId}
              onChange={(e) => setResourceId(e.target.value)}
              required
            >
              <option value="">Select a resource…</option>
              {options.map((o) => (
                <option key={o.id} value={o.id}>
                  {o.label}
                </option>
              ))}
            </select>
          </Field>
          <Field label="Reason">
            <input aria-label="Reason" value={reason} onChange={(e) => setReason(e.target.value)} />
          </Field>
          <div>
            <button type="submit" disabled={busy || !resourceId}>
              {busy ? 'Replanning…' : 'Report disruption'}
            </button>
          </div>
        </form>

        {error && <Notice kind="error">{error}</Notice>}

        {result && (
          <Notice kind={result.replanStatus === 'replaced' || result.replanStatus === 'not_required' ? 'success' : 'info'}>
            <div>
              <strong>Replan status: {result.replanStatus}</strong>
              <div>{REPLAN_TEXT[result.replanStatus]}</div>
              <div>
                Affected samples:{' '}
                {result.affectedSampleIds.length === 0
                  ? 'none'
                  : result.affectedSampleIds.map((id) => (
                      <Link key={id} to={`/samples/${id}`} className="mono" style={{ marginRight: 8 }}>
                        {shortId(id)}
                      </Link>
                    ))}
              </div>
              <div>
                Replacement plans:{' '}
                {result.replacementPlanIds.length === 0
                  ? 'none'
                  : result.replacementPlanIds.map((id) => (
                      <Link key={id} to={`/journeys/${id}`} className="mono" style={{ marginRight: 8 }}>
                        {shortId(id)}
                      </Link>
                    ))}
              </div>
            </div>
          </Notice>
        )}
      </Panel>

      <Panel title={`Open exceptions (${ops?.exceptions.length ?? 0})`}>
        {(ops?.exceptions ?? []).length === 0 ? (
          <p className="muted">No open exceptions.</p>
        ) : (
          <table>
            <thead>
              <tr>
                <th>Sample</th>
                <th>Kind</th>
                <th>Reason</th>
              </tr>
            </thead>
            <tbody>
              {(ops?.exceptions ?? []).map((e, i) => (
                <tr key={String(e.sampleId ?? i)}>
                  <td className="mono">
                    {e.sampleId ? (
                      <Link to={`/samples/${String(e.sampleId)}`}>{shortId(String(e.sampleId))}</Link>
                    ) : (
                      '—'
                    )}
                  </td>
                  <td>
                    <StatusBadge status={String(e.kind ?? 'exception')} />
                  </td>
                  <td>{String(e.reason ?? '—')}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </Panel>
    </>
  );
