{"command":"create","path":"/workspace/scripts/verify-openapi.py","file_text":"#!/usr/bin/env python3
"""Verify app-setup/openapi.json is valid and structurally identical to the pinned contract.

Documentation-only fields (descriptions, summaries, info, servers, securityScheme
description) are allowed to differ; anything that defines the wire format must not.
"""
import json
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
contract = json.loads((ROOT / 'contracts' / 'openapi.contract.json').read_text())
mine = json.loads((ROOT / 'app-setup' / 'openapi.json').read_text())

DOC_KEYS = {'description', 'summary', 'example', 'examples', 'title'}
problems = []


def strip(node):
    """Drop documentation-only keys so only wire-format structure remains."""
    if isinstance(node, dict):
        return {k: strip(v) for k, v in node.items() if k not in DOC_KEYS}
    if isinstance(node, list):
        return [strip(v) for v in node]
    return node


# 1. Must be a valid JSON object using OpenAPI 3.0/3.1.
version = mine.get('openapi', '')
if not version.startswith(('3.0', '3.1')):
    problems.append(f'openapi version must be 3.0.x or 3.1.x, got {version!r}')

# 2. Paths, methods, bodies, responses and schemas must match the contract exactly.
if set(mine['paths']) != set(contract['paths']):
    problems.append(f'path set differs: only-contract={set(contract["paths"]) - set(mine["paths"])} '
                    f'only-mine={set(mine["paths"]) - set(contract["paths"])}')

for path, ops in contract['paths'].items():
    for method, cop in ops.items():
        if method not in ('get', 'post', 'put', 'patch', 'delete'):
            continue
        mop = mine['paths'].get(path, {}).get(method)
        if mop is None:
            problems.append(f'missing operation {method.upper()} {path}')
            continue
        if cop.get('operationId') != mop.get('operationId'):
            problems.append(f'{method.upper()} {path}: operationId changed')
        for field in ('requestBody', 'parameters', 'security'):
            if strip(cop.get(field)) != strip(mop.get(field)):
                problems.append(f'{method.upper()} {path}: {field} differs from contract')
        if set(cop.get('responses', {})) != set(mop.get('responses', {})):
            problems.append(f'{method.upper()} {path}: response codes differ')
        for code, cresp in cop.get('responses', {}).items():
            mresp = mop['responses'].get(code, {})
            if strip(cresp.get('content')) != strip(mresp.get('content')):
                problems.append(f'{method.upper()} {path} {code}: response schema differs')

if strip(contract['components']['schemas']) != strip(mine['components']['schemas']):
    problems.append('components.schemas differ from contract')

# 3. Deliverable requirements: unique operationIds, auth scheme, documentation present.
ids = [op['operationId'] for ops in mine['paths'].values() for m, op in ops.items()
       if m in ('get', 'post', 'put', 'patch', 'delete')]
if len(ids) != len(set(ids)):
    problems.append('operationIds are not unique')

if mine.get('components', {}).get('securitySchemes', {}).get('BearerAuth', {}).get('scheme') != 'bearer':
    problems.append('BearerAuth security scheme missing')

for path, ops in mine['paths'].items():
    for method, op in ops.items():
        if method not in ('get', 'post', 'put', 'patch', 'delete'):
            continue
        if not op.get('description'):
            problems.append(f'{method.upper()} {path}: missing description')
        for code, resp in op.get('responses', {}).items():
            if not resp.get('description'):
                problems.append(f'{method.upper()} {path} {code}: missing response description')

# 4. The manifest must line up with the document and use loopback URLs.
manifest = json.loads((ROOT / 'app-setup' / 'manifest.json').read_text())
if manifest['initialAdmin']['loginOperationId'] not in ids:
    problems.append('manifest initialAdmin.loginOperationId is not an operationId in openapi.json')
for name, url in manifest['urls'].items():
    if '127.0.0.1' not in url:
        problems.append(f'manifest url {name} is not loopback: {url}')

print(f'operations: {len(ids)}')
if problems:
    print('FAILURES:')
    for p in problems:
        print(' -', p)
    sys.exit(1)
print('OK: openapi.json matches the pinned contract and the manifest is consistent.')
","security_risk":"LOW","summary":"Create OpenAPI verification script"}

