{"command":"create","path":"/workspace/backend/internal/app/planning_test.go","file_text":"package app

import (
	"context"
	"testing"
	"time"

	"github.com/google/uuid"
)

// buildTestGraph wires a small network in memory. buildPlan is pure with respect to the
// graph, so planning can be exercised without a database.
func buildTestGraph(locs []*Location, conns []*Connection,
	accepted map[uuid.UUID]map[uuid.UUID]bool, st *SampleType) *networkGraph {
	g := &networkGraph{
		locations:   map[uuid.UUID]*Location{},
		outgoing:    map[uuid.UUID][]*Connection{},
		connByPair:  map[[2]uuid.UUID]*Connection{},
		acceptedBy:  accepted,
		sampleTypes: map[uuid.UUID]*SampleType{st.ID: st},
	}
	for _, l := range locs {
		g.locations[l.ID] = l
	}
	for _, c := range conns {
		g.outgoing[c.FromLocationID] = append(g.outgoing[c.FromLocationID], c)
		g.connByPair[[2]uuid.UUID{c.FromLocationID, c.ToLocationID}] = c
	}
	return g
}

func testCollectionPoint(name string, lat, lon float64) *Location {
	return &Location{
		ID: uuid.New(), Name: name,
		Coordinate:    Coordinate{Latitude: lat, Longitude: lon},
		CoverageKm:    4.5,
		Active:        true,
		Functions:     LocationFunctionStates{CollectionPoint: true},
		CapacityUnits: 10, CooledCapacityUnits: 10,
	}
}

// TestBuildPlanTriesEveryCollectionPointInRange guards against a nearer entry node with
// no usable onward route masking a farther one that can still deliver the sample.
// Serviceability must reflect the network as a whole, not just the closest node.
func TestBuildPlanTriesEveryCollectionPointInRange(t *testing.T) {
	st := &SampleType{ID: uuid.New(), Name: "Amber", ContainerType: "standard",
		TemperatureMinC: 2, TemperatureMaxC: 30}

	origin := Coordinate{Latitude: 14.50, Longitude: 78.50}
	// ~0.5 km from the origin, with no outbound connection.
	deadEnd := testCollectionPoint("near-dead-end", 14.5045, 78.50)
	// ~2 km from the origin, connected to the laboratory.
	routable := testCollectionPoint("far-routable", 14.518, 78.50)
	lab := &Location{
		ID: uuid.New(), Name: "lab",
		Coordinate:    Coordinate{Latitude: 14.65, Longitude: 78.50},
		CoverageKm:    3,
		Active:        true,
		Functions:     LocationFunctionStates{Laboratory: true},
		CapacityUnits: 10, CooledCapacityUnits: 10,
	}
	conn := &Connection{ID: uuid.New(), FromLocationID: routable.ID, ToLocationID: lab.ID,
		TravelMinutes: 25, CostUnits: 5, Cooled: true, Active: true,
		CapacityUnits: 10, CooledCapacityUnits: 10}
	accepted := map[uuid.UUID]map[uuid.UUID]bool{lab.ID: {st.ID: true}}

	now := time.Now().UTC()
	req := planRequest{
		Origin: origin, OriginType: "home", SampleType: st,
		CollectionAt: now, Deadline: now.Add(10 * time.Hour),
	}
	s := &Server{}

	// The nearer dead end is listed first, so a nearest-only planner would give up here.
	g := buildTestGraph([]*Location{deadEnd, routable, lab}, []*Connection{conn}, accepted, st)
	p, err := s.buildPlan(context.Background(), g, req)
	if err != nil {
		t.Fatalf("buildPlan: %v", err)
	}
	if !p.Serviceable {
		t.Fatalf("expected serviceable via the farther routable collection point, got reason %q", p.Reason)
	}
	if p.StartNodeID != routable.ID {
		t.Errorf("start node = %v, want the routable collection point %v", p.StartNodeID, routable.ID)
	}
	if p.LaboratoryID != lab.ID {
		t.Errorf("laboratory = %v, want %v", p.LaboratoryID, lab.ID)
	}
}

// TestBuildPlanReportsMostInformativeReason checks that when no entry node works, the
// reported reason is the one from the node that progressed furthest, rather than the
// reason from whichever node happened to be nearest.
func TestBuildPlanReportsMostInformativeReason(t *testing.T) {
	st := &SampleType{ID: uuid.New(), Name: "Amber", ContainerType: "standard",
		TemperatureMinC: 2, TemperatureMaxC: 30}

	origin := Coordinate{Latitude: 14.50, Longitude: 78.50}
	deadEnd := testCollectionPoint("near-dead-end", 14.5045, 78.50)
	routable := testCollectionPoint("far-routable", 14.518, 78.50)
	lab := &Location{
		ID: uuid.New(), Name: "lab",
		Coordinate:    Coordinate{Latitude: 14.65, Longitude: 78.50},
		CoverageKm:    3,
		Active:        true,
		Functions:     LocationFunctionStates{Laboratory: true},
		CapacityUnits: 10, CooledCapacityUnits: 10,
	}
	// Travel time makes the deadline unreachable from the only routable entry node.
	conn := &Connection{ID: uuid.New(), FromLocationID: routable.ID, ToLocationID: lab.ID,
		TravelMinutes: 600, CostUnits: 5, Cooled: true, Active: true,
		CapacityUnits: 10, CooledCapacityUnits: 10}
	accepted := map[uuid.UUID]map[uuid.UUID]bool{lab.ID: {st.ID: true}}

	now := time.Now().UTC()
	req := planRequest{
		Origin: origin, OriginType: "home", SampleType: st,
		CollectionAt: now, Deadline: now.Add(1 * time.Hour),
	}
	g := buildTestGraph([]*Location{deadEnd, routable, lab}, []*Connection{conn}, accepted, st)

	p, err := (&Server{}).buildPlan(context.Background(), g, req)
	if err != nil {
		t.Fatalf("buildPlan: %v", err)
	}
	if p.Serviceable {
		t.Fatal("expected the plan to be unserviceable")
	}
	if p.Reason != reasonDeadlineUnreachable {
		t.Errorf("reason = %q, want %q", p.Reason, reasonDeadlineUnreachable)
	}
}

// TestBuildPlanOutsideCoverage confirms an origin beyond every collection point's
// coverage radius is reported as outside the service coverage.
func TestBuildPlanOutsideCoverage(t *testing.T) {
	st := &SampleType{ID: uuid.New(), Name: "Amber", ContainerType: "standard",
		TemperatureMinC: 2, TemperatureMaxC: 30}
	cp := testCollectionPoint("cp", 14.50, 78.50)
	accepted := map[uuid.UUID]map[uuid.UUID]bool{}
	g := buildTestGraph([]*Location{cp}, nil, accepted, st)

	now := time.Now().UTC()
	p, err := (&Server{}).buildPlan(context.Background(), g, planRequest{
		Origin: Coordinate{Latitude: 20.0, Longitude: 78.50}, OriginType: "home",
		SampleType: st, CollectionAt: now, Deadline: now.Add(10 * time.Hour),
	})
	if err != nil {
		t.Fatalf("buildPlan: %v", err)
	}
	if p.Serviceable || p.Reason != reasonOutsideCoverage {
		t.Errorf("got serviceable=%v reason=%q, want unserviceable %q",
			p.Serviceable, p.Reason, reasonOutsideCoverage)
	}
}
